def _get_sector_names_from_root(root: str, ContextInfo=None) -> List[str]:
    """根据根目录名获取板块名称列表。

    优先使用 ContextInfo.get_sector_list(root)，否则回退到全局 get_sector_list(root)。
    预期返回类似 ["['食品安全', '旅游', ...]", '[]'] 结构，取第一个元素并做 ast.literal_eval。
    任意异常时返回空列表，不抛出到上层。
    """
    try:
        sector_func = None
        try:
            if ContextInfo is not None and hasattr(ContextInfo, 'get_sector_list'):
                sector_func = ContextInfo.get_sector_list
        except Exception:
            sector_func = None
        if sector_func is None:
            sector_func = globals().get('get_sector_list')

        if not callable(sector_func):
            return []

        res = sector_func(root)
        if not isinstance(res, (list, tuple)) or not res:
            return []

        first = res[0]
        if isinstance(first, str):
            try:
                parsed = ast.literal_eval(first)
                if isinstance(parsed, (list, tuple)):
                    return [str(x) for x in parsed]
            except Exception:
                return []
        # 如果第一个元素本身就是列表/元组
        if isinstance(first, (list, tuple)):
            return [str(x) for x in first]

        return []
    except Exception:
        return []


def get_all_t_concepts(ContextInfo=None) -> List[str]:
    """返回 T概念 下的全部板块名称列表。"""
    return _get_sector_names_from_root('T概念', ContextInfo)


