def get_core_t_concepts(ContextInfo=None) -> List[str]:
    """构建一篮子核心T概念池：当前策略改为**覆盖所有 T 概念**。

    早期版本通过 keyword_groups 从全部 T 概念里筛一小撮“核心主题”。
    现在根据需求，核心池直接等于所有 T 概念，便于在日志和打分中完整观察全市场概念分布。
    """
    try:
        all_t = get_all_t_concepts(ContextInfo) or []
        if not all_t:
            return []

        # 统一转成字符串并去重排序
        core_set = set()
        for name in all_t:
            try:
                core_set.add(str(name))
            except Exception:
                continue
        return sorted(core_set)
    except Exception:
        return []


_CORE_CONCEPT_WEIGHTS_CACHE: Dict[str, float] = None


def _build_core_concept_weights(ContextInfo=None) -> Dict[str, float]:
    global _CORE_CONCEPT_WEIGHTS_CACHE
    if _CORE_CONCEPT_WEIGHTS_CACHE is not None:
        return _CORE_CONCEPT_WEIGHTS_CACHE

    core_list = get_core_t_concepts(ContextInfo) or []
    if not core_list:
        _CORE_CONCEPT_WEIGHTS_CACHE = {}
        return _CORE_CONCEPT_WEIGHTS_CACHE

    tech_keywords = ['半导体', '芯片', '集成电路', '人工智能', '云计算', '大数据', '工业互联网', '5G', '消费电子']
    energy_keywords = ['新能源汽车', '锂电池', '光伏', '储能', '氢能源']
    medical_keywords = ['医疗', '医药', '创新药', '疫苗', '医疗器械']
    region_keywords = ['自贸区', '粤港澳', '长三角', '京津冀', '雄安', '乡村振兴', '一带一路']

    raw_weights: Dict[str, float] = {}
    for name in core_list:
        try:
            n = str(name)
        except Exception:
            continue
        base = 0.0
        if any(kw in n for kw in tech_keywords):
            base += 2.0
        if any(kw in n for kw in energy_keywords):
            base += 2.0
        if any(kw in n for kw in medical_keywords):
            base += 2.0
        if any(kw in n for kw in region_keywords):
            base += 1.0
        if n in ('食品安全', '旅游'):
            base += 1.0
        if base <= 0.0:
            base = 1.0
        raw_weights[n] = base

    max_base = max(raw_weights.values()) if raw_weights else 1.0
    if max_base <= 0.0:
        max_base = 1.0

    _CORE_CONCEPT_WEIGHTS_CACHE = {k: v / max_base for k, v in raw_weights.items()}
    return _CORE_CONCEPT_WEIGHTS_CACHE


def get_core_concept_score(concept_names, ContextInfo=None) -> float:
    try:
        if not concept_names:
            return 0.0
        weights = _build_core_concept_weights(ContextInfo)
        if not weights:
            return 0.0
        unique = set()
        for n in concept_names:
            try:
                unique.add(str(n))
            except Exception:
                continue
        if not unique:
            return 0.0
        sum_w = sum(weights.get(n, 0.0) for n in unique)
        raw_score = sum_w / 3.0
        if raw_score < 0.0:
            raw_score = 0.0
        if raw_score > 1.0:
            raw_score = 1.0
        return raw_score
    except Exception:
        return 0.0


def get_limit_up_open_fail_penalty(context, stock_code: str, *, lookback_days: int = 30) -> float:
    """估算近N日“触板未封(炸板)”惩罚分。

    近似判定：当日 high 触及(或非常接近)涨停阈值，但 close 未达到涨停阈值 => 视为开板未回封。
    - 越近发生惩罚越大（更贴近实战：近期炸板风险更高）。
    - 仅用于题材内龙头排序扣分，失败时返回 0。
    """
    try:
        lookback_days = int(lookback_days or 30)
        lookback_days = max(5, min(120, lookback_days))
        cache_key = None
        try:
            cache_key = (str(stock_code), lookback_days)
            if cache_key in LIMIT_UP_OPEN_FAIL_CACHE:
                return float(LIMIT_UP_OPEN_FAIL_CACHE[cache_key] or 0.0)
        except Exception:
            cache_key = None

        code = str(stock_code)
        is_st = False
        try:
            if 'is_st_stock' in globals() and callable(globals().get('is_st_stock')):
                is_st = bool(is_st_stock(code, context))
        except Exception:
            is_st = False

        pct_th = 0.095
        try:
            if is_st:
                pct_th = 0.045
            else:
                if code.startswith(('300', '301', '688', '689')):
                    pct_th = 0.195
                elif code.startswith(('8', '83', '87')):
                    pct_th = 0.295
                else:
                    pct_th = 0.095
        except Exception:
            pct_th = 0.095

        md = None
        try:
            md = get_optimized_market_data_ex(
                stock_codes=[code],
                fields=['close', 'high'],
                period='1d',
                count=lookback_days + 1,
                context=context,
            )
        except Exception:
            md = None

        bars = None
        try:
            if md is not None and code in md:
                bars = md[code]
            elif md is not None and stock_code in md:
                bars = md[stock_code]
        except Exception:
            bars = None

        if not bars or len(bars) < 6:
            if cache_key is not None:
                LIMIT_UP_OPEN_FAIL_CACHE[cache_key] = 0.0
            return 0.0

        try:
            if hasattr(bars, 'to_dict'):
                bars = bars.to_dict('records')
        except Exception:
            pass

        closes, highs = [], []
        for b in list(bars):
            try:
                if isinstance(b, dict):
                    c = float(b.get('close') or 0)
                    h = float(b.get('high') or b.get('close') or 0)
                else:
                    c = float(getattr(b, 'close', 0) or 0)
                    h = float(getattr(b, 'high', c) or c)
                closes.append(c)
                highs.append(h)
            except Exception:
                closes.append(0.0)
                highs.append(0.0)

        tol = 0.002
        fail_idxs = []
        for i in range(1, len(closes)):
            pc = closes[i - 1]
            if not pc or pc <= 0:
                continue
            limit_px = pc * (1.0 + pct_th)
            hit_limit = bool(highs[i] >= limit_px * (1.0 - 0.0005))
            sealed = bool(closes[i] >= limit_px * (1.0 - tol))
            if hit_limit and (not sealed):
                fail_idxs.append(i)

        if not fail_idxs:
            if cache_key is not None:
                LIMIT_UP_OPEN_FAIL_CACHE[cache_key] = 0.0
            return 0.0

        # 基础惩罚：次数
        base = 1.5 * float(len(fail_idxs))
        # 新近性加权：最近一次越近，额外惩罚越大（7日内最强）
        recency = 0.0
        try:
            last_i = int(max(fail_idxs))
            days_since = (len(closes) - 1) - last_i
            recency = max(0.0, 1.0 - (float(days_since) / 7.0)) * 3.0
        except Exception:
            recency = 0.0

        penalty = base + recency
        if penalty < 0.0:
            penalty = 0.0

        if cache_key is not None:
            LIMIT_UP_OPEN_FAIL_CACHE[cache_key] = float(penalty)
        return float(penalty)
    except Exception:
        return 0.0


def get_stock_sector_boost(stock_code: str, ContextInfo=None) -> float:
    """根据个股所属行业(日线+短期3日)和核心概念3日强度，计算一个温和的板块加权系数。

    目标区间约为 0.9~1.3：
    - 行业/概念均较弱时略微压缩分数(≈0.9~1.0)；
    - 强行业/强核心概念时适当放大(≈1.1~1.3)。
    任意异常时返回 1.0，不影响原始评分。
    """
    try:
        from math import isnan

        # 1) 行业日线 + 短期3日
        base_industry = get_stock_industry(stock_code)

        daily_band_score = None
        try:
            ind_scores = globals().get('INDUSTRY_SENTIMENT_SCORES')
            if isinstance(ind_scores, dict):
                info = ind_scores.get(base_industry)
                if isinstance(info, dict):
                    v = info.get('band_score')
                    if isinstance(v, (int, float)) and not isnan(v):
                        daily_band_score = float(v)
        except Exception:
            daily_band_score = None

        short_band_score = None
        try:
            ind_short_scores = globals().get('INDUSTRY_SHORT_TERM_SCORES')
            if isinstance(ind_short_scores, dict):
                info_s = ind_short_scores.get(base_industry)
                if isinstance(info_s, dict):
                    v2 = info_s.get('short_term_band_score')
                    if isinstance(v2, (int, float)) and not isnan(v2):
                        short_band_score = float(v2)
        except Exception:
            short_band_score = None

        # 将 A/B/C/D 档位分数映射到 0~1 的强弱值，默认 C 档 ~0.5
        def norm_band_score(x: float) -> float:
            try:
                # 以 1.3,1.1,0.9,0.7 映射到 [1.0, 0.5, 0.0] 的线性区间
                # 简化：x∈[0.7,1.3] -> (x-0.7)/(1.3-0.7)
                v = (float(x) - 0.7) / 0.6
                if v < 0.0:
                    v = 0.0
                if v > 1.0:
                    v = 1.0
                return v
            except Exception:
                return 0.5

        daily_strength = norm_band_score(daily_band_score) if daily_band_score is not None else 0.5
        short_strength = norm_band_score(short_band_score) if short_band_score is not None else 0.5

        industry_strength = 0.6 * daily_strength + 0.4 * short_strength

        # 2) 核心概念3日强度：使用 update_concept_short_term_scores 计算的 scores 字典(如存在)
        concept_short_strength = 0.5
        try:
            # 从 ContextInfo 或全局获取最新的概念3日强度 scores（若已缓存）
            concept_short_scores = getattr(ContextInfo, 'concept_short_term_scores', None) if ContextInfo else None
            if not isinstance(concept_short_scores, dict):
                concept_short_scores = globals().get('CONCEPT_SHORT_TERM_SCORES')

            tags = get_stock_tags(ContextInfo, stock_code)
            t_concepts = tags.get('t_concept') if isinstance(tags, dict) else None
            concept_names = []
            if isinstance(t_concepts, (list, tuple, set)):
                concept_names = [str(x) for x in t_concepts if x]
            elif t_concepts:
                concept_names = [str(t_concepts)]

            best_strength = None
            if concept_short_scores and concept_names:
                for cname in concept_names:
                    info = concept_short_scores.get(cname)
                    if not isinstance(info, dict):
                        continue
                    r3 = info.get('return_3d')
                    if not isinstance(r3, (int, float)):
                        continue
                    # 假设 -10%~+10% 映射到 [0,1]，超出部分截断
                    v = (float(r3) + 0.10) / 0.20
                    if v < 0.0:
                        v = 0.0
                    if v > 1.0:
                        v = 1.0
                    if best_strength is None or v > best_strength:
                        best_strength = v
            if best_strength is not None:
                concept_short_strength = best_strength
        except Exception:
            concept_short_strength = 0.5

        # 3) 组合行业 + 概念短期强度，得到一个 0~1 总强度
        total_strength = 0.6 * industry_strength + 0.4 * concept_short_strength

        # 4) 映射到 0.9~1.3 的放大系数
        boost = 0.9 + 0.4 * total_strength
        if boost < 0.9:
            boost = 0.9
        if boost > 1.3:
            boost = 1.3
        return float(boost)
    except Exception:
        return 1.0


def compute_env_score(ContextInfo=None) -> float:
    """综合行业日线/短期3日与核心概念3日强度，计算 0~1 的市场环境分。

    设计思路：
    - 行业层：看 A/B 档占比 + 短期3日分布（强行业多 → 值高）；
    - 概念层：看核心概念3日涨幅的中位数/分布；
    - 返回 0~1，0.5 视为中性，>0.7 偏进攻，<0.3 偏防守。
    任意异常时返回 0.5（中性）。
    """
    try:
        # 1) 行业部分：按 A/B/C/D 档位统计强行业比例
        sentiment = globals().get('INDUSTRY_SENTIMENT_SCORES') if isinstance(globals().get('INDUSTRY_SENTIMENT_SCORES'), dict) else {}
        short_term = globals().get('INDUSTRY_SHORT_TERM_SCORES') if isinstance(globals().get('INDUSTRY_SHORT_TERM_SCORES'), dict) else {}

        total_ind = 0
        strong_ind = 0
        avg_band = []
        for name, info in (sentiment or {}).items():
            if not isinstance(info, dict):
                continue
            band = info.get('band_score')
            if not isinstance(band, (int, float)):
                continue
            total_ind += 1
            avg_band.append(float(band))
            # 认为 band_score >=1.1 为 A/B 强行业
            if float(band) >= 1.1:
                strong_ind += 1

        if total_ind > 0:
            strong_ratio = strong_ind / float(total_ind)
            mean_band = sum(avg_band) / len(avg_band) if avg_band else 1.0
        else:
            strong_ratio = 0.0
            mean_band = 1.0

        # 将 band_score(≈0.7~1.3) 映射到 0~1
        def norm_band(x: float) -> float:
            try:
                v = (float(x) - 0.7) / 0.6
                if v < 0.0:
                    v = 0.0
                if v > 1.0:
                    v = 1.0
                return v
            except Exception:
                return 0.5

        band_strength = norm_band(mean_band)

        # 短期3日行业强度：看 short_term_score 的平均
        short_vals = []
        for name, info in (short_term or {}).items():
            if not isinstance(info, dict):
                continue
            v = info.get('short_term_score')
            if isinstance(v, (int, float)):
                short_vals.append(float(v))
        if short_vals:
            # short_term_score 本身已是 0~1
            short_strength = sum(short_vals) / len(short_vals)
        else:
            short_strength = 0.5

        # 行业环境：更偏向3日节奏（short_strength 权重提升）
        industry_env = 0.3 * band_strength + 0.5 * short_strength + 0.2 * strong_ratio

        # 2) 概念3日部分：从 ContextInfo 或全局读取概念3日强度
        concept_env = 0.5
        try:
            concept_short_scores = getattr(ContextInfo, 'concept_short_term_scores', None) if ContextInfo else None
            if not isinstance(concept_short_scores, dict):
                concept_short_scores = globals().get('CONCEPT_SHORT_TERM_SCORES')
            rets = []
            if concept_short_scores:
                for _, info in concept_short_scores.items():
                    if not isinstance(info, dict):
                        continue
                    r3 = info.get('return_3d')
                    if isinstance(r3, (int, float)):
                        rets.append(float(r3))
            if rets:
                # -10%~+10% 映射到 0~1，使用中位数抗噪
                rets.sort()
                mid = rets[len(rets) // 2]
                v = (mid + 0.10) / 0.20
                if v < 0.0:
                    v = 0.0
                if v > 1.0:
                    v = 1.0
                concept_env = v
        except Exception:
            concept_env = 0.5

        # 3) 综合环境分：改为“概念主导、行业辅助”
        # 原先: env = 0.6 * industry_env + 0.4 * concept_env
        # 调整后: 行业 0.3，概念 0.7，使热点概念对整体环境的影响更大
        env = 0.3 * industry_env + 0.7 * concept_env
        if env < 0.0:
            env = 0.0
        if env > 1.0:
            env = 1.0
        return float(env)
    except Exception:
        return 0.5


