def get_dynamic_cci_config(context) -> dict:
    """
    根据市场环境动态生成CCI配置。
    bull: 放宽触发、提升加分
    sideways: 中性
    bear: 收紧触发、降低加分
    """
    try:
        env = getattr(context, 'current_market_env', globals().get('current_market_environment', 'sideways')) or 'sideways'
        base = dict(CCI_SIGNAL_CONFIG)
        env = str(env).lower()
        if env in ('bull', 'up', 'strong_bull'):
            base.update({
                'window': 14,
                'min_cci_current': 0.0,
                'min_volume_rank_for_bonus': 50,
                'min_cci_rank_for_extra_bonus': 58,
                'bonus_level_ge4': 3.5,
                'bonus_level_eq3': 2.0,
                'bonus_cci_rank': 0.6,
            })
        elif env in ('bear', 'down', 'weak_bear'):
            base.update({
                'window': 26,
                'min_cci_current': 30.0,
                'min_volume_rank_for_bonus': 60,
                'min_cci_rank_for_extra_bonus': 65,
                'bonus_level_ge4': 2.0,
                'bonus_level_eq3': 1.0,
                'bonus_cci_rank': 0.4,
            })
        else:
            base.update({
                'window': 20,
                'min_cci_current': 10.0,
                'min_volume_rank_for_bonus': 55,
                'min_cci_rank_for_extra_bonus': 60,
                'bonus_level_ge4': 3.0,
                'bonus_level_eq3': 1.5,
                'bonus_cci_rank': 0.5,
            })
        return base
    except Exception:
        return dict(CCI_SIGNAL_CONFIG)


RECENT_LIMIT_UP_CACHE = {}

