def get_limit_up_quality_score(context, stock_code: str, *, lookback_days: int = 30) -> float:
    """计算近N日涨停“质量分”（用于题材内龙头排序的辅助）。

    设计：不依赖盘口，基于日线 close/high/low 近似。
    - 更偏好“非一字涨停”(high!=low) 的涨停事件；
    - 惩罚一字占比过高（减少纯一字被误判为可参与龙头）；
    - 越近发生的涨停，质量分略更高。
    返回范围不做强约束，通常在 0~10 左右。
    """
    try:
        lookback_days = int(lookback_days or 30)
        lookback_days = max(5, min(120, lookback_days))
        cache_key = None
        try:
            cache_key = (str(stock_code), lookback_days)
            if cache_key in LIMIT_UP_QUALITY_CACHE:
                return float(LIMIT_UP_QUALITY_CACHE[cache_key] or 0.0)
        except Exception:
            cache_key = None

        code = str(stock_code)
        is_st = False
        try:
            if 'is_st_stock' in globals() and callable(globals().get('is_st_stock')):
                is_st = bool(is_st_stock(code, context))
        except Exception:
            is_st = False

        pct_th = 0.095
        try:
            if is_st:
                pct_th = 0.045
            else:
                if code.startswith(('300', '301', '688', '689')):
                    pct_th = 0.195
                elif code.startswith(('8', '83', '87')):
                    pct_th = 0.295
                else:
                    pct_th = 0.095
        except Exception:
            pct_th = 0.095

        md = None
        try:
            md = get_optimized_market_data_ex(
                stock_codes=[code],
                fields=['close', 'high', 'low'],
                period='1d',
                count=lookback_days + 1,
                context=context,
            )
        except Exception:
            md = None

        bars = None
        try:
            if md is not None and code in md:
                bars = md[code]
            elif md is not None and stock_code in md:
                bars = md[stock_code]
        except Exception:
            bars = None

        if not bars or len(bars) < 6:
            if cache_key is not None:
                LIMIT_UP_QUALITY_CACHE[cache_key] = 0.0
            return 0.0

        try:
            if hasattr(bars, 'to_dict'):
                bars = bars.to_dict('records')
        except Exception:
            pass

        closes, highs, lows = [], [], []
        for b in list(bars):
            try:
                if isinstance(b, dict):
                    c = float(b.get('close') or 0)
                    h = float(b.get('high') or b.get('close') or 0)
                    l = float(b.get('low') or b.get('close') or 0)
                else:
                    c = float(getattr(b, 'close', 0) or 0)
                    h = float(getattr(b, 'high', c) or c)
                    l = float(getattr(b, 'low', c) or c)
                closes.append(c)
                highs.append(h)
                lows.append(l)
            except Exception:
                closes.append(0.0)
                highs.append(0.0)
                lows.append(0.0)

        tol = 0.002
        limit_days = []
        one_word_cnt = 0
        non_one_word_cnt = 0
        last_non_one_word_idx = None

        for i in range(1, len(closes)):
            pc = closes[i - 1]
            cc = closes[i]
            pct = (cc - pc) / pc if (pc and cc and pc > 0) else 0.0
            is_limit = bool(pct >= (pct_th - tol))
            if not is_limit:
                continue
            is_one_word = False
            try:
                if highs[i] > 0 and lows[i] > 0 and abs(highs[i] - lows[i]) <= 1e-12:
                    is_one_word = True
            except Exception:
                is_one_word = False

            limit_days.append((i, is_one_word))
            if is_one_word:
                one_word_cnt += 1
            else:
                non_one_word_cnt += 1
                last_non_one_word_idx = i

        if not limit_days:
            if cache_key is not None:
                LIMIT_UP_QUALITY_CACHE[cache_key] = 0.0
            return 0.0

        total_limits = len(limit_days)
        one_word_ratio = float(one_word_cnt) / float(max(1, total_limits))

        recency_bonus = 0.0
        try:
            if last_non_one_word_idx is not None:
                days_since = (len(closes) - 1) - int(last_non_one_word_idx)
                # 越近越高，7日内最强
                recency_bonus = max(0.0, 1.0 - (float(days_since) / 7.0)) * 2.0
        except Exception:
            recency_bonus = 0.0

        # 质量分：非一字次数 + 近期加成 - 一字占比惩罚
        score = (1.5 * float(non_one_word_cnt)) + float(recency_bonus) - (2.0 * float(one_word_ratio))
        if score < 0.0:
            score = 0.0

        if cache_key is not None:
            LIMIT_UP_QUALITY_CACHE[cache_key] = float(score)
        return float(score)
    except Exception:
        return 0.0


def get_consecutive_limit_up_days(context, stock_code: str, *, lookback_days: int = 30) -> int:
    """估算最近的连续涨停天数（以日线收盘涨幅阈值近似）。

    说明：不依赖盘口/涨跌停价字段，使用 close 与前收涨幅判断。
    - ST：约 5%
    - 创业板/科创板：约 20%
    - 北交所：约 30%
    - 其他：约 10%
    识别失败时返回 0。
    """
    try:
        lookback_days = int(lookback_days or 30)
        lookback_days = max(5, min(120, lookback_days))
        cache_key = None
        try:
            cache_key = (str(stock_code), lookback_days)
            if cache_key in CONSEC_LIMIT_UP_CACHE:
                return int(CONSEC_LIMIT_UP_CACHE[cache_key] or 0)
        except Exception:
            cache_key = None

        code = str(stock_code)
        is_st = False
        try:
            if 'is_st_stock' in globals() and callable(globals().get('is_st_stock')):
                is_st = bool(is_st_stock(code, context))
        except Exception:
            is_st = False

        # 交易所涨跌幅：用代码前缀做近似
        pct_th = 0.095
        try:
            if is_st:
                pct_th = 0.045
            else:
                if code.startswith(('300', '301', '688', '689')):
                    pct_th = 0.195
                elif code.startswith(('8', '83', '87')):
                    pct_th = 0.295
                else:
                    pct_th = 0.095
        except Exception:
            pct_th = 0.095

        md = None
        try:
            md = get_optimized_market_data_ex(
                stock_codes=[code],
                fields=['close'],
                period='1d',
                count=lookback_days + 1,
                context=context,
            )
        except Exception:
            md = None

        bars = None
        try:
            if md is not None and code in md:
                bars = md[code]
            elif md is not None and stock_code in md:
                bars = md[stock_code]
        except Exception:
            bars = None

        if not bars or len(bars) < 3:
            if cache_key is not None:
                CONSEC_LIMIT_UP_CACHE[cache_key] = 0
            return 0

        try:
            if hasattr(bars, 'to_dict'):
                bars = bars.to_dict('records')
        except Exception:
            pass

        closes = []
        for b in list(bars):
            try:
                if isinstance(b, dict):
                    c = float(b.get('close') or 0)
                else:
                    c = float(getattr(b, 'close', 0) or 0)
                closes.append(c)
            except Exception:
                closes.append(0.0)

        # 容错：给阈值留一点误差（涨停价四舍五入等）
        tol = 0.002
        flags = []
        for i in range(1, len(closes)):
            pc = closes[i - 1]
            cc = closes[i]
            pct = (cc - pc) / pc if (pc and cc and pc > 0) else 0.0
            flags.append(bool(pct >= (pct_th - tol)))

        # 从最新一根开始回溯连续 True
        streak = 0
        j = len(flags) - 1
        while j >= 0 and flags[j]:
            streak += 1
            j -= 1

        if cache_key is not None:
            CONSEC_LIMIT_UP_CACHE[cache_key] = int(streak)
        return int(streak)
    except Exception:
        return 0


def get_recent_limit_up_info(context, stock_code: str, cfg: dict = None) -> dict:
    try:
        cfg = cfg if isinstance(cfg, dict) else globals().get('LIMIT_UP_RECENT_BONUS_CONFIG', {})
        if not cfg or not cfg.get('enabled', False):
            return {'has_limit_up': False, 'days_since': None, 'count': 0}

        lookback_days = int(cfg.get('lookback_days', 30) or 30)
        lookback_days = max(5, min(120, lookback_days))
        pct_th = float(cfg.get('pct_threshold', 0.098) or 0.098)
        exclude_one_word = bool(cfg.get('exclude_one_word', True))
        exclude_consecutive_ge = int(cfg.get('exclude_consecutive_ge', 2) or 2)
        exclude_consecutive_ge = max(1, exclude_consecutive_ge)

        cache_key = None
        try:
            cache_key = (str(stock_code), lookback_days, pct_th, int(exclude_one_word), exclude_consecutive_ge)
            if cache_key in RECENT_LIMIT_UP_CACHE:
                return RECENT_LIMIT_UP_CACHE[cache_key]
        except Exception:
            cache_key = None

        md = None
        try:
            md = get_optimized_market_data_ex(
                stock_codes=[stock_code],
                fields=['close', 'high', 'low'],
                period='1d',
                count=lookback_days + 1,
                context=context,
            )
        except Exception:
            md = None

        bars = None
        try:
            if md is not None and stock_code in md:
                bars = md[stock_code]
        except Exception:
            bars = None

        if not bars or len(bars) < 6:
            res = {'has_limit_up': False, 'days_since': None, 'count': 0}
            if cache_key is not None:
                RECENT_LIMIT_UP_CACHE[cache_key] = res
            return res

        try:
            if hasattr(bars, 'to_dict'):
                bars = bars.to_dict('records')
        except Exception:
            pass

        closes, highs, lows = [], [], []
        for b in list(bars):
            try:
                if isinstance(b, dict):
                    c = float(b.get('close') or 0)
                    h = float(b.get('high') or b.get('close') or 0)
                    l = float(b.get('low') or b.get('close') or 0)
                else:
                    c = float(getattr(b, 'close', 0) or 0)
                    h = float(getattr(b, 'high', c) or c)
                    l = float(getattr(b, 'low', c) or c)
                closes.append(c)
                highs.append(h)
                lows.append(l)
            except Exception:
                closes.append(0.0)
                highs.append(0.0)
                lows.append(0.0)

        limit_flags = []
        for i in range(1, len(closes)):
            pc = closes[i - 1]
            cc = closes[i]
            pct = (cc - pc) / pc if (pc and cc and pc > 0) else 0.0
            is_limit = bool(pct >= pct_th)
            if is_limit and exclude_one_word:
                try:
                    if highs[i] > 0 and lows[i] > 0 and abs(highs[i] - lows[i]) <= 1e-12:
                        is_limit = False
                except Exception:
                    pass
            limit_flags.append(is_limit)

        last_idx = None
        count = 0
        for j in range(len(limit_flags) - 1, -1, -1):
            if limit_flags[j]:
                last_idx = j
                break
        for f in limit_flags:
            if f:
                count += 1

        if last_idx is None:
            res = {'has_limit_up': False, 'days_since': None, 'count': 0}
            if cache_key is not None:
                RECENT_LIMIT_UP_CACHE[cache_key] = res
            return res

        streak = 1
        try:
            k = last_idx - 1
            while k >= 0 and limit_flags[k]:
                streak += 1
                k -= 1
        except Exception:
            streak = 1

        days_since = (len(limit_flags) - 1) - last_idx
        if streak >= exclude_consecutive_ge:
            res = {'has_limit_up': False, 'days_since': None, 'count': 0}
        else:
            res = {'has_limit_up': True, 'days_since': int(days_since), 'count': int(count)}

        if cache_key is not None:
            RECENT_LIMIT_UP_CACHE[cache_key] = res
        return res
    except Exception:
        return {'has_limit_up': False, 'days_since': None, 'count': 0}

def _simple_ma(vals, n):
    try:
        if not vals or len(vals) < n:
            return None
        return sum(vals[-n:]) / float(n)
    except Exception:
        return None

def _simple_rsi(vals, period=14):
    try:
        if not vals or len(vals) < period + 1:
            return None
        gains = []
        losses = []
        for i in range(1, len(vals)):
            chg = float(vals[i]) - float(vals[i-1])
            gains.append(max(chg, 0.0))
            losses.append(max(-chg, 0.0))
        avg_gain = sum(gains[-period:]) / float(period)
        avg_loss = sum(losses[-period:]) / float(period)
        if avg_loss == 0:
            return 100.0
        rs = avg_gain / avg_loss
        return 100.0 - (100.0 / (1.0 + rs))
    except Exception:
        return None

def _is_ma20_break(closes, confirm_bars=1):
    try:
        cb = int(confirm_bars) if confirm_bars is not None else 1
        cb = max(1, cb)
        if not closes or len(closes) < 20 + cb:
            return False
        arr = [float(v) for v in closes]
        for i in range(cb):
            idx = -1 - i
            win = arr[idx-19:idx+1]
            if len(win) < 20:
                return False
            ma = sum(win) / 20.0
            if not (arr[idx] < ma):
                return False
        prev_idx = -1 - cb
        prev_win = arr[prev_idx-19:prev_idx+1]
        if len(prev_win) < 20:
            return False
        prev_ma = sum(prev_win) / 20.0
        return arr[prev_idx] >= prev_ma
    except Exception:
        return False

def _is_high_position(current_price, closes, buy_price=None, cfg=None):
    try:
        if not closes or len(closes) < 60:
            return False
        price = float(current_price)
        arr = [float(v) for v in closes]
        w = int(globals().get('MA_TREND', 20) or 20)
        w = max(10, min(60, w))
        ma20 = sum(arr[-w:]) / float(w)
        ma60 = sum(arr[-60:]) / 60.0
        cfg = cfg or {}
        # 条件1：价格在MA60上方（默认启用）
        cond_above_ma60 = True
        if bool(cfg.get('above_ma60', True)):
            cond_above_ma60 = price > ma60
        # 条件2：相对成本的最小利润
        cond_profit = True
        try:
            pmin = float(cfg.get('profit_min', 0.10))
            if buy_price is not None and float(buy_price) > 0:
                cond_profit = (price - float(buy_price)) / float(buy_price) >= pmin
        except Exception:
            cond_profit = True
        # 条件3：相对MA20的溢价
        cond_premium = True
        try:
            prem = float(cfg.get('ma20_premium_min', 0.05))
            if ma20 > 0:
                cond_premium = (price - ma20) / ma20 >= prem
        except Exception:
            cond_premium = True
        return bool(cond_above_ma60 and cond_profit and cond_premium)
    except Exception:
        return False

def _ema_series(vals, period):
    k = 2.0 / (float(period) + 1.0)
    ema = None
    out = []
    for v in vals:
        if ema is None:
            ema = float(v)
        else:
            ema = (float(v) - ema) * k + ema
        out.append(ema)
    return out

def _is_macd_dead_cross(closes, confirm_bars=1):
    try:
        cb = int(confirm_bars) if confirm_bars is not None else 1
        cb = max(1, cb)
        if not closes or len(closes) < 35 + cb:
            return False
        vals = [float(v) for v in closes]
        ema12 = _ema_series(vals, 12)
        ema26 = _ema_series(vals, 26)
        dif = [a - b for a, b in zip(ema12[-len(ema26):], ema26)]
        dea = _ema_series(dif, 9)
        if len(dea) < cb + 1:
            return False
        now_idx = -1
        prev_idx = -1 - cb
        if not (dif[now_idx] < dea[now_idx]):
            return False
        return dif[prev_idx] >= dea[prev_idx]
    except Exception:
        return False

def _is_price_below_ma(closes, ma_window=5, confirm_bars=1):
    try:
        cb = int(confirm_bars) if confirm_bars is not None else 1
        cb = max(1, cb)
        mw = int(ma_window) if ma_window is not None else 5
        mw = max(2, mw)
        if not closes or len(closes) < mw + cb:
            return False
        arr = [float(v) for v in closes]
        for i in range(cb):
            idx = -1 - i
            win = arr[idx-mw+1:idx+1]
            if len(win) < mw:
                return False
            ma = sum(win) / float(mw)
            if not (arr[idx] < ma):
                return False
        prev_idx = -1 - cb
        prev_win = arr[prev_idx-mw+1:prev_idx+1]
        if len(prev_win) < mw:
            return False
        prev_ma = sum(prev_win) / float(mw)
        return arr[prev_idx] >= prev_ma
    except Exception:
        return False

def _evaluate_hourly_exit(context, stock_code: str, current_price: float, buy_price: float, st: dict, cfg: dict, market_env: str = ''):
    try:
        h_cfg = cfg.get('hourly_exit', {}) if isinstance(cfg.get('hourly_exit', {}), dict) else {}
        if not bool(h_cfg.get('enabled', False)):
            return None
        if buy_price is None or float(buy_price) <= 0 or current_price is None or float(current_price) <= 0:
            return None
        profit_ratio = (float(current_price) - float(buy_price)) / float(buy_price)
        # 判断是否为熊市严格模式：跳过盈利门槛和持仓时长守卫
        _env_l = str(market_env or '').lower()
        bear_strict = _env_l in ('bear', 'down', 'weak_bear')
        # 修复: 避免 0.0 or 0.05 → 0.05 的Python falsy陷阱
        _raw_mpr = h_cfg.get('min_profit_ratio', None)
        min_profit_ratio = float(_raw_mpr) if _raw_mpr is not None else 0.05
        if not bear_strict and profit_ratio < min_profit_ratio:
            logger.debug(
                f"HOURLY_EXIT_PROFIT_GUARD {stock_code} profit={profit_ratio:.2%} min_profit_ratio={min_profit_ratio:.2%} gap={(min_profit_ratio - profit_ratio):.2%}"
            )
            return None

        period = str(h_cfg.get('period', '60m') or '60m')
        min_bars = int(h_cfg.get('min_bars', 24) or 24)
        count = max(16, min_bars + 8)
        closes = _get_period_closes(context, stock_code, period, count)
        if not closes or len(closes) < min_bars:
            logger.debug(
                f"HOURLY_EXIT_DATA_GUARD {stock_code} period={period} got_bars={len(closes) if closes else 0} min_bars={min_bars} request_count={count}"
            )
            return None

        st = st if isinstance(st, dict) else {}
        min_hold_hours = float(h_cfg.get('min_hold_hours', 6) or 0)
        opened_at_ts = int(st.get('opened_at_ts', 0) or 0)
        now_ts = int(time_module.time())
        if not bear_strict and min_hold_hours > 0 and opened_at_ts > 0 and now_ts > 0:
            hold_seconds = max(0, now_ts - opened_at_ts)
            if hold_seconds < int(min_hold_hours * 3600):
                logger.debug(
                    f"HOURLY_EXIT_HOLD_GUARD {stock_code} hold_hours={hold_seconds / 3600.0:.2f} min_hold_hours={min_hold_hours:.2f} remaining_hours={max(0.0, min_hold_hours - (hold_seconds / 3600.0)):.2f}"
                )
                return None
        if bear_strict:
            logger.debug(f"HOURLY_EXIT_BEAR_STRICT {stock_code} env={_env_l} skip_profit_guard skip_hold_guard profit={profit_ratio:.2%}")
        confirm_bars = int(h_cfg.get('confirm_bars', 1) or 1)
        ma5_confirm_bars = int(h_cfg.get('ma5_confirm_bars', confirm_bars) or confirm_bars)
        ma8_confirm_bars = int(h_cfg.get('ma8_confirm_bars', 2) or 2)
        ma5_hit = bool(h_cfg.get('ma5_reduce', True)) and _is_price_below_ma(closes, 5, ma5_confirm_bars)
        ma8_hit = bool(h_cfg.get('ma8_exit', True)) and _is_price_below_ma(closes, 8, ma8_confirm_bars)
        ma5_done = bool(st.get('hourly_ma5_reduced', False))
        ma8_done = bool(st.get('hourly_ma8_exited', False))

        ma5_val = (sum(closes[-5:]) / 5.0) if len(closes) >= 5 else None
        ma8_val = (sum(closes[-8:]) / 8.0) if len(closes) >= 8 else None

        if ma8_hit and not ma8_done:
            return {
                'triggered': True,
                'action': 'exit_all',
                'sell_ratio': 1.0,
                'reason': 'HOURLY_EXIT_MA8',
                'meta': {'ma5': ma5_val, 'ma8': ma8_val, 'profit_ratio': profit_ratio, 'period': period, 'ma5_confirm_bars': ma5_confirm_bars, 'ma8_confirm_bars': ma8_confirm_bars, 'min_hold_hours': min_hold_hours, 'min_profit_ratio': min_profit_ratio}
            }
        if ma5_hit and not ma5_done:
            reduce_ratio = float(h_cfg.get('reduce_ratio', 0.50) or 0.50)
            reduce_ratio = max(0.0, min(1.0, reduce_ratio))
            if reduce_ratio > 0:
                return {
                    'triggered': True,
                    'action': 'reduce_half',
                    'sell_ratio': reduce_ratio,
                    'reason': 'HOURLY_EXIT_MA5',
                    'meta': {'ma5': ma5_val, 'ma8': ma8_val, 'profit_ratio': profit_ratio, 'period': period, 'ma5_confirm_bars': ma5_confirm_bars, 'ma8_confirm_bars': ma8_confirm_bars, 'min_hold_hours': min_hold_hours, 'min_profit_ratio': min_profit_ratio}
                }
        logger.debug(
            f"HOURLY_EXIT_NO_TRIGGER {stock_code} period={period} profit={profit_ratio:.2%} ma5_hit={int(ma5_hit)} ma8_hit={int(ma8_hit)} ma5_done={int(ma5_done)} ma8_done={int(ma8_done)} ma5_confirm={ma5_confirm_bars} ma8_confirm={ma8_confirm_bars}"
        )
        return None
    except Exception:
        return None

def _evaluate_daily_ma8_exit(context, stock_code: str, current_price: float, buy_price: float, st: dict, market_env: str = ''):
    """日线8日均线跌破清仓：行情不好时严格执行，不受盈利/持仓时长豁免。"""
    try:
        if buy_price is None or float(buy_price) <= 0 or current_price is None or float(current_price) <= 0:
            return None
        _env_l = str(market_env or '').lower()
        bear_strict = _env_l in ('bear', 'down', 'weak_bear')
        # 非bear环境也检测，但需盈利 < 0（亏损时才触发），bear环境无条件触发
        profit_ratio = (float(current_price) - float(buy_price)) / float(buy_price)
        closes = _get_close_series(context, stock_code, count=30)
        if not closes or len(closes) < 10:
            return None
        ma8_val = sum(closes[-8:]) / 8.0 if len(closes) >= 8 else None
        if ma8_val is None:
            return None
        price = float(current_price)
        below_ma8 = price < ma8_val
        if not below_ma8:
            return None
        # bear市场：无条件清仓；其他环境：仅亏损时清仓（保护盈利头寸不被洗盘卖飞）
        if not bear_strict and profit_ratio >= 0.0:
            logger.debug(
                f"DAILY_MA8_EXIT_SKIP {stock_code} env={_env_l} profit={profit_ratio:.2%}>=0 ma8={ma8_val:.3f} price={price:.3f} (non-bear, profitable, skip)"
            )
            return None
        st = st if isinstance(st, dict) else {}
        if bool(st.get('daily_ma8_exited', False)):
            return None
        logger.warning(
            f"DAILY_MA8_EXIT_TRIGGER {stock_code} env={_env_l} price={price:.3f} ma8={ma8_val:.3f} gap={((price - ma8_val) / ma8_val):.2%} profit={profit_ratio:.2%} bear_strict={bear_strict}"
        )
        return {
            'triggered': True,
            'action': 'exit_all',
            'sell_ratio': 1.0,
            'reason': 'DAILY_MA8_EXIT',
            'meta': {'ma8': ma8_val, 'price': price, 'profit_ratio': profit_ratio, 'env': _env_l, 'bear_strict': bear_strict}
        }
    except Exception:
        return None

_last_env_update_date = {'date': None}
def update_market_environment(context):
    try:
        dt = getattr(context, 'current_dt', None)
        day = None
        if dt is not None:
            try:
                day = dt.date()
            except Exception:
                day = None
        if _last_env_update_date['date'] == day:
            return
        env = get_enhanced_market_environment(context)
        try:
            setattr(context, 'current_market_env', env)
        except Exception:
            pass
        try:
            cci_cfg_snapshot = get_dynamic_cci_config(context)
            logger.info(
                f"环境={env} | CCI(window={cci_cfg_snapshot.get('window')}, min_cci={cci_cfg_snapshot.get('min_cci_current')}, "
                f"yang={cci_cfg_snapshot.get('require_yang')}, vol_amp={cci_cfg_snapshot.get('require_volume_amplified')}, short_ma_up={cci_cfg_snapshot.get('require_short_ma_up')}, "
                f"bonus_ge4={cci_cfg_snapshot.get('bonus_level_ge4')}, bonus_eq3={cci_cfg_snapshot.get('bonus_level_eq3')}, bonus_rank={cci_cfg_snapshot.get('bonus_cci_rank')})"
            )
        except Exception:
            pass
        # 将环境与CCI参数写入当日上下文详情，供回测报告使用
        try:
            details = getattr(context, 'details', None)
            if details is None or not isinstance(details, dict):
                try:
                    setattr(context, 'details', {})
                except Exception:
                    pass
                details = getattr(context, 'details', None)
            if isinstance(details, dict):
                day_str = str(day) if day is not None else 'unknown'
                cci_cfg_snapshot2 = cci_cfg_snapshot if 'cci_cfg_snapshot' in locals() else get_dynamic_cci_config(context)
                snapshot = {
                    'date': day_str,
                    'env': env,
                    'cci': {
                        'window': cci_cfg_snapshot2.get('window'),
                        'min_cci_current': cci_cfg_snapshot2.get('min_cci_current'),
                        'require_yang': cci_cfg_snapshot2.get('require_yang'),
                        'require_volume_amplified': cci_cfg_snapshot2.get('require_volume_amplified'),
                        'require_short_ma_up': cci_cfg_snapshot2.get('require_short_ma_up'),
                        'bonus_level_ge4': cci_cfg_snapshot2.get('bonus_level_ge4'),
                        'bonus_level_eq3': cci_cfg_snapshot2.get('bonus_level_eq3'),
                        'bonus_cci_rank': cci_cfg_snapshot2.get('bonus_cci_rank'),
                        'min_volume_rank_for_bonus': cci_cfg_snapshot2.get('min_volume_rank_for_bonus'),
                        'min_cci_rank_for_extra_bonus': cci_cfg_snapshot2.get('min_cci_rank_for_extra_bonus'),
                    }
                }
                diary = details.get('daily_env_snapshot')
                if not isinstance(diary, dict):
                    diary = {}
                diary[day_str] = snapshot
                details['daily_env_snapshot'] = diary
        except Exception:
            pass
        _last_env_update_date['date'] = day
    except Exception:
        pass
# ===== 流动性辅助函数与缓存 =====
# 简单缓存：30分钟有效期，避免重复IO
_liquidity_cache = {
    'turnover': {},  # key: (code, days) -> {'value': float, 'ts': datetime}
    'multiplier': {},  # key: code -> {'value': float, 'ts': datetime}
}

def _cache_get(bucket: str, key):
    try:
        rec = _liquidity_cache.get(bucket, {}).get(key)
        if not rec:
            return None
        ts = rec.get('ts')
        if not ts:
            return None
        # 30分钟过期
        from datetime import datetime, timedelta
        if datetime.now() - ts > timedelta(minutes=30):
            return None
        return rec.get('value')
    except Exception:
        return None

def _cache_set(bucket: str, key, value):
    try:
        from datetime import datetime
        if bucket not in _liquidity_cache:
            _liquidity_cache[bucket] = {}
        _liquidity_cache[bucket][key] = {'value': value, 'ts': datetime.now()}
    except Exception:
        pass

def _cache_get_exp(bucket: str, key, minutes: int):
    """带自定义过期时间的轻量缓存读取。"""
    try:
        rec = _liquidity_cache.get(bucket, {}).get(key)
        if not rec:
            return None
        ts = rec.get('ts')
        if not ts:
            return None
        from datetime import datetime, timedelta
        if datetime.now() - ts > timedelta(minutes=max(1, int(minutes))):
            return None
        return rec.get('value')
    except Exception:
        return None

def _extract_tick_fields(tick_data, code: str):
    """尽可能从多种返回格式提取 (amount, volume, lastPrice)。"""
    try:
        import pandas as _pd
    except Exception:
        _pd = None
    amount = volume = last_price = None
    try:
        # dict: {code: {...}} 或 {code: DataFrame}
        if isinstance(tick_data, dict):
            obj = tick_data.get(code) or tick_data.get(str(code))
            if obj is None:
                # 某些实现返回列表或嵌套
                obj = next(iter(tick_data.values())) if tick_data else None
            if obj is not None:
                if _pd is not None and isinstance(obj, _pd.DataFrame):
                    if len(obj) > 0:
                        row = obj.iloc[-1]
                        # 统一大小写与常见别名
                        keys = {k.lower(): k for k in row.index}
                        amount = float(row[keys.get('amount')]) if 'amount' in keys else None
                        volume = float(row[keys.get('volume')]) if 'volume' in keys else None
                        lp_key = keys.get('lastprice') or keys.get('last_price') or keys.get('price')
                        last_price = float(row[lp_key]) if lp_key else None
                elif isinstance(obj, dict):
                    # 宽松大小写
                    low = {k.lower(): v for k, v in obj.items()}
                    amount = float(low.get('amount')) if low.get('amount') is not None else None
                    volume = float(low.get('volume')) if low.get('volume') is not None else None
                    lpv = low.get('lastprice') or low.get('last_price') or low.get('price')
                    last_price = float(lpv) if lpv is not None else None
                elif isinstance(obj, list) and obj:
                    # 取最后一个元素尝试解析
                    tail = obj[-1]
                    if isinstance(tail, dict):
                        low = {k.lower(): v for k, v in tail.items()}
                        amount = float(low.get('amount')) if low.get('amount') is not None else None
                        volume = float(low.get('volume')) if low.get('volume') is not None else None
                        lpv = low.get('lastprice') or low.get('last_price') or low.get('price')
                        last_price = float(lpv) if lpv is not None else None
        # 其他直接是 DataFrame
        elif _pd is not None and isinstance(tick_data, _pd.DataFrame):
            if len(tick_data) > 0:
                row = tick_data.iloc[-1]
                keys = {k.lower(): k for k in row.index}
                amount = float(row[keys.get('amount')]) if 'amount' in keys else None
                volume = float(row[keys.get('volume')]) if 'volume' in keys else None
                lp_key = keys.get('lastprice') or keys.get('last_price') or keys.get('price')
                last_price = float(row[lp_key]) if lp_key else None
    except Exception:
        pass
    return amount, volume, last_price

INTRADAY_PK_CONFIG = {
    'enabled': True,
    'top_n_only': 2,
    'cache_minutes': 1,
    'weights': {
        'day_chg': 0.40,
        'amount': 0.30,
        'pullback': 0.20,
        'spread': 0.07,
        'bid_imbalance': 0.03,
    },
    'filters': {
        'max_day_chg_pct': 8.5,
        'max_pullback_pct': 3.5,
        'max_spread_pct': 0.8,
        'min_today_amount': 2e7,
    }
}

_intraday_pk_cache = {'ts': None, 'data': {}}

def _clamp01(x: float) -> float:
    try:
        if x is None:
            return 0.0
        x = float(x)
        if x < 0:
            return 0.0
        if x > 1:
            return 1.0
        return x
    except Exception:
        return 0.0

def _get_intraday_tick_batch(context, stock_codes, cache_minutes: int = 1):
    try:
        mins = max(0, int(cache_minutes or 0))
    except Exception:
        mins = 0
    try:
        from datetime import datetime, timedelta
        if mins > 0 and _intraday_pk_cache.get('ts') is not None:
            if datetime.now() - _intraday_pk_cache['ts'] <= timedelta(minutes=mins):
                cached = _intraday_pk_cache.get('data') or {}
                if all((c in cached) for c in (stock_codes or [])):
                    return cached
    except Exception:
        pass
    td = None
    try:
        td = get_current_tick(context, stock_codes)
    except Exception:
        td = None
    normalized = {}
    if isinstance(td, dict):
        for c in (stock_codes or []):
            v = td.get(c) or td.get(str(c))
            if v is not None:
                normalized[str(c)] = v
    try:
        from datetime import datetime
        _intraday_pk_cache['ts'] = datetime.now()
        _intraday_pk_cache['data'] = normalized
    except Exception:
        pass
    return normalized

def _get_prev_close_batch(context, stock_codes):
    out = {}
    try:
        md = get_optimized_market_data_ex(stock_codes=stock_codes, fields=['close'], period='1d', count=2, context=context)
        for c in (stock_codes or []):
            rec = (md or {}).get(c) or (md or {}).get(str(c)) or {}
            closes = (rec or {}).get('close') or []
            if isinstance(closes, (list, tuple)) and len(closes) >= 2:
                try:
                    out[str(c)] = float(closes[-2])
                except Exception:
                    continue
    except Exception:
        pass
    return out

def _intraday_pk_score_one(code: str, tick: dict, prev_close: float, cfg: dict):
    w = (cfg or {}).get('weights', {}) or {}
    flt = (cfg or {}).get('filters', {}) or {}

    last_price = None
    day_high = None
    amount = None
    bid1 = ask1 = None
    bidv1 = askv1 = None
    try:
        if isinstance(tick, dict):
            last_price = tick.get('lastPrice') or tick.get('price') or tick.get('last')
            day_high = tick.get('high') or tick.get('High')
            amount = tick.get('amount') or tick.get('turnover')
            bid1 = tick.get('bidPrice1') or tick.get('buy1') or tick.get('bid1')
            ask1 = tick.get('askPrice1') or tick.get('sell1') or tick.get('ask1')
            bidv1 = tick.get('bidVol1') or tick.get('buyVol1') or tick.get('bid1_volume')
            askv1 = tick.get('askVol1') or tick.get('sellVol1') or tick.get('ask1_volume')
    except Exception:
        pass

    try:
        lp = float(last_price) if last_price is not None else 0.0
    except Exception:
        lp = 0.0
    try:
        pc = float(prev_close) if prev_close is not None else 0.0
    except Exception:
        pc = 0.0

    day_chg_pct = 0.0
    if pc > 0 and lp > 0:
        day_chg_pct = (lp - pc) / pc * 100.0

    try:
        dh = float(day_high) if day_high is not None else 0.0
    except Exception:
        dh = 0.0
    pullback_pct = 0.0
    if dh > 0 and lp > 0 and lp <= dh:
        pullback_pct = (dh - lp) / dh * 100.0

    try:
        amt = float(amount) if amount is not None else 0.0
    except Exception:
        amt = 0.0

    spread_pct = 0.0
    try:
        b1 = float(bid1) if bid1 is not None else 0.0
        a1 = float(ask1) if ask1 is not None else 0.0
        if b1 > 0 and a1 > 0 and a1 >= b1:
            spread_pct = (a1 - b1) / b1 * 100.0
    except Exception:
        spread_pct = 0.0

    imbalance = 0.0
    try:
        bv = float(bidv1) if bidv1 is not None else 0.0
        av = float(askv1) if askv1 is not None else 0.0
        denom = (bv + av)
        if denom > 0:
            imbalance = (bv - av) / denom
    except Exception:
        imbalance = 0.0

    if flt:
        try:
            max_chg = float(flt.get('max_day_chg_pct', 9.8))
            if day_chg_pct >= max_chg:
                return -1.0, {'reason': 'day_chg_cap', 'day_chg_pct': day_chg_pct}
        except Exception:
            pass
        try:
            max_pb = float(flt.get('max_pullback_pct', 4.0))
            if pullback_pct >= max_pb:
                return -1.0, {'reason': 'pullback_cap', 'pullback_pct': pullback_pct}
        except Exception:
            pass
        try:
            max_sp = float(flt.get('max_spread_pct', 0.8))
            if spread_pct >= max_sp:
                return -1.0, {'reason': 'spread_cap', 'spread_pct': spread_pct}
        except Exception:
            pass
        try:
            min_amt = float(flt.get('min_today_amount', 0.0))
            if min_amt > 0 and amt > 0 and amt < min_amt:
                return -1.0, {'reason': 'min_amount', 'amount': amt}
        except Exception:
            pass

    day_chg_score = _clamp01((day_chg_pct + 2.0) / 10.0)
    amount_score = _clamp01(amt / 1e8)
    pullback_score = _clamp01(1.0 - (pullback_pct / 5.0))
    spread_score = _clamp01(1.0 - (spread_pct / 1.0))
    imbalance_score = _clamp01((imbalance + 1.0) / 2.0)

    total = (
        float(w.get('day_chg', 0.0)) * day_chg_score +
        float(w.get('amount', 0.0)) * amount_score +
        float(w.get('pullback', 0.0)) * pullback_score +
        float(w.get('spread', 0.0)) * spread_score +
        float(w.get('bid_imbalance', 0.0)) * imbalance_score
    )

    detail = {
        'day_chg_pct': day_chg_pct,
        'pullback_pct': pullback_pct,
        'spread_pct': spread_pct,
        'amount': amt,
        'bid_imbalance': imbalance,
        'score': total,
    }
    return float(total), detail

def intraday_pk_rank(context, positions_items, cfg: dict = None):
    cfg2 = cfg or INTRADAY_PK_CONFIG
    if not bool((cfg2 or {}).get('enabled', True)):
        return list(positions_items), {}

    stocks = [str(s) for s, _ in (positions_items or [])]
    tick_map = _get_intraday_tick_batch(context, stocks, cache_minutes=(cfg2 or {}).get('cache_minutes', 1))
    prev_close_map = _get_prev_close_batch(context, stocks)

    ranked = []
    fallback = []
    details = {}
    for stock, pos in (positions_items or []):
        code = str(stock)
        tick = tick_map.get(code)
        if tick is None and hasattr(context, 'get_full_tick'):
            try:
                td = context.get_full_tick([code])
                if isinstance(td, dict):
                    tick = td.get(code)
            except Exception:
                tick = None
        if not isinstance(tick, dict):
            fallback.append((code, pos))
            continue
        score, det = _intraday_pk_score_one(code, tick, prev_close_map.get(code), cfg2)
        if score < 0:
            details[code] = det
            continue
        try:
            pos['intraday_pk_score'] = float(score)
        except Exception:
            pass
        details[code] = det
        ranked.append((code, pos, float(score)))

    ranked.sort(key=lambda x: (x[2], float((x[1] or {}).get('score', 0.0))), reverse=True)
    out_items = [(c, p) for c, p, _ in ranked]
    if fallback:
        fallback.sort(key=lambda x: float((x[1] or {}).get('score', 0.0)), reverse=True)
        out_items.extend(fallback)
    top_n = (cfg2 or {}).get('top_n_only')
    try:
        top_n = int(top_n) if top_n is not None else None
    except Exception:
        top_n = None
    if top_n is not None and top_n > 0:
        out_items = out_items[:top_n]
    return out_items, details

def get_layered_params(total_asset) -> dict:
    """
    根据资金规模返回分层参数，包含基础流动性门槛（单位：元/日成交额）。
    小资金放宽门槛，大资金提高门槛。
    """
    try:
        ta = float(total_asset or 0)
        if ta <= 500_000:
            floor = 5_000_000  # 500万
        elif ta <= 1_500_000:
            floor = 10_000_000 # 1000万
        elif ta <= 3_000_000:
            floor = 15_000_000 # 1500万
        else:
            floor = 20_000_000 # 2000万
        return {'liquidity_floor': floor}
    except Exception as e:
        logger.warning(f"get_layered_params失败: {e}")
        return {'liquidity_floor': 10_000_000}

def adjust_liquidity_floor(base_floor: float, market_env: str) -> float:
    """
    按市场环境调整基础门槛。
    - 牛市: 适度提高门槛（+10%）
    - 震荡: 略微降低（-10%）
    - 熊市: 明显降低（-30%）
    - 未知: 保持不变
    """
    try:
        env = (market_env or '').lower()
        floor = float(base_floor or 0)
        if env in ('bull', 'bullish', '牛市'):
            floor *= 1.1
        elif env in ('sideways', 'neutral', '震荡'):
            floor *= 0.9
        elif env in ('bear', 'bearish', '熊市'):
            floor *= 0.7
        # 下限保护
        return max(0.0, floor)
    except Exception as e:
        logger.warning(f"adjust_liquidity_floor失败: {e}")
        return float(base_floor or 0)

def _fetch_daily_series(context, code: str, days: int):
    """
    统一从优化的数据接口拉取近期日线字段，容错多字段名。
    返回 dict(fields->list)
    """
    try:
        # 优先尝试 amount（成交额）
        fields_try = [
            ['amount'],
            ['turnover'],
            ['amount', 'volume', 'close'],
            ['turnover', 'volume', 'close']
        ]
        for fields in fields_try:
            try:
                data = get_optimized_market_data_ex(stock_codes=[code], fields=fields, period='1d', count=max(1, int(days)), context=context)
                if data and code in data:
                    ok = True
                    for f in fields:
                        if f not in data[code] or not data[code][f]:
                            ok = False
                            break
                    if ok:
                        return data[code]
            except Exception as _:
                continue
    except Exception as e:
        logger.debug(f"_fetch_daily_series失败 {code}: {e}")
    return {}

def check_cci_zero_cross(context, code: str, window: int = 20, days: int = 30) -> dict:
    """
    检查CCI是否上穿0轴。
    返回: { 'triggered': bool, 'cci': float, 'prev': float }
    规则: 昨日CCI<=0 且 今日CCI>0 视为上穿0轴。
    """
    try:
        data = get_optimized_market_data_ex(stock_codes=[code], fields=['high', 'low', 'close'], period='1d', count=max(days, window+2), context=context)
        if not data or code not in data:
            return {'triggered': False, 'cci': None, 'prev': None}
        highs = data[code].get('high') or []
        lows = data[code].get('low') or []
        closes = data[code].get('close') or []
        n = min(len(highs), len(lows), len(closes))
        if n < window + 2:
            return {'triggered': False, 'cci': None, 'prev': None}
        # 计算TP
        TP = [(float(highs[i]) + float(lows[i]) + float(closes[i])) / 3.0 for i in range(n)]
        # 滚动MA与MD（简单实现：末尾两点）
        def _ma(arr, end_idx):
            start = end_idx - window + 1
            seg = arr[start:end_idx+1]
            return sum(seg) / window
        def _md(arr, end_idx, ma_val):
            start = end_idx - window + 1
            seg = arr[start:end_idx+1]
            return sum(abs(x - ma_val) for x in seg) / window
        # 倒数第二天索引与最后一天索引
        i_prev = n - 2
        i_cur = n - 1
        if i_prev - (window - 1) < 0:
            return {'triggered': False, 'cci': None, 'prev': None}
        ma_prev = _ma(TP, i_prev)
        md_prev = _md(TP, i_prev, ma_prev)
        cci_prev = (TP[i_prev] - ma_prev) / (0.015 * md_prev) if md_prev > 0 else 0.0
        ma_cur = _ma(TP, i_cur)
        md_cur = _md(TP, i_cur, ma_cur)
        cci_cur = (TP[i_cur] - ma_cur) / (0.015 * md_cur) if md_cur > 0 else 0.0
        triggered = (cci_prev <= 0.0 and cci_cur > 0.0)
        return {'triggered': triggered, 'cci': cci_cur, 'prev': cci_prev}
    except Exception as e:
        logger.debug(f"check_cci_zero_cross失败 {code}: {e}")
        return {'triggered': False, 'cci': None, 'prev': None}

def check_cci_down_cross(context, code: str, window: int = 20, days: int = 30) -> dict:
    """
    检查CCI是否下穿0轴。
    返回: { 'triggered': bool, 'cci': float, 'prev': float }
    规则: 昨日CCI>=0 且 今日CCI<0 视为下穿0轴。
    """
    try:
        data = get_optimized_market_data_ex(stock_codes=[code], fields=['high', 'low', 'close'], period='1d', count=max(days, window+2), context=context)
        if not data or code not in data:
            return {'triggered': False, 'cci': None, 'prev': None}
        highs = data[code].get('high') or []
        lows = data[code].get('low') or []
        closes = data[code].get('close') or []
        n = min(len(highs), len(lows), len(closes))
        if n < window + 2:
            return {'triggered': False, 'cci': None, 'prev': None}
        TP = [(float(highs[i]) + float(lows[i]) + float(closes[i])) / 3.0 for i in range(n)]
        def _ma(arr, idx):
            s = 0.0
            for j in range(idx - window + 1, idx + 1):
                s += TP[j]
            return s / window
        def _md(arr, idx, ma):
            s = 0.0
            for j in range(idx - window + 1, idx + 1):
                s += abs(TP[j] - ma)
            return s / window
        i_prev = n - 2
        i_cur = n - 1
        if i_prev - (window - 1) < 0:
            return {'triggered': False, 'cci': None, 'prev': None}
        ma_prev = _ma(TP, i_prev)
        md_prev = _md(TP, i_prev, ma_prev)
        cci_prev = (TP[i_prev] - ma_prev) / (0.015 * md_prev) if md_prev > 0 else 0.0
        ma_cur = _ma(TP, i_cur)
        md_cur = _md(TP, i_cur, ma_cur)
        cci_cur = (TP[i_cur] - ma_cur) / (0.015 * md_cur) if md_cur > 0 else 0.0
        triggered = (cci_prev >= 0.0 and cci_cur < 0.0)
        return {'triggered': triggered, 'cci': cci_cur, 'prev': cci_prev}
    except Exception as e:
        logger.debug(f"check_cci_down_cross失败 {code}: {e}")
        return {'triggered': False, 'cci': None, 'prev': None}

def is_short_ma_trend_up(context, code: str, days: int = 20) -> dict:
    """
    检查短期均线是否向上：MA5 > MA10 且 MA5上升（当前MA5 > 5日前MA5）。
    返回: {'ok': bool, 'ma5': float, 'ma10': float}
    """
    try:
        data = get_optimized_market_data_ex(stock_codes=[code], fields=['close'], period='1d', count=max(20, days), context=context)
        if not data or code not in data or 'close' not in data[code] or not data[code]['close']:
            return {'ok': False, 'ma5': None, 'ma10': None}
        closes = [float(x) for x in data[code]['close'] if x is not None]
        n = len(closes)
        if n < 15:
            return {'ok': False, 'ma5': None, 'ma10': None}
        def sma(arr, p):
            return sum(arr[-p:]) / p
        ma5 = sma(closes, 5)
        ma10 = sma(closes, 10)
        # 5日前的MA5近似（用前5根窗口）
        if n >= 10:
            ma5_prev = sum(closes[-10:-5]) / 5
        else:
            ma5_prev = ma5
        ok = (ma5 > ma10) and (ma5 > ma5_prev)
        return {'ok': bool(ok), 'ma5': ma5, 'ma10': ma10}
    except Exception as e:
        logger.debug(f"is_short_ma_trend_up失败 {code}: {e}")
        return {'ok': False, 'ma5': None, 'ma10': None}

def get_cached_avg_turnover(context, code: str, days: int = 5) -> float:
    """
    获取近N日平均成交额（元）。使用缓存+多字段容错：
    - 优先 amount，其次 turnover；
    - 若均缺失，尝试 close*volume 估算；
    - 全部失败返回 None（上层按数据未知处理，不直接剔除）。
    """
    try:
        key = (code, int(days))
        cached = _cache_get('turnover', key)
        if cached is not None:
            return cached
        series = _fetch_daily_series(context, code, days)
        if not series:
            _cache_set('turnover', key, None)
            return None
        values = None
        if 'amount' in series and series['amount']:
            values = [float(x) for x in series['amount'] if x is not None]
        elif 'turnover' in series and series['turnover']:
            values = [float(x) for x in series['turnover'] if x is not None]
        # 估算
        if (not values) and ('close' in series and 'volume' in series):
            closes = series['close'] or []
            vols = series['volume'] or []
            n = min(len(closes), len(vols))
            values = []
            for i in range(-n, 0):
                try:
                    values.append(float(closes[i]) * float(vols[i]))
                except Exception:
                    continue
        if not values:
            # 当历史 amount/turnover 均不可用时，尝试在实盘内盘时刻使用 get_full_tick 做当日快速兜底
            try:
                # 仅在交易时段尝试（避免非交易时段误用快照）
                current_dt = getattr(context, 'current_dt', None)
                session = get_strategy_session(current_dt) if 'get_strategy_session' in globals() else 'closed'
                if session in ('morning', 'afternoon') and hasattr(context, 'get_full_tick') and callable(getattr(context, 'get_full_tick')):
                    # 短时缓存（1-3分钟）
                    cache_key = ("tick_turnover", code)
                    tick_cached = _cache_get_exp('turnover', cache_key, minutes=3)
                    if tick_cached is not None:
                        try:
                            tick_val = float(tick_cached)
                        except Exception:
                            tick_val = 0.0
                        if tick_val > 0:
                            values = [tick_val]
                    if not values:
                        tick = context.get_full_tick([code])
                        # 期望 tick 返回 { code: { 'amount':..., 'volume':..., 'lastPrice':... } } 或 DataFrame/其他结构
                        am, vol, lp = _extract_tick_fields(tick, code)
                        am_f = float(am) if am is not None else 0.0
                        vol_f = float(vol) if vol is not None else 0.0
                        lp_f = float(lp) if lp is not None else 0.0
                        est_turnover = am_f if am_f > 0 else (lp_f * vol_f if (lp_f > 0 and vol_f > 0) else 0.0)
                        if est_turnover and est_turnover > 0:
                            values = [float(est_turnover)]
                            _cache_set('turnover', cache_key, float(est_turnover))
            except Exception:
                pass
            # 如仍无数据，标记为 None
            if not values:
                _cache_set('turnover', key, None)
                return None
        avg_val = sum(values) / max(1, len(values))
        # 过滤异常负值
        if avg_val <= 0:
            _cache_set('turnover', key, None)
            return None
        _cache_set('turnover', key, float(avg_val))
        return float(avg_val)
    except Exception as e:
        logger.debug(f"get_cached_avg_turnover失败 {code}: {e}")
        return None

def get_cached_liquidity_multiplier(context, code: str) -> float:
    """
    基于近期成交额粗略评估流动性乘子（0.8~1.2）：
    - 近5日均额 > 3亿: 1.2
    - > 1.5亿: 1.1
    - > 5000万: 1.0
    - > 2000万: 0.9
    - 其余: 0.8
    缺失数据: 返回1.0
    """
    try:
        cached = _cache_get('multiplier', code)
        if cached is not None:
            return cached
        avg5 = get_cached_avg_turnover(context, code, days=5)
        mult = 1.0
        if avg5 is None:
            mult = 1.0
        elif avg5 >= 300_000_000:
            mult = 1.2
        elif avg5 >= 150_000_000:
            mult = 1.1
        elif avg5 >= 50_000_000:
            mult = 1.0
        elif avg5 >= 20_000_000:
            mult = 0.9
        else:
            mult = 0.8
        _cache_set('multiplier', code, mult)
        return mult
    except Exception as e:
        logger.debug(f"get_cached_liquidity_multiplier失败 {code}: {e}")
        return 1.0

# ===== 统一的策略时间/会话工具（不直接依赖系统时钟）=====
def get_strategy_trading_day(ContextInfo=None, current_time: Optional[datetime] = None) -> Optional[str]:
    """返回策略视角的交易日字符串（YYYYMMDD）。强依赖交易所/平台变量，避免系统时钟。
    优先级：ContextInfo.get_market_time() -> ContextInfo.trading_day -> 全局 current_trading_day -> None
    """
    # 1) 平台API
    try:
        if ContextInfo is not None and hasattr(ContextInfo, 'get_market_time') and callable(getattr(ContextInfo, 'get_market_time')):
            mt = ContextInfo.get_market_time()
            if isinstance(mt, dict):
                day = mt.get('trade_date') or mt.get('trading_day') or mt.get('current_date') or mt.get('date')
                if isinstance(day, str) and day:
                    day_str = day.replace('-', '').replace('/', '').strip()
                    if len(day_str) == 8 and day_str.isdigit():
                        return day_str
    except Exception:
        pass
    # 2) 上下文直接提供
    try:
        if ContextInfo is not None and hasattr(ContextInfo, 'trading_day'):
            day = getattr(ContextInfo, 'trading_day')
            if isinstance(day, str) and day:
                day_str = day.replace('-', '').replace('/', '').strip()
                if len(day_str) == 8 and day_str.isdigit():
                    return day_str
    except Exception:
        pass
    # 3) 全局变量
    try:
        global current_trading_day
        if isinstance(current_trading_day, str) and current_trading_day:
            return current_trading_day
    except Exception:
        pass
    # 4) 不使用系统时钟作为兜底
    return None

def get_strategy_session(current_time: Union[str, datetime]) -> str:
    """根据传入的 current_time 判定会话: 'morning' | 'afternoon' | 'closed'。
    注意：不从系统时钟获取时间，完全依赖调用方传入的 current_time。"""
    try:
        if isinstance(current_time, str):
            # 允许 'HH:MM:SS' 或 带日期格式
            t_str = current_time.split()[-1]
            h, m, *_ = [int(x) for x in t_str.split(':')]
            ct = dt_time(h, m)
        elif isinstance(current_time, datetime):
            ct = dt_time(current_time.hour, current_time.minute)
        else:
            return 'closed'
        if dt_time(9, 30) <= ct < dt_time(11, 30):
            return 'morning'
        if dt_time(13, 0) <= ct < dt_time(15, 0):
            return 'afternoon'
        return 'closed'
    except Exception:
        return 'closed'

def strategy_open_window_cycle_tick(session: str, cycles_limit: int, current_day: Optional[str]) -> bool:
    """在会话开启后的前 N 个循环内返回 True，并维护 OPEN_CYCLE_STATE（带最小互斥）。"""
    if cycles_limit <= 0:
        return False
    ok = False
    try:
        with OPEN_CYCLE_LOCK:
            if OPEN_CYCLE_STATE.get('last_session_day') != current_day:
                OPEN_CYCLE_STATE['last_session_day'] = current_day
                OPEN_CYCLE_STATE['morning_started'] = False
                OPEN_CYCLE_STATE['morning_count'] = 0
                OPEN_CYCLE_STATE['afternoon_started'] = False
                OPEN_CYCLE_STATE['afternoon_count'] = 0
            if session == 'morning':
                if not OPEN_CYCLE_STATE['morning_started']:
                    OPEN_CYCLE_STATE['morning_started'] = True
                    OPEN_CYCLE_STATE['morning_count'] = 0
                if OPEN_CYCLE_STATE['morning_count'] < cycles_limit:
                    OPEN_CYCLE_STATE['morning_count'] += 1
                    ok = True
            elif session == 'afternoon':
                if not OPEN_CYCLE_STATE['afternoon_started']:
                    OPEN_CYCLE_STATE['afternoon_started'] = True
                    OPEN_CYCLE_STATE['afternoon_count'] = 0
                if OPEN_CYCLE_STATE['afternoon_count'] < cycles_limit:
                    OPEN_CYCLE_STATE['afternoon_count'] += 1
                    ok = True
    except Exception:
        ok = False
    return ok

