# ===== 分批金额门槛策略（优化版）=====
# 1) 金额阶梯上限：限制“最多允许的分批数”（单位: 元）
# 2) 单批最低金额保护：确保拆分后每批资金≥下限
BATCH_AMOUNT_POLICY = [
    (1200000, 6),
    (800000, 5),
    (500000, 4),
    (300000, 3),
    (200000, 2),
    (0, 1),   # 20万以下一律不分批
]

# 单批最低金额（单位: 元），用于防止金额被过度切割导致每批规模过小
PER_BATCH_MIN_AMOUNT = 30000.0

# 首次建仓最低金额（单位: 元），用于避免首次建仓出现过小单
MIN_FIRST_POSITION_AMOUNT = 30000.0

HIGH_PRICE_CEILING = 120.0

def get_layered_params(total_asset: float) -> dict:
    """
    按账户规模返回分层参数：资金利用率/最大持仓/单股上限建议/最小建仓/单批阈值/流动性门槛/并发上限
    仅本函数返回建议值，真正执行时保留现有 capital_manager 流程与单股上限检查，
    并在运行时覆盖 MIN_FIRST_POSITION_AMOUNT / PER_BATCH_MIN_AMOUNT 两个阈值。

    在此基础上，根据当前市场环境(bull/sideways/bear)做温和调整：
    - bull: 略微提升资金利用率与最大持仓，适度放宽流动性门槛
    - bear: 明显降低资金利用率与最大持仓，适度提高流动性门槛
    - sideways: 保持基准值
    """
    ta = float(total_asset or 0)

    # 1) 先按账户规模给出基准档位
    if ta <= 30_000:
        base = {
            'utilization': 0.60, 'max_positions': 3, 'per_stock_cap': 0.50,
            'min_first_amount': 3_000, 'per_batch_min_amount': 2_000,
            'liquidity_floor': 3_000_000, 'concurrency_limit': 1,
            'min_add_ratio': 0.10
        }
    elif ta <= 60_000:
        base = {
            'utilization': 0.60, 'max_positions': 4, 'per_stock_cap': 0.35,
            'min_first_amount': 5_000, 'per_batch_min_amount': 4_000,
            'liquidity_floor': 5_000_000, 'concurrency_limit': 2,
            'min_add_ratio': 0.10
        }
    elif ta <= 100_000:
        base = {
            'utilization': 0.65, 'max_positions': 5, 'per_stock_cap': 0.25,
            'min_first_amount': 8_000, 'per_batch_min_amount': 6_000,
            'liquidity_floor': 6_000_000, 'concurrency_limit': 2,
            'min_add_ratio': 0.10
        }
    elif ta <= 500_000:
        base = {
            'utilization': 0.70, 'max_positions': 7, 'per_stock_cap': 0.20,
            'min_first_amount': 10_000, 'per_batch_min_amount': 8_000,
            'liquidity_floor': 8_000_000, 'concurrency_limit': 3,
            'min_add_ratio': 0.10
        }
    elif ta <= 2_000_000:
        base = {
            'utilization': 0.75, 'max_positions': 10, 'per_stock_cap': 0.18,
            'min_first_amount': 20_000, 'per_batch_min_amount': 15_000,
            'liquidity_floor': 15_000_000, 'concurrency_limit': 4,
            'min_add_ratio': 0.10
        }
    elif ta <= 5_000_000:
        base = {
            'utilization': 0.78, 'max_positions': 10, 'per_stock_cap': 0.20,
            'min_first_amount': 30_000, 'per_batch_min_amount': 20_000,
            'liquidity_floor': 20_000_000, 'concurrency_limit': 4,
            'min_add_ratio': 0.10
        }
    elif ta <= 10_000_000:
        base = {
            'utilization': 0.80, 'max_positions': 12, 'per_stock_cap': 0.22,
            'min_first_amount': 50_000, 'per_batch_min_amount': 30_000,
            'liquidity_floor': 25_000_000, 'concurrency_limit': 5,
            'min_add_ratio': 0.10
        }
    else:
        base = {
            'utilization': 0.80, 'max_positions': 14, 'per_stock_cap': 0.25,
            'min_first_amount': 80_000, 'per_batch_min_amount': 50_000,
            'liquidity_floor': 30_000_000, 'concurrency_limit': 5,
            'min_add_ratio': 0.10
        }

    # 2) 根据当前市场环境做温和调整（不改变键结构）
    try:
        env = globals().get('current_market_environment', 'sideways')
        env = str(env).lower()
    except Exception:
        env = 'sideways'

    util = float(base.get('utilization', 0.7) or 0.7)
    max_pos = int(base.get('max_positions', 7) or 7)
    floor = float(base.get('liquidity_floor', 0) or 0)

    if env == 'bull':
        util *= 1.05  # 牛市略微提高整体利用率
        max_pos = int(round(max_pos * 1.1))  # 牛市适度增加持仓数
        floor *= 0.8  # 牛市适度放宽流动性门槛
    elif _is_bearish(env):
        util *= 0.80  # 熊市明显降低整体利用率
        max_pos = int(round(max_pos * 0.8))  # 熊市适度减少持仓数
        floor *= 1.2  # 熊市提高流动性门槛
    # sideways 或未知环境不做调整

    # 合理边界保护
    util = max(0.3, min(util, 0.85))
    max_pos = max(3, min(max_pos, 20))

    base['utilization'] = util
    base['max_positions'] = max_pos
    base['liquidity_floor'] = floor

    return base

def get_avg_turnover(context, stock_code: str, days: int = 5) -> float:
    """
    获取近N日日均成交额(元)。优先使用amount字段，缺失时用close*volume近似。
    """
    try:
        md = get_optimized_market_data_ex(stock_codes=[stock_code], fields=['amount','close','volume'], period='1d', count=days, context=context)
        if not md or stock_code not in md:
            return 0.0
        amounts = []
        data = md[stock_code]
        if 'amount' in data and data['amount']:
            amounts = [float(x) for x in data['amount'] if x is not None]
        else:
            closes = data.get('close', []) or []
            vols = data.get('volume', []) or []
            lim = min(len(closes), len(vols))
            for i in range(lim):
                try:
                    amounts.append(float(closes[i]) * float(vols[i]))
                except Exception:
                    continue
        if not amounts:
            return 0.0
        return sum(amounts) / len(amounts)
    except Exception:
        return 0.0

def get_market_env_name(context) -> str:
    """获取当前市场环境标识，默认'sideways'。"""
    try:
        env = getattr(context, 'current_market_env', None)
        if not env:
            env = globals().get('current_market_environment', 'sideways')
        return str(env).lower()
    except Exception:
        return 'sideways'

def adjust_liquidity_floor(base_floor: float, market_env: str) -> float:
    """根据市场环境调整流动性门槛。牛市适度放宽，熊市适度提高。"""
    try:
        multipliers = {
            'bull': 0.8,
            'bear': 1.2,
            'sideways': 1.0
        }
        m = multipliers.get(str(market_env).lower(), 1.0)
        return float(base_floor) * m
    except Exception:
        return float(base_floor)

def get_realized_volatility(context, stock_code: str, days: int = 20) -> float:
    try:
        md = get_optimized_market_data_ex(stock_codes=[stock_code], fields=['close'], period='1d', count=days+1, context=context)
        if not md or stock_code not in md:
            return 0.0
        closes = md[stock_code].get('close', []) or []
        if len(closes) < 2:
            return 0.0
        rets = []
        for i in range(1, len(closes)):
            try:
                if closes[i-1] and closes[i-1] > 0:
                    rets.append((float(closes[i]) - float(closes[i-1])) / float(closes[i-1]))
            except Exception:
                continue
        if not rets:
            return 0.0
        mean = sum(rets) / len(rets)
        var = sum((r - mean) * (r - mean) for r in rets) / max(1, len(rets)-1)
        return var ** 0.5
    except Exception:
        return 0.0

def get_limit_ratio(context, stock_code: str, days: int = 20) -> float:
    try:
        md = get_optimized_market_data_ex(stock_codes=[stock_code], fields=['close'], period='1d', count=days+1, context=context)
        if not md or stock_code not in md:
            return 0.0
        closes = md[stock_code].get('close', []) or []
        if len(closes) < 2:
            return 0.0
        limit_days = 0
        total = 0
        for i in range(1, len(closes)):
            try:
                if closes[i-1] and closes[i-1] > 0:
                    ret = (float(closes[i]) - float(closes[i-1])) / float(closes[i-1])
                    if ret >= 0.095 or ret <= -0.095:
                        limit_days += 1
                    total += 1
            except Exception:
                continue
        if total == 0:
            return 0.0
        return limit_days / total
    except Exception:
        return 0.0

def build_liquidity_multiplier(context, stock_code: str) -> float:
    try:
        vol = get_realized_volatility(context, stock_code, days=20)
        lim = get_limit_ratio(context, stock_code, days=20)
        vol_mult = 1.0
        if vol >= 0.05:
            vol_mult = 1.3
        elif vol >= 0.03:
            vol_mult = 1.15
        elif vol <= 0.01:
            vol_mult = 0.9
        lim_mult = 1.0
        if lim >= 0.2:
            lim_mult = 1.3
        elif lim >= 0.1:
            lim_mult = 1.15
        mult = vol_mult * lim_mult
        if mult < 0.8:
            mult = 0.8
        if mult > 1.5:
            mult = 1.5
        return mult
    except Exception:
        return 1.0

def get_cached_container(context):
    try:
        cache = getattr(context, '_tick_cache', None)
        if cache is None:
            cache = {
                'avg_turnover_5d': {},
                'vol_20d': {},
                'limit_ratio_20d': {},
                'multiplier': {}
            }
            setattr(context, '_tick_cache', cache)
        return cache
    except Exception:
        return None

def get_cached_avg_turnover(context, stock_code: str, days: int = 5) -> float:
    cache = get_cached_container(context)
    if not cache:
        return get_avg_turnover(context, stock_code, days)
    k = (stock_code, days)
    if k in cache['avg_turnover_5d']:
        return cache['avg_turnover_5d'][k]
    v = get_avg_turnover(context, stock_code, days)
    cache['avg_turnover_5d'][k] = v
    return v

def get_cached_realized_volatility(context, stock_code: str, days: int = 20) -> float:
    cache = get_cached_container(context)
    if not cache:
        return get_realized_volatility(context, stock_code, days)
    k = (stock_code, days)
    if k in cache['vol_20d']:
        return cache['vol_20d'][k]
    v = get_realized_volatility(context, stock_code, days)
    cache['vol_20d'][k] = v
    return v

def get_cached_limit_ratio(context, stock_code: str, days: int = 20) -> float:
    cache = get_cached_container(context)
    if not cache:
        return get_limit_ratio(context, stock_code, days)
    k = (stock_code, days)
    if k in cache['limit_ratio_20d']:
        return cache['limit_ratio_20d'][k]
    v = get_limit_ratio(context, stock_code, days)
    cache['limit_ratio_20d'][k] = v
    return v

def get_cached_liquidity_multiplier(context, stock_code: str) -> float:
    cache = get_cached_container(context)
    if not cache:
        return build_liquidity_multiplier(context, stock_code)
    if stock_code in cache['multiplier']:
        return cache['multiplier'][stock_code]
    # 构建时复用已缓存的波动率与涨跌停占比
    _ = get_cached_realized_volatility(context, stock_code, 20)
    _ = get_cached_limit_ratio(context, stock_code, 20)
    v = build_liquidity_multiplier(context, stock_code)
    cache['multiplier'][stock_code] = v
    return v

def map_signal_strength_to_pb(strength: int) -> tuple:
    """
    基于信号强度映射保守的胜率p与赔率b，缺省时返回中性参数。
    返回(p, b)
    """
    try:
        s = int(strength or 0)
    except Exception:
        s = 0
    mapping = {
        6: (0.58, 1.40),  # perfect
        5: (0.55, 1.30),  # excellent
        4: (0.53, 1.25),  # premium/confirmed高
        3: (0.52, 1.20),  # confirmed
        2: (0.50, 1.15),  # detected
        1: (0.50, 1.10),  # pullback/弱
        0: (0.50, 1.10)
    }
    return mapping.get(s, (0.50, 1.10))

def compute_kelly_weight(strength: int, k_fraction: float = 0.33) -> float:
    """
    计算分数凯利权重：f = k * (p - (1-p)/b)，负值置0。
    """
    p, b = map_signal_strength_to_pb(strength)
    edge = p - (1 - p) / max(b, 1e-6)
    f_star = max(0.0, edge)
    return max(0.0, float(k_fraction) * f_star)

