ADD_POSITION_ALLOWED_SIGNAL_LEVELS = ['confirmed', 'premium', 'excellent', 'perfect', 'strong', 'very_strong']
ADD_POSITION_MIN_NUMERIC_LEVEL = 4
ADD_POSITION_MAX_CHASE_PCT = 0.03     # 追高最大+3%
