def get_allowed_batches_by_amount(amount: float) -> int:
    """
    按金额返回允许的最大分批数，并叠加“单批最低金额”保护。
    规则：最终允许批数 = min(金额阶梯允许的上限, floor(amount / PER_BATCH_MIN_AMOUNT))，且至少为1。
    输入异常时回退为1。
    """
    try:
        a = float(amount or 0.0)
        # 阶梯上限
        by_amount_cap = 1
        for threshold, batches in BATCH_AMOUNT_POLICY:
            if a >= threshold:
                by_amount_cap = int(batches)
                break
        # 单批下限约束
        by_min_batches = int(max(1, math.floor(a / float(PER_BATCH_MIN_AMOUNT)) if PER_BATCH_MIN_AMOUNT > 0 else 1))
        return max(1, min(by_amount_cap, by_min_batches))
    except Exception:
        return 1

_dyn_threshold_guard = {
    'last_key': None
}

def _log_dynamic_threshold(env: str, signal_count: int, threshold: int, msg: str):
    """仅在动态阈值的"语义桶"或阈值发生变化时打印日志，避免重复刷屏。"""
    try:
        # 定义语义桶：根据环境与信号规模归类
        if env == 'bull' and signal_count > 100:
            bucket = 'bull_high'
        elif _is_bearish(env):
            bucket = 'bear'
        elif env == 'sideways' and signal_count < 20:
            bucket = 'sideways_low'
        else:
            bucket = 'default'
        key = (env, bucket, int(threshold))
        if _dyn_threshold_guard.get('last_key') == key:
            return
        logger.info(msg)
        _dyn_threshold_guard['last_key'] = key
    except Exception:
        # 兜底：异常时直接打印一次
        logger.info(msg)

def _get_cycle_id(ContextInfo) -> str:
    """返回当前周期ID（日期+分钟），用于日志去重。"""
    try:
        now = datetime.now()
        return now.strftime('%Y%m%d_%H%M')
    except Exception:
        return str(int(time_module.time() // 60))

def _should_log_once(ContextInfo, key: str) -> bool:
    """同一周期内同一key仅记录一次详细日志。"""
    try:
        guard = getattr(ContextInfo, '_log_once_guard', None)
        if not isinstance(guard, dict):
            guard = {}
            setattr(ContextInfo, '_log_once_guard', guard)
        cycle = _get_cycle_id(ContextInfo)
        if cycle not in guard:
            guard.clear()
            guard[cycle] = set()
        s = guard[cycle]
        if key in s:
            return False
        s.add(key)
        return True
    except Exception:
        return True

