def get_runtime_refill_config(context) -> dict:
    """
    轻量运行时配置读取：可通过 context.runtime_config['same_round_refill'] 动态覆盖：
      - enabled: bool
      - rounds: int
      - refill_min_amount: float
    未设置时回退到全局常量。
    """
    try:
        rc = getattr(context, 'runtime_config', None)
        if not isinstance(rc, dict):
            return {
                'enabled': ENABLE_SAME_ROUND_REFILL,
                'rounds': MAX_SAME_ROUND_REFILL_ROUNDS,
                'refill_min_amount': REFILL_MIN_AMOUNT,
            }
        cfg = (rc or {}).get('same_round_refill') or {}
        return {
            'enabled': cfg.get('enabled', ENABLE_SAME_ROUND_REFILL),
            'rounds': cfg.get('rounds', MAX_SAME_ROUND_REFILL_ROUNDS),
            'refill_min_amount': cfg.get('refill_min_amount', REFILL_MIN_AMOUNT),
        }
    except Exception:
        return {
            'enabled': ENABLE_SAME_ROUND_REFILL,
            'rounds': MAX_SAME_ROUND_REFILL_ROUNDS,
            'refill_min_amount': REFILL_MIN_AMOUNT,
        }

