def update_cci_down_config(context, enabled=None, only_negative=None, once_per_day=None):
    """运行时更新 CCI 下穿卖出配置。仅更新提供的字段。"""
    try:
        rc = getattr(context, 'runtime_config', None)
        if not isinstance(rc, dict):
            setattr(context, 'runtime_config', {})
            rc = context.runtime_config
        cur = rc.get('cci_down_sell') or {}
        if enabled is not None:
            cur['enabled'] = bool(enabled)
        if only_negative is not None:
            cur['only_negative'] = bool(only_negative)
        if once_per_day is not None:
            cur['once_per_day'] = bool(once_per_day)
        rc['cci_down_sell'] = cur
        setattr(context, 'runtime_config', rc)
        return True
    except Exception:
        return False

def update_same_round_refill_config(context, enabled=None, rounds=None, refill_min_amount=None):
    """
    轻量运行时配置写入：在不重启策略的情况下，动态调整同轮补买参数。
    仅更新非None的字段。
    """
    try:
        if not hasattr(context, 'runtime_config') or not isinstance(getattr(context, 'runtime_config'), dict):
            setattr(context, 'runtime_config', {})
        rc = getattr(context, 'runtime_config')
        sub = rc.get('same_round_refill') or {}
        if enabled is not None:
            sub['enabled'] = bool(enabled)
        if rounds is not None:
            sub['rounds'] = int(rounds)
        if refill_min_amount is not None:
            sub['refill_min_amount'] = float(refill_min_amount)
        rc['same_round_refill'] = sub
        setattr(context, 'runtime_config', rc)
        return True
    except Exception:
        return False

