def get_order_status_profile(ContextInfo) -> dict:
    """根据 ContextInfo 自动选择订单状态码配置档。
    选择优先级：ContextInfo.broker -> ContextInfo.platform -> ContextInfo.accIDType -> 'default'
    """
    try:
        broker = (getattr(ContextInfo, 'broker', '') or '').strip().lower()
        platform = (getattr(ContextInfo, 'platform', '') or '').strip().lower()
        acc_type = (getattr(ContextInfo, 'accIDType', '') or '').strip().lower()

        # 简单归一化匹配
        keys = [broker, platform, acc_type]
        alias_map = {
            'iquant': 'guosen_iquant',
            'guosen': 'guosen_iquant',
            'guosen_iquant': 'guosen_iquant',
        }
        for k in keys:
            if not k:
                continue
            norm = alias_map.get(k, k)
            if norm in ORDER_STATUS_PROFILES:
                return ORDER_STATUS_PROFILES[norm]
        return ORDER_STATUS_PROFILES['default']
    except Exception:
        return ORDER_STATUS_PROFILES['default']

