def _accumulate_realtime_total(stock_code: str, add_amount: float):
    try:
        if add_amount is None:
            return
        add_amount = float(add_amount)
        if add_amount <= 0:
            return
        with batch_total_registry_lock:
            batch_total_registry['total'] = float(batch_total_registry.get('total', 0.0)) + add_amount
            by_stock = batch_total_registry.get('by_stock', {})
            by_stock[stock_code] = float(by_stock.get(stock_code, 0.0)) + add_amount
            batch_total_registry['by_stock'] = by_stock
    except Exception:
        pass

