def validate_stock_code(stock_code):
    """
    验证股票代码是否有效
    
    Args:
        stock_code: 股票代码
    
    Returns:
        bool: 是否为有效的股票代码
    """
    try:
        if not stock_code or stock_code is None:
            return False
        
        stock_str = str(stock_code).strip()
        
        # 检查基本格式：6位数字.交易所
        if not re.match(r'^\d{6}\.(SH|SZ)$', stock_str):
            return False
        
        code_part = stock_str[:6]
        market_part = stock_str[7:]
        
        # 验证代码和市场的匹配关系
        if market_part == 'SH':
            # 上海市场：6开头的股票，5开头的基金
            return code_part.startswith(('6', '5'))
        elif market_part == 'SZ':
            # 深圳市场：0、2、3开头
            return code_part.startswith(('0', '2', '3', '8', '9'))
        
        return False
    except Exception:
        return False

def format_stock_code(stock_code):
    """
    格式化股票代码，确保包含交易所后缀
    
    Args:
        stock_code: 股票代码，可以是字符串或数字
    
    Returns:
        str: 格式化后的股票代码，如 '000001.SZ'，无效代码返回空字符串
    """
    try:
        # 修复None值处理BUG
        if stock_code is None:
            logger.warning("[format_stock_code] - 股票代码为None，返回空字符串")
            return ""
        
        # 处理数字类型输入
        if isinstance(stock_code, (int, float)):
            try:
                # 确保是整数
                if stock_code == int(stock_code):
                    stock_code_str = str(int(stock_code))
                else:
                    logger.warning(f"[format_stock_code] - 无法识别股票代码格式: {stock_code}")
                    return ""
            except Exception:
                stock_code_str = str(stock_code)
            
            # 检查数字是否为有效的股票代码长度（通常6位）
            if len(stock_code_str) != 6:
                logger.info(f"[format_stock_code] - 股票代码长度不符合标准(需6位): {stock_code}")
                return ""
            
            stock_code = stock_code_str
        else:
            stock_code = str(stock_code).strip()
        
        # 检查是否包含特殊字符或非法字符
        if re.search(r'[^\w\.\-]', stock_code):
            logger.warning(f"[format_stock_code] - 无法识别股票代码格式: {stock_code}")
            return ""
        
        # 处理包含换行符、制表符等特殊字符的情况
        if '\n' in stock_code or '\t' in stock_code or len(stock_code.split()) > 1:
            logger.warning(f"[format_stock_code] - 无法识别股票代码格式: {repr(stock_code)}")
            return ""
        
        # 处理非标准后缀格式（如 .深圳）
        if '.' in stock_code:
            parts = stock_code.split('.')
            if len(parts) == 2:
                base_code, suffix = parts
                # 标准化后缀
                if suffix.upper() in ['SH', '上海', '沪']:
                    formatted_code = base_code + '.SH'
                elif suffix.upper() in ['SZ', '深圳', '深']:
                    formatted_code = base_code + '.SZ'
                else:
                    # 尝试根据代码前缀推断
                    if base_code.isdigit() and len(base_code) == 6:
                        if base_code.startswith('6'):
                            formatted_code = base_code + '.SH'
                        elif base_code.startswith(('0', '2', '3')):
                            formatted_code = base_code + '.SZ'
                        else:
                            logger.warning(f"[format_stock_code] - 无法识别股票代码格式: {stock_code}")
                            return ""
                    else:
                        logger.warning(f"[format_stock_code] - 无法识别股票代码格式: {stock_code}")
                        return ""
                
                # 验证格式化后的代码
                if validate_stock_code(formatted_code):
                    return formatted_code
                else:
                    logger.warning(f"[format_stock_code] - 格式化后验证失败: {formatted_code}")
                    return ""
            else:
                logger.warning(f"[format_stock_code] - 无法识别股票代码格式: {stock_code}")
                return ""
        
        # 检查是否为6位数字的标准股票代码
        if not re.match(r'^\d{6}$', stock_code):
            logger.warning(f"[format_stock_code] - 无法识别股票代码格式: {stock_code}")
            return ""
            
        # 根据股票代码规则添加后缀
        if stock_code.startswith('6'):
            formatted_code = stock_code + '.SH'
        elif stock_code.startswith(('0', '2', '3')):
            formatted_code = stock_code + '.SZ'
        else:
            # 无法识别的代码前缀
            logger.warning(f"[format_stock_code] - 无法识别股票代码格式: {stock_code}")
            return ""
        
        # 最终验证
        if validate_stock_code(formatted_code):
            return formatted_code
        else:
            logger.warning(f"[format_stock_code] - 最终验证失败: {formatted_code}")
            return ""
    except Exception as e:
        logger.error(f"[format_stock_code] - 格式化股票代码失败: {e}")
        return ""

def clean_stock_universe(stock_list):
    """
    清理股票池，移除无效的股票代码
    
    Args:
        stock_list: 原始股票代码列表
    
    Returns:
        list: 清理后的有效股票代码列表
    """
    if not stock_list:
        return []
    
    valid_stocks = []
    invalid_stocks = []
    
    for stock in stock_list:
        formatted_code = format_stock_code(stock)
        if formatted_code:
            valid_stocks.append(formatted_code)
        else:
            invalid_stocks.append(stock)
    
    if invalid_stocks:
        logger.warning(f"发现并移除无效股票代码 {len(invalid_stocks)} 只: {invalid_stocks[:10]}{'...' if len(invalid_stocks) > 10 else ''}")
    
    logger.info(f"股票池清理完成: 原始 {len(stock_list)} 只 -> 有效 {len(valid_stocks)} 只")
    return valid_stocks

