# ===== 实时价格与盘口兼容封装 =====
def get_realtime_price_safe(context, stock_code: str) -> Optional[float]:
    """统一的实时价格获取封装：
    - 尝试 get_realtime_price(code)
    - 退化到 get_realtime_quote()/get_quote()
    - 再退化到 get_tick()/get_ticks() 最新成交
    - 最后退化到日线收盘价
    返回 float 或 None
    """
    code = stock_code
    # 0) ContextInfo.get_full_tick (文档推荐接口，仅实盘)
    try:
        if hasattr(context, 'get_full_tick') and callable(getattr(context, 'get_full_tick')):
            data = context.get_full_tick([code])
            # 兼容返回结构：可能是列表或字典
            rec = None
            if isinstance(data, list) and len(data) > 0:
                rec = data[0]
            elif isinstance(data, dict):
                # 可能返回 {code: {...}} 或 {'data':[...]} 等
                rec = data.get(code) or (data.get('data')[0] if isinstance(data.get('data'), list) and data.get('data') else None) or data
            if isinstance(rec, dict):
                v = rec.get('lastPrice') or rec.get('last') or rec.get('price')
                if v and float(v) > 0:
                    return float(v)
    except Exception:
        pass
    # 1) get_realtime_price
    try:
        if 'get_realtime_price' in globals():
            px = float(get_realtime_price(code) or 0)
            if px > 0:
                return px
    except Exception:
        pass
    # 2) get_realtime_quote / get_quote
    try:
        if 'get_realtime_quote' in globals():
            q = get_realtime_quote(code)
            for k in ('last', 'last_price', 'price', 'close'):
                v = q.get(k) if isinstance(q, dict) else getattr(q, k, None)
                if v and float(v) > 0:
                    return float(v)
    except Exception:
        pass
    try:
        if 'get_quote' in globals():
            q = get_quote(code)
            for k in ('last', 'last_price', 'price', 'close'):
                v = q.get(k) if isinstance(q, dict) else getattr(q, k, None)
                if v and float(v) > 0:
                    return float(v)
    except Exception:
        pass
    # 3) get_tick / get_ticks
    try:
        if 'get_tick' in globals():
            t = get_tick(code)
            v = None
            if isinstance(t, dict):
                v = t.get('last') or t.get('price')
            else:
                for k in ('last', 'price', 'close'):
                    v = getattr(t, k, None) or v
            if v and float(v) > 0:
                return float(v)
    except Exception:
        pass
    try:
        if 'get_ticks' in globals():
            ts = get_ticks(code, 1)
            if ts:
                r = ts[-1]
                v = r.get('last') if isinstance(r, dict) else getattr(r, 'last', None)
                if v and float(v) > 0:
                    return float(v)
    except Exception:
        pass
    # 4) fallback: 日线收盘
    try:
        bars = get_market_data_ex(code, ['close'], 'D', 1)
        if bars and len(bars) > 0:
            v = float(bars[-1].get('close', 0) or 0)
            if v > 0:
                return v
    except Exception:
        pass
    return None

def get_limit_up_price_safe(context, stock_code: str, prev_close: float = None) -> float:
    try:
        code = format_stock_code(stock_code) if 'format_stock_code' in globals() else str(stock_code)
        try:
            det = getattr(context, 'details', None)
            if isinstance(det, dict) and code in det:
                d = det.get(code)
                if isinstance(d, dict):
                    v = d.get('UpStopPrice') or d.get('UpStop') or d.get('UpperLimit') or d.get('UpperLimitPrice')
                    if v is not None and float(v) > 0:
                        return float(v)
                else:
                    v = getattr(d, 'UpStopPrice', 0) or getattr(d, 'UpStop', 0) or getattr(d, 'UpperLimit', 0)
                    if v and float(v) > 0:
                        return float(v)
        except Exception:
            pass
        try:
            if context is not None and hasattr(context, 'get_full_tick') and callable(getattr(context, 'get_full_tick')):
                tk = context.get_full_tick([code])
                rec = None
                if isinstance(tk, dict):
                    rec = tk.get(code) or tk
                elif isinstance(tk, list) and tk:
                    rec = tk[0]
                if isinstance(rec, dict):
                    for k in ('upperLimitPrice', 'highLimit', 'limitUp', 'upLimit', 'UpStopPrice', 'UpperLimitPrice'):
                        v = rec.get(k)
                        if v is not None and float(v) > 0:
                            return float(v)
        except Exception:
            pass
        try:
            if 'get_instrumentdetail' in globals() and callable(globals().get('get_instrumentdetail')):
                detail = get_instrumentdetail(code, context)
                v = getattr(detail, 'UpStopPrice', 0) if detail is not None else 0
                if v and float(v) > 0:
                    return float(v)
        except Exception:
            pass
        pc = 0.0
        try:
            if prev_close is not None and float(prev_close) > 0:
                pc = float(prev_close)
        except Exception:
            pc = 0.0
        if pc <= 0:
            try:
                bars = get_market_data_ex(code, ['close'], 'D', 2)
                if bars and len(bars) >= 2:
                    pc = float(bars[-2].get('close', 0) or 0)
            except Exception:
                pc = 0.0
        if pc <= 0:
            return 0.0
        is_st = False
        try:
            if 'is_st_stock' in globals() and callable(globals().get('is_st_stock')):
                is_st = bool(is_st_stock(code, context))
        except Exception:
            is_st = False
        ratio = 1.05 if is_st else 1.10
        return float(round(pc * ratio, 2))
    except Exception:
        return 0.0

def is_resealing_likely(context, stock_code: str, limit_up_price: float, cfg: dict) -> bool:
    """基于盘口委买强度的回封判据（若API可用）。
    - 读取一档/多档委买，判断在涨停价附近是否存在显著的封单量。
    - 需要的API（任一可用）：get_order_book/get_orderbook/get_depth
    配置示例：{'enabled': True, 'min_bid_volume': 100000, 'price_match': True}
    """
    try:
        if not bool((cfg or {}).get('enabled', False)):
            return False
        unit = str((cfg or {}).get('unit', 'hand')).lower()
        price_match = bool((cfg or {}).get('price_match', True))
        tol = float((cfg or {}).get('price_tolerance', max(0.01, limit_up_price * 0.0005)))
        # 阈值解析：默认按“手(hand)”口径，与现有上下文一致（volume 精确到手）
        if unit == 'share':
            min_bid_shares = int((cfg or {}).get('min_bid_shares', (cfg or {}).get('min_bid_volume', 20000000)))
        else:
            min_bid_lots = int((cfg or {}).get('min_bid_lots', (cfg or {}).get('min_bid_volume', 200000)))

        # A) 优先用 ContextInfo.get_full_tick（文档接口）
        try:
            if hasattr(context, 'get_full_tick') and callable(getattr(context, 'get_full_tick')):
                data = context.get_full_tick([stock_code])
                rec = None
                if isinstance(data, list) and len(data) > 0:
                    rec = data[0]
                elif isinstance(data, dict):
                    rec = data.get(stock_code) or (data.get('data')[0] if isinstance(data.get('data'), list) and data.get('data') else None) or data
                if isinstance(rec, dict):
                    bid_prices = rec.get('bidPrice') or []
                    bid_vols = rec.get('bidVol') or []
                    total_lots = 0
                    matched = False
                    for i in range(min(5, len(bid_prices), len(bid_vols))):
                        px = float(bid_prices[i])
                        vol_lots = int(bid_vols[i])
                        total_lots += max(0, vol_lots)
                        if price_match and abs(px - limit_up_price) <= tol:
                            matched = True
                    if unit == 'share':
                        total_shares = total_lots * 100
                        if total_shares >= min_bid_shares and (matched or not price_match):
                            return True
                    else:
                        if total_lots >= min_bid_lots and (matched or not price_match):
                            return True
        except Exception:
            pass

        # B) 回退到通用 orderbook 接口
        ob = None
        for fn in ('get_order_book', 'get_orderbook', 'get_depth'):
            if fn in globals():
                try:
                    ob = globals()[fn](stock_code)
                    break
                except Exception:
                    ob = None
        if not ob:
            return False
        bids = None
        if isinstance(ob, dict):
            bids = ob.get('bids') or ob.get('Bid') or ob.get('bid')
        else:
            for attr in ('bids', 'Bid', 'bid'):
                if hasattr(ob, attr):
                    bids = getattr(ob, attr)
                    break
        if not bids:
            return False
        total_lots = 0
        matched = False
        for i, lvl in enumerate(bids[:5] if isinstance(bids, list) else []):
            try:
                px = float(lvl[0]) if isinstance(lvl, (list, tuple)) and len(lvl) >= 2 else float(lvl.get('price', 0))
                vol_lots = int(lvl[1]) if isinstance(lvl, (list, tuple)) and len(lvl) >= 2 else int(lvl.get('volume', 0))
                total_lots += max(0, vol_lots)
                if price_match and abs(px - limit_up_price) <= tol:
                    matched = True
            except Exception:
                continue
        if unit == 'share':
            total_shares = total_lots * 100
            if total_shares >= min_bid_shares and (matched or not price_match):
                return True
        else:
            if total_lots >= min_bid_lots and (matched or not price_match):
                return True
        return False
    except Exception:
        return False

def get_market_env_display_name(env):
    """
    获取市场环境的中文名称
    
    参数:
    env: 市场环境代码
    
    返回:
    str: 中文名称
    """
    env_names = {
        'bull': '牛市',
        'bear': '熊市',
        'extreme_bear': '极端熊市',
        'sideways': '震荡市',
        'volatile': '震荡市'
    }
    return env_names.get(env, '未知')


def _is_bearish(env):
    """判断市场环境是否属于熊市类别（bear 或 extreme_bear）"""
    return env in ('bear', 'extreme_bear')


def _in_time_windows(now_t, windows) -> bool:
    try:
        if not windows:
            return True
        for w in windows:
            if not isinstance(w, (list, tuple)) or len(w) != 4:
                continue
            sh, sm, eh, em = int(w[0]), int(w[1]), int(w[2]), int(w[3])
            if time(sh, sm) <= now_t <= time(eh, em):
                return True
        return False
    except Exception:
        return True


_first_board_scan_cache = {'ts': 0, 'codes': [], 'map': {}}


def _tick_get(rec: dict, keys: tuple, default=None):
    try:
        for k in keys:
            if k in rec and rec.get(k) is not None:
                return rec.get(k)
        return default
    except Exception:
        return default


def _resolve_first_board_entry_profile(context) -> dict:
    """解析首板二段式仓位画像（开盘试仓/确认加仓），按市场环境自适应。"""
    try:
        env = None
        try:
            env = getattr(context, 'current_market_env', None)
        except Exception:
            env = None
        if not env:
            try:
                env = globals().get('current_market_environment', None)
            except Exception:
                env = None
        env = str(env or 'sideways').lower()

        default_trial = float(FIRST_BOARD_OPEN_TRIAL_RATIO)
        default_confirm = float(FIRST_BOARD_CONFIRM_POSITION_RATIO if 'FIRST_BOARD_CONFIRM_POSITION_RATIO' in globals() else FIRST_BOARD_POSITION_RATIO)

        cfg_map = FIRST_BOARD_ENTRY_PROFILE_BY_ENV if isinstance(globals().get('FIRST_BOARD_ENTRY_PROFILE_BY_ENV', None), dict) else {}
        alias_map = {
            'up': 'bull',
            'strong_bull': 'bull',
            'down': 'bear',
            'weak_bear': 'bear',
        }
        env_key = alias_map.get(env, env)
        env_cfg = cfg_map.get(env_key, {}) if isinstance(cfg_map, dict) else {}

        trial_ratio = float(env_cfg.get('trial_ratio', default_trial))
        confirm_ratio = float(env_cfg.get('confirm_ratio', default_confirm))

        trial_ratio = max(0.05, min(0.60, trial_ratio))
        confirm_ratio = max(trial_ratio, min(0.90, confirm_ratio))
        return {
            'env': env_key,
            'trial_ratio': trial_ratio,
            'confirm_ratio': confirm_ratio,
        }
    except Exception:
        return {
            'env': 'sideways',
            'trial_ratio': float(FIRST_BOARD_OPEN_TRIAL_RATIO),
            'confirm_ratio': float(FIRST_BOARD_CONFIRM_POSITION_RATIO if 'FIRST_BOARD_CONFIRM_POSITION_RATIO' in globals() else FIRST_BOARD_POSITION_RATIO),
        }


def scan_first_board_pool(context, universe_codes, held_set=None):
    try:
        if not bool(FIRST_BOARD_ENABLED) or not bool(FIRST_BOARD_INDEPENDENT_SCAN):
            return [], {}

        try:
            now_ts = int(time_module.time())
        except Exception:
            now_ts = 0
        try:
            cd = int(FIRST_BOARD_SCAN_COOLDOWN_SECONDS)
        except Exception:
            cd = 0
        if cd > 0 and now_ts > 0:
            try:
                last_ts = int((_first_board_scan_cache or {}).get('ts', 0) or 0)
            except Exception:
                last_ts = 0
            if last_ts > 0 and (now_ts - last_ts) < cd:
                try:
                    cc = list((_first_board_scan_cache or {}).get('codes') or [])
                    cm = dict((_first_board_scan_cache or {}).get('map') or {})
                    return cc, cm
                except Exception:
                    return [], {}

        now_t = datetime.now().time()
        if not _in_time_windows(now_t, FIRST_BOARD_TIME_WINDOWS):
            return [], {}

        hs = set(held_set or [])
        codes = []
        try:
            max_u = int(FIRST_BOARD_SCAN_MAX_UNIVERSE)
        except Exception:
            max_u = 900

        for c in list(universe_codes or []):
            s = str(c)
            if s in hs:
                continue
            if s.startswith(('300', '301', '68')):
                continue
            codes.append(s)
            if max_u > 0 and len(codes) >= max_u:
                break

        try:
            if codes and 'filter_risky_stocks' in globals() and callable(globals().get('filter_risky_stocks')):
                codes = list(filter_risky_stocks(codes, context))
        except Exception:
            pass

        if not codes:
            return [], {}

        fmt_map = {}
        fmt_list = []
        for s in codes:
            try:
                sf = format_stock_code(s) if 'format_stock_code' in globals() else s
            except Exception:
                sf = s
            fmt_map[sf] = s
            fmt_list.append(sf)

        tk = None
        try:
            if hasattr(context, 'get_full_tick') and callable(getattr(context, 'get_full_tick')):
                tk = context.get_full_tick(fmt_list)
        except Exception:
            tk = None
        if not isinstance(tk, dict) or not tk:
            return [], {}

        mode = 'fast'
        try:
            mode = str(FIRST_BOARD_MODE or '').lower() or 'fast'
        except Exception:
            mode = 'fast'

        cands = []
        cand_map = {}
        for kf, rec in tk.items():
            if not isinstance(rec, dict):
                continue
            code = fmt_map.get(str(kf), str(kf))
            if code in hs:
                continue

            px = _tick_get(rec, ('lastPrice', 'price', 'last', 'm_dLastPrice', 'close'))
            try:
                px = float(px or 0)
            except Exception:
                px = 0.0
            if px <= 0:
                continue

            limit_up = _tick_get(rec, ('upperLimitPrice', 'highLimit', 'limitUp', 'upLimit', 'UpStopPrice', 'UpperLimitPrice', 'm_dUpLimitPrice'))
            try:
                limit_up = float(limit_up or 0)
            except Exception:
                limit_up = 0.0

            if limit_up <= 0:
                pc = _tick_get(rec, ('preClose', 'pre_close', 'yclose', 'm_dPreClose'))
                try:
                    pc = float(pc or 0)
                except Exception:
                    pc = 0.0
                if pc > 0:
                    limit_up = float(round(pc * 1.10, 2))
            if limit_up <= 0:
                continue

            dist = (limit_up - px) / max(1e-9, px)
            try:
                if not (0.0 <= float(dist) <= float(FIRST_BOARD_NEAR_LIMITUP_DIST)):
                    continue
            except Exception:
                continue

            amt = _tick_get(rec, ('amount', 'turnover', 'm_dAmount'))
            if amt is None:
                v = _tick_get(rec, ('volume', 'm_nVolume'))
                try:
                    if v is not None:
                        amt = float(v) * float(px)
                except Exception:
                    amt = None
            try:
                if amt is None or float(amt) < float(FIRST_BOARD_MIN_TODAY_AMOUNT):
                    continue
            except Exception:
                continue

            hi = _tick_get(rec, ('high', 'High', 'm_dHigh'))
            try:
                hi = float(hi or 0)
            except Exception:
                hi = 0.0
            if mode == 'fast':
                try:
                    if bool(FIRST_BOARD_FAST_REQUIRE_HIGH_NEAR_LIMITUP) and hi > 0:
                        high_dist = (limit_up - hi) / max(1e-9, hi)
                        if not (0.0 <= float(high_dist) <= float(FIRST_BOARD_FAST_HIGH_NEAR_LIMITUP_DIST)):
                            continue
                except Exception:
                    continue

            try:
                recent_info = get_recent_limit_up_info(context, str(kf), {
                    'enabled': True,
                    'lookback_days': int(FIRST_BOARD_LOOKBACK_DAYS),
                    'recent_window_days': int(FIRST_BOARD_RECENT_WINDOW_DAYS),
                })
            except Exception:
                recent_info = None
            if isinstance(recent_info, dict):
                try:
                    if int(recent_info.get('count', 0) or 0) > int(FIRST_BOARD_MAX_RECENT_LIMITUP_COUNT):
                        continue
                except Exception:
                    continue

            det = {'code': code, 'price': float(px), 'limit_up': float(limit_up), 'dist': float(dist), 'amount': float(amt)}
            cand_map[str(code)] = det
            cands.append(det)

        if not cands:
            try:
                _first_board_scan_cache['ts'] = now_ts
                _first_board_scan_cache['codes'] = []
                _first_board_scan_cache['map'] = {}
            except Exception:
                pass
            return [], {}

        try:
            cands.sort(key=lambda x: float(x.get('dist', 1.0)))
        except Exception:
            pass
        try:
            top_n = int(FIRST_BOARD_SCAN_TOP_N)
        except Exception:
            top_n = 10
        top = cands[:top_n] if top_n > 0 else cands
        codes_out = [str(x.get('code')) for x in top if x.get('code')]
        map_out = {str(x.get('code')): x for x in top if x.get('code')}

        try:
            _first_board_scan_cache['ts'] = now_ts
            _first_board_scan_cache['codes'] = list(codes_out)
            _first_board_scan_cache['map'] = dict(map_out)
        except Exception:
            pass

        return codes_out, map_out
    except Exception:
        return [], {}


def build_first_board_base_pool(context, candidate_stocks, data_close, data_high, data_low, data_volume):
    try:
        if not bool(FIRST_BOARD_ENABLED) or not bool(FIRST_BOARD_BASEPOOL_ENABLED):
            return list(candidate_stocks or [])

        out = []
        total = 0
        try:
            n_range = int(FIRST_BOARD_BASEPOOL_RANGE_DAYS)
        except Exception:
            n_range = 60
        n_range = max(20, n_range)

        try:
            pos_max = float(FIRST_BOARD_BASEPOOL_PRICE_POS_MAX)
        except Exception:
            pos_max = 0.35

        try:
            ma_conv_max = float(FIRST_BOARD_BASEPOOL_MA_CONV_MAX)
        except Exception:
            ma_conv_max = 0.02

        try:
            n_vol = int(FIRST_BOARD_BASEPOOL_VOL_DAYS)
        except Exception:
            n_vol = 20
        n_vol = max(10, n_vol)

        try:
            vol_max = float(FIRST_BOARD_BASEPOOL_VOL_MAX)
        except Exception:
            vol_max = 0.035

        try:
            vc_max = float(FIRST_BOARD_BASEPOOL_VOL_CONTRACTION_MAX)
        except Exception:
            vc_max = 0.90

        try:
            max_ret20 = float(FIRST_BOARD_BASEPOOL_MAX_20D_RETURN)
        except Exception:
            max_ret20 = 0.30

        for s in list(candidate_stocks or []):
            code = str(s)
            total += 1
            closes = (data_close or {}).get(code) or []
            highs = (data_high or {}).get(code) or []
            lows = (data_low or {}).get(code) or []
            vols = (data_volume or {}).get(code) or []

            if len(closes) < max(20, n_range) or len(highs) < max(20, n_range) or len(lows) < max(20, n_range):
                continue

            try:
                last_close = float(closes[-1])
            except Exception:
                continue
            if last_close <= 0:
                continue

            try:
                hi = float(np.max(np.array(highs[-n_range:], dtype=float)))
                lo = float(np.min(np.array(lows[-n_range:], dtype=float)))
            except Exception:
                continue
            if hi <= 0 or lo <= 0 or hi <= lo:
                continue

            pos = (last_close - lo) / max(1e-9, (hi - lo))
            if pos > pos_max:
                continue

            try:
                ma5 = float(np.mean(np.array(closes[-5:], dtype=float)))
                ma10 = float(np.mean(np.array(closes[-10:], dtype=float)))
                ma20 = float(np.mean(np.array(closes[-20:], dtype=float)))
            except Exception:
                continue
            ma_min = min(ma5, ma10, ma20)
            ma_max = max(ma5, ma10, ma20)
            if ma_min <= 0:
                continue
            if (ma_max - ma_min) / ma_min > ma_conv_max:
                continue

            try:
                if len(closes) >= (n_vol + 1):
                    arr = np.array(closes[-(n_vol + 1):], dtype=float)
                    base = arr[:-1]
                    nxt = arr[1:]
                    rets = (nxt - base) / np.maximum(1e-9, base)
                    rv = float(np.std(rets))
                    if rv > vol_max:
                        continue
            except Exception:
                continue

            try:
                if len(vols) >= 20:
                    v5 = float(np.mean(np.array(vols[-5:], dtype=float)))
                    v20 = float(np.mean(np.array(vols[-20:], dtype=float)))
                    if v20 > 0 and (v5 / v20) > vc_max:
                        continue
            except Exception:
                pass

            try:
                if len(closes) >= 21:
                    c20 = float(closes[-21])
                    if c20 > 0:
                        r20 = (last_close - c20) / c20
                        if r20 > max_ret20:
                            continue
            except Exception:
                pass

            out.append(code)

        try:
            if total > 0:
                logger.info(f"?? 首板底部集中预选池(base_pool): {len(out)} / {total} (pass_rate={len(out)/max(1,total):.1%})")
        except Exception:
            pass

        return out
    except Exception:
        return list(candidate_stocks or [])


def first_board_check(context, stock_code: str):
    try:
        if not bool(FIRST_BOARD_ENABLED):
            return None
        now_t = datetime.now().time()
        if not _in_time_windows(now_t, FIRST_BOARD_TIME_WINDOWS):
            return None

        code = str(stock_code)
        code_fmt = format_stock_code(code) if 'format_stock_code' in globals() else code

        px = None
        try:
            px = get_realtime_price_safe(context, code_fmt)
        except Exception:
            px = None
        if px is None or float(px) <= 0:
            return None

        limit_up = get_limit_up_price_safe(context, code_fmt)
        if not limit_up or float(limit_up) <= 0:
            return None
        dist = (float(limit_up) - float(px)) / max(1e-9, float(px))
        if not (0.0 <= float(dist) <= float(FIRST_BOARD_NEAR_LIMITUP_DIST)):
            return None

        today_amount = None
        today_high = None
        prev_close = None
        try:
            if hasattr(context, 'get_full_tick') and callable(getattr(context, 'get_full_tick')):
                tk = context.get_full_tick([code_fmt])
                rec = None
                if isinstance(tk, dict):
                    rec = tk.get(code_fmt) or tk.get(code) or tk
                elif isinstance(tk, list) and tk:
                    rec = tk[0]
                if isinstance(rec, dict):
                    today_amount = rec.get('amount') or rec.get('turnover') or rec.get('m_dAmount')
                    today_high = rec.get('high') or rec.get('High') or rec.get('m_dHigh')
                    prev_close = rec.get('preClose') or rec.get('pre_close') or rec.get('yclose') or rec.get('m_dPreClose')
                    if today_amount is None:
                        v = rec.get('volume') or rec.get('m_nVolume')
                        if v is not None:
                            today_amount = float(v) * float(px)
        except Exception:
            today_amount = None
        try:
            if today_amount is None or float(today_amount) < float(FIRST_BOARD_MIN_TODAY_AMOUNT):
                return None
        except Exception:
            return None

        recent_info = None
        try:
            recent_info = get_recent_limit_up_info(context, code_fmt, {
                'enabled': True,
                'lookback_days': int(FIRST_BOARD_LOOKBACK_DAYS),
                'recent_window_days': int(FIRST_BOARD_RECENT_WINDOW_DAYS),
            })
        except Exception:
            recent_info = None
        if isinstance(recent_info, dict):
            try:
                if int(recent_info.get('count', 0) or 0) > int(FIRST_BOARD_MAX_RECENT_LIMITUP_COUNT):
                    return None
            except Exception:
                return None

        try:
            mode = str(FIRST_BOARD_MODE or '').lower()
        except Exception:
            mode = 'fast'

        if mode == 'fast':
            try:
                if bool(FIRST_BOARD_FAST_REQUIRE_HIGH_NEAR_LIMITUP) and today_high is not None and float(today_high) > 0:
                    high_dist = (float(limit_up) - float(today_high)) / max(1e-9, float(today_high))
                    if not (0.0 <= float(high_dist) <= float(FIRST_BOARD_FAST_HIGH_NEAR_LIMITUP_DIST)):
                        return None
            except Exception:
                return None

        if mode != 'fast':
            try:
                if bool(FIRST_BOARD_REQUIRE_RESEAL_CONFIRM):
                    touch = (float(dist) <= float(FIRST_BOARD_TOUCH_LIMIT_EPS))
                    if not touch:
                        return None
                    if not is_resealing_likely(context, code_fmt, float(limit_up), dict(FIRST_BOARD_RESEAL_CFG or {})):
                        return None
            except Exception:
                return None

        return {
            'code': code,
            'price': float(px),
            'limit_up': float(limit_up),
            'dist': float(dist),
            'amount': float(today_amount),
        }
    except Exception:
        return None

def get_enhanced_position_cost_price(pos, stock_code):
    """
    增强版持仓成本价获取函数，支持多种数据源和异常处理
    
    Args:
        pos: 持仓对象
        stock_code: 股票代码
        
    Returns:
        float: 有效的成本价，如果无法获取则返回None
    """
    try:
        # 尝试多种可能的成本价字段
        cost_price_fields = [
            'm_dOpenPrice',      # 开仓价
            'm_dCostPrice',      # 成本价
            'm_dAvgPrice',       # 平均价
            'm_dPrice',          # 价格
            'cost_price',        # 成本价(简化)
            'open_price',        # 开仓价(简化)
            'avg_price'          # 平均价(简化)
        ]
        
        cost_price = None
        field_used = None
        
        # 按优先级尝试获取成本价
        for field in cost_price_fields:
            try:
                if hasattr(pos, field):
                    value = getattr(pos, field)
                    if value is not None:
                        cost_price = float(value)
                        field_used = field
                        break
            except (ValueError, TypeError, AttributeError):
                continue
        
        # 如果获取到了成本价，进行合理性验证
        if cost_price is not None:
            # 检查是否为合理的价格范围
            if 0.01 <= cost_price <= 10000:  # 合理价格范围：1分到1万元
                logger.info(f"? {stock_code} 成功获取成本价: {cost_price:.3f}元 (字段: {field_used})")
                return cost_price
            else:
                logger.warning(f"?? {stock_code} 成本价超出合理范围: {cost_price:.3f}元 (字段: {field_used})")
                # 对于负数成本价，尝试取绝对值进行修正
                if cost_price < 0:
                    corrected_price = abs(cost_price)
                    if 0.01 <= corrected_price <= 10000:
                        logger.info(f"?? {stock_code} 负数成本价修正为: {corrected_price:.3f}元")
                        return corrected_price
        
        # 如果无法获取有效成本价，尝试从历史交易记录推算
        estimated_price = estimate_cost_price_from_history(stock_code)
        if estimated_price is not None:
            logger.info(f"?? {stock_code} 使用历史推算成本价: {estimated_price:.3f}元")
            return estimated_price
        
        # 如果仍然无法获取，尝试使用当前价格作为临时成本价
        try:
            current_price = get_current_price_safe(context, stock_code)
            if current_price is not None and current_price > 0:
                logger.warning(f"?? {stock_code} 无法获取成本价，临时使用当前价格: {current_price:.3f}元")
                return current_price
        except Exception as e:
            logger.error(f"获取当前价格失败 {stock_code}: {e}")
        
        # 所有方法都失败
        logger.error(f"? {stock_code} 无法获取有效成本价，所有字段均无效:")
        for field in cost_price_fields:
            try:
                value = getattr(pos, field, "不存在")
                logger.error(f"   {field}: {value}")
            except:
                logger.error(f"   {field}: 访问异常")
        
        return None
        
    except Exception as e:
        logger.error(f"获取成本价异常 {stock_code}: {e}")
        return None

def estimate_cost_price_from_history(stock_code):
    """
    从历史交易记录推算成本价
    
    Args:
        stock_code: 股票代码
        
    Returns:
        float: 推算的成本价，如果无法推算则返回None
    """
    try:
        # 尝试从当前市场数据获取合理的参考价格
        formatted_code = format_stock_code(stock_code)
        
        # 方法1: 尝试获取最近5日均价作为参考
        try:
            if 'get_market_data_ex' in globals():
                # 获取最近5日的收盘价
                market_data = get_market_data_ex([formatted_code], period='1d', start_time='', end_time='', count=5, fields=['close'])
                if market_data and len(market_data) > 0:
                    closes = []
                    for data in market_data:
                        if hasattr(data, 'close') and data.close > 0:
                            closes.append(float(data.close))
                    
                    if len(closes) >= 3:  # 至少3个有效价格
                        avg_price = sum(closes) / len(closes)
                        logger.info(f"?? {stock_code} 使用{len(closes)}日均价作为成本价参考: {avg_price:.3f}元")
                        return avg_price
        except Exception as e:
            logger.warning(f"获取历史均价失败 {stock_code}: {e}")
        
        # 方法2: 尝试从全局持仓缓存获取
        try:
            global position_cost_cache
            if 'position_cost_cache' in globals() and stock_code in position_cost_cache:
                cached_info = position_cost_cache[stock_code]
                cached_price = cached_info.get('cost_price')
                if cached_price and 0.01 <= cached_price <= 10000:
                    logger.info(f"?? {stock_code} 使用缓存成本价: {cached_price:.3f}元")
                    return cached_price
        except Exception as e:
            logger.warning(f"获取缓存成本价失败 {stock_code}: {e}")
        
        # 方法3: 使用行业平均价格区间估算
        try:
            # 根据股票代码前缀估算合理价格区间
            if stock_code.startswith('00'):  # 深市主板
                estimated_range = (5.0, 50.0)
            elif stock_code.startswith('30'):  # 创业板
                estimated_range = (10.0, 100.0)
            elif stock_code.startswith('60'):  # 沪市主板
                estimated_range = (3.0, 80.0)
            else:
                estimated_range = (5.0, 50.0)
            
            # 使用区间中位数作为估算价格
            estimated_price = (estimated_range[0] + estimated_range[1]) / 2
            logger.warning(f"?? {stock_code} 使用行业估算成本价: {estimated_price:.3f}元 (区间: {estimated_range})")
            return estimated_price
            
        except Exception as e:
            logger.warning(f"行业估算失败 {stock_code}: {e}")
        
        return None
    except Exception as e:
        logger.error(f"从历史记录推算成本价失败 {stock_code}: {e}")
        return None

def get_current_price_safe(context, stock_code):
    """
    安全获取当前价格
    
    Args:
        context: 策略上下文
        stock_code: 股票代码
        
    Returns:
        float: 当前价格，如果无法获取则返回None
    """
    try:
        # 确保股票代码格式正确
        formatted_code = format_stock_code(stock_code)
        
        # 尝试获取当前价格（需要context）
        price_data = get_current_price(formatted_code, context)
        if price_data is not None and price_data > 0:
            return float(price_data)
        
        return None
    except Exception as e:
        logger.error(f"安全获取当前价格失败 {stock_code}: {e}")
        return None

