def trailing_profit_check(stock_code, profit_loss_ratio, buy_price, current_price, volume, trailing_params, highest_price):
    """
    移动止盈检查函数 - 增强版本，带类型验证
    
    参数:
    stock_code: 股票代码
    profit_loss_ratio: 当前盈亏比例
    buy_price: 买入价格
    current_price: 当前价格
    volume: 持仓数量
    trailing_params: 移动止盈参数
    highest_price: 历史最高价格
    
    返回:
    tuple: (action, sell_ratio, detail_info_dict)
    """
    try:
        # 参数类型验证
        if not isinstance(trailing_params, dict):
            logger.error(f"? trailing_profit_check: trailing_params 必须是字典类型, 实际类型: {type(trailing_params)}")
            return 'HOLD', 0.0, {'reason': '参数类型错误', 'error': 'trailing_params不是字典'}
        # 基本数值校验
        try:
            profit_loss_ratio = float(profit_loss_ratio)
            buy_price = float(buy_price)
            current_price = float(current_price)
            volume = int(volume)
            highest_price = float(highest_price) if highest_price is not None else 0.0
        except Exception as conv_e:
            logger.error(f"? trailing_profit_check: 参数数值转换失败: {conv_e}")
            return 'HOLD', 0.0, {'reason': '参数数值不合法', 'error': str(conv_e)}
        if buy_price <= 0 or current_price <= 0 or volume <= 0:
            return 'HOLD', 0.0, {'reason': '无效买入价/当前价/数量', 'error': 'buy/current/volume invalid'}

        # 获取移动止盈参数，使用安全的字典访问
        trailing_threshold = TypeValidator.safe_get_dict_value(
            trailing_params, 'trailing_percent', 0.06, float
        )
        protection_threshold = TypeValidator.safe_get_dict_value(
            trailing_params, 'min_profit', 0.08, float
        )
        # 抗抖动控制参数
        min_holding_days = int(trailing_params.get('min_holding_days', 2))
        cooldown_seconds = int(trailing_params.get('cooldown_seconds', 1200))
        max_triggers_per_hour = int(trailing_params.get('max_triggers_per_hour', 1))
        hysteresis_pct = float(trailing_params.get('hysteresis_pct', 0.015))
        shock_gate_minutes = int(trailing_params.get('shock_gate_minutes', 15))
        opened_at_ts = int(trailing_params.get('opened_at_ts', 0) or 0)
        if opened_at_ts <= 0:
            try:
                opened_at_ts = int((stock_positions_info.get(stock_code, {}) or {}).get('opened_at_ts', 0) or 0)
            except Exception:
                opened_at_ts = 0
        if opened_at_ts <= 0:
            try:
                rec = buy_in_table.get(stock_code) if isinstance(buy_in_table, dict) else None
                ts = rec.get('timestamp') if isinstance(rec, dict) else None
                if isinstance(ts, str) and ts:
                    opened_at_ts = int(datetime.strptime(ts, '%Y-%m-%d %H:%M:%S').timestamp())
            except Exception:
                opened_at_ts = 0

        # 严格区分止盈/止损：本函数仅处理止盈（盈利为正的卖出）。
        if profit_loss_ratio <= 0:
            return 'HOLD', 0.0, {
                'reason': f'非止盈场景：当前为亏损状态({profit_loss_ratio:.2%})，移动止盈不生效',
                'profit_ratio': profit_loss_ratio,
                'category': 'stop_loss_domain'
            }

        # 结构过滤配置
        structure_filters_enabled = True
        # 海龟式通道退出（默认20日），降低短周期抖动导致的卖飞
        n_day_low_window = 20
        ma_window = 10
        # 主升浪结构破位确认参数：避免盘中噪声导致卖飞
        structure_break_confirm_times = 2
        structure_break_partial_ratio = 0.50
        # 结构破位“收盘确认窗口”起始时间（默认14:50，可在顶部配置/参数覆盖）
        confirm_window_start = time(14, 50)
        # 是否仅在收盘窗口累计确认次数：True=仅尾盘累计；False=全天累计
        confirm_window_enabled = True
        # 是否要求“日线bar已更新到今日”才允许累计确认次数
        require_daily_bar_today = True
        # 行为开关（可由上游覆盖）
        intraday_confirm = True
        afternoon_caution = True

        try:
            _cfg0 = STRATEGY_ENHANCEMENT_CONFIG.get('structure_break_confirm', {}) if isinstance(STRATEGY_ENHANCEMENT_CONFIG, dict) else {}
            if isinstance(_cfg0, dict):
                confirm_window_enabled = bool(_cfg0.get('enabled', True))
                _hm = _cfg0.get('confirm_window_start')
                if isinstance(_hm, (list, tuple)) and len(_hm) >= 2:
                    confirm_window_start = time(int(_hm[0]), int(_hm[1]))
                rdbt = _cfg0.get('require_daily_bar_today', require_daily_bar_today)
                if isinstance(rdbt, bool):
                    require_daily_bar_today = rdbt
        except Exception:
            pass
        try:
            n_day_low_window = int(trailing_params.get('n_day_low_window', n_day_low_window))
            ma_window = int(trailing_params.get('ma_window', ma_window))
            structure_break_confirm_times = int(trailing_params.get('structure_break_confirm_times', structure_break_confirm_times))
            structure_break_partial_ratio = float(trailing_params.get('structure_break_partial_ratio', structure_break_partial_ratio))
            structure_break_confirm_times = max(1, min(5, structure_break_confirm_times))
            structure_break_partial_ratio = max(0.0, min(1.0, structure_break_partial_ratio))
            _hm2 = trailing_params.get('structure_break_confirm_window_start')
            if isinstance(_hm2, (list, tuple)) and len(_hm2) >= 2:
                confirm_window_start = time(int(_hm2[0]), int(_hm2[1]))
            _cwe = trailing_params.get('structure_break_confirm_window_enabled')
            if isinstance(_cwe, bool):
                confirm_window_enabled = _cwe
            _rdbt2 = trailing_params.get('structure_break_require_daily_bar_today')
            if isinstance(_rdbt2, bool):
                require_daily_bar_today = _rdbt2
            ic = trailing_params.get('intraday_confirm', intraday_confirm)
            ac = trailing_params.get('afternoon_caution', afternoon_caution)
            if isinstance(ic, bool):
                intraday_confirm = ic
            if isinstance(ac, bool):
                afternoon_caution = ac
        except Exception:
            pass

        # 生命周期阶段（用于主升浪防卖飞）
        try:
            phase = str((stock_positions_info.get(stock_code, {}) or {}).get('lifecycle_phase', '') or '').lower()
        except Exception:
            phase = ''
        try:
            env_l = str(trailing_params.get('market_env') or '').lower()
        except Exception:
            env_l = ''

        # 计算当前回撤幅度
        if highest_price and highest_price > buy_price:
            drawdown_from_high = (highest_price - current_price) / max(1e-9, highest_price)
        else:
            drawdown_from_high = 0.0

        holding_days = None
        try:
            now_ts = _now_ts()
            if opened_at_ts and opened_at_ts > 0:
                holding_days = int(max(0, (now_ts - int(opened_at_ts)) // 86400))
            else:
                holding_days = None
        except Exception:
            holding_days = None

        try:
            mt_cfg = (STRATEGY_ENHANCEMENT_CONFIG.get('markup_trailing', {}) or {}) if isinstance(STRATEGY_ENHANCEMENT_CONFIG, dict) else {}
        except Exception:
            mt_cfg = {}
        try:
            if phase in ('markup', 'accumulation'):
                if bool(trailing_params.get('skip_markup_trailing', False)):
                    mt_cfg = {}
                disable_before_days = int(mt_cfg.get('disable_before_days', 1))
                if disable_before_days > 0 and holding_days is not None and holding_days < disable_before_days:
                    return 'HOLD', 0.0, {
                        'reason': f'主升段持仓{holding_days}天<{disable_before_days}天，抑制盈利移动止盈',
                        'profit_ratio': profit_loss_ratio,
                        'drawdown': drawdown_from_high,
                        'phase': phase,
                        'holding_days': holding_days,
                        'category': 'markup_trailing_suppress'
                    }
                trailing_multiplier = float(mt_cfg.get('trailing_multiplier', 1.5))
                if trailing_multiplier and trailing_multiplier > 1.0:
                    trailing_threshold = float(trailing_threshold) * float(trailing_multiplier)
        except Exception:
            pass

        # 计算结构性位置信息（MA与N日低点）
        above_ma10 = True
        above_n_day_low = True
        # 方案B：主升段用“日线收盘确认 + 0.3*ATR14缓冲”判定有效破位，避免贴10日线洗盘卖飞
        atr14 = None
        daily_close = None
        daily_bar_is_today = False
        try:
            hist = get_market_data_ex([stock_code], ['high', 'low', 'close'], '1d', max(ma_window, n_day_low_window, 20) + 2)  # pyright: ignore[reportUndefinedVariable]
            if isinstance(hist, dict) and stock_code in hist and not hist[stock_code].empty:
                df = hist[stock_code]
                try:
                    _last_dt = None
                    if hasattr(df, 'index') and len(df.index) > 0:
                        try:
                            _last_dt = df.index[-1]
                        except Exception:
                            _last_dt = None
                    if _last_dt is None and isinstance(df, pd.DataFrame) and 'date' in df.columns:
                        _last_dt = df['date'].iloc[-1]
                    if _last_dt is not None:
                        try:
                            _last_day = pd.to_datetime(_last_dt).strftime('%Y%m%d')
                            _today = datetime.now().strftime('%Y%m%d')
                            daily_bar_is_today = (_last_day == _today)
                        except Exception:
                            daily_bar_is_today = False
                except Exception:
                    daily_bar_is_today = False
                closes = df['close'].dropna().tolist() if 'close' in df else []
                highs = df['high'].dropna().tolist() if 'high' in df else []
                lows = df['low'].dropna().tolist() if 'low' in df else []
                if closes:
                    daily_close = float(closes[-1])

                # MA10 / N日低点：默认仍以“当前价”判断（非主升段）
                if len(closes) >= ma_window:
                    ma10 = sum(closes[-ma_window:]) / ma_window
                    above_ma10 = current_price >= ma10
                if len(closes) >= n_day_low_window:
                    recent_low = min(closes[-n_day_low_window:])
                    above_n_day_low = current_price >= recent_low

                # ATR14（用于主升段缓冲）
                try:
                    n_atr = 14
                    if len(closes) >= n_atr + 1 and len(highs) >= n_atr + 1 and len(lows) >= n_atr + 1:
                        trs = []
                        for _i in range(len(closes) - n_atr, len(closes)):
                            pc = float(closes[_i - 1])
                            hi = float(highs[_i])
                            lo = float(lows[_i])
                            tr = max(hi - lo, abs(hi - pc), abs(lo - pc))
                            trs.append(tr)
                        if trs:
                            atr14 = float(sum(trs) / len(trs))
                except Exception:
                    atr14 = None
        except Exception as _e:
            logger.debug(f"结构过滤数据获取失败: {_e}")

        # 主升/吸筹阶段：用日线收盘做确认，并引入 0.3*ATR14 缓冲
        eff_above_ma10 = above_ma10
        eff_above_n_day_low = above_n_day_low
        try:
            if phase in ('markup', 'accumulation') and daily_close is not None and atr14 is not None and atr14 > 0:
                buf = 0.3 * float(atr14)
                # 这里重新计算一次 MA 与 N 日低点（用收盘序列）并应用缓冲
                try:
                    if 'closes' in locals() and len(closes) >= ma_window:
                        ma10_c = sum(closes[-ma_window:]) / ma_window
                        eff_above_ma10 = float(daily_close) >= float(ma10_c) - buf
                except Exception:
                    pass
                try:
                    if 'closes' in locals() and len(closes) >= n_day_low_window:
                        recent_low_c = min(closes[-n_day_low_window:])
                        eff_above_n_day_low = float(daily_close) >= float(recent_low_c) - buf
                except Exception:
                    pass
        except Exception:
            pass

        try:
            _buf_dbg = 0.3 * float(atr14) if (atr14 is not None and float(atr14) > 0) else None
        except Exception:
            _buf_dbg = None
        try:
            _ma10_dbg = None
            if 'closes' in locals() and isinstance(closes, list) and len(closes) >= ma_window:
                _ma10_dbg = float(sum(closes[-ma_window:]) / float(ma_window))
        except Exception:
            _ma10_dbg = None
        try:
            _nlow_dbg = None
            if 'closes' in locals() and isinstance(closes, list) and len(closes) >= n_day_low_window:
                _nlow_dbg = float(min(closes[-n_day_low_window:]))
        except Exception:
            _nlow_dbg = None

        hold_detail = {
            'reason': f"移动止盈未触发: 收益{profit_loss_ratio:.1%}, 回撤{drawdown_from_high:.1%}",
            'profit_ratio': profit_loss_ratio,
            'drawdown': drawdown_from_high,
            'trailing_threshold': trailing_threshold,
            'protection_threshold': protection_threshold,
            'above_ma10': above_ma10,
            'above_n_day_low': above_n_day_low,
            'phase': phase,
            'daily_close': daily_close,
            'atr14': atr14,
            'atr_buf': _buf_dbg,
            'ma10': _ma10_dbg,
            'n_day_low': _nlow_dbg,
            'eff_above_ma10': eff_above_ma10,
            'eff_above_n_day_low': eff_above_n_day_low,
        }

        # 未达到激活收益，直接持有
        if profit_loss_ratio < protection_threshold:
            return 'HOLD', 0.0, hold_detail

        # 已达到激活收益，检查回撤强度
        if drawdown_from_high < trailing_threshold:
            return 'HOLD', 0.0, hold_detail

        # —— 抗抖动控制 ——
        now_ts = _now_ts()
        state_key = f"{stock_code}__trail_state"
        st = PER_STOCK_SHAPE_STATE['sell_hints'].get(state_key, {}) if isinstance(PER_STOCK_SHAPE_STATE.get('sell_hints'), dict) else {}
        last_trail_ts = int(st.get('last_trail_ts', 0) or 0)
        window_start = int(st.get('window_start', 0) or 0)
        triggers_in_window = int(st.get('triggers_in_window', 0) or 0)
        shock_gate_until = int(st.get('shock_gate_until', 0) or 0)
        last_effective_threshold = float(st.get('last_effective_threshold', trailing_threshold))

        # 最小持有期：仅对移动止盈生效（结构破位除外）
        if opened_at_ts > 0:
            min_hold_ok = (now_ts - opened_at_ts) >= (min_holding_days * 86400)
        else:
            min_hold_ok = False if int(min_holding_days) > 0 else True

        # 冷却期限制（结构破位除外）
        in_cooldown = (last_trail_ts > 0) and ((now_ts - last_trail_ts) < cooldown_seconds)

        # 小时窗口计数
        if window_start == 0 or (now_ts - window_start) >= 3600:
            window_start = now_ts
            triggers_in_window = 0

        # 滞回：如果刚触发过，提高再次触发阈值
        eff_trailing_threshold = trailing_threshold
        if last_trail_ts > 0:
            try:
                eff_trailing_threshold = max(trailing_threshold, last_effective_threshold * (1.0 + hysteresis_pct))
            except Exception:
                eff_trailing_threshold = trailing_threshold

        # 冲击闸门（默认对非结构破位情形生效）
        in_shock_gate = shock_gate_until and now_ts < shock_gate_until

        # 进入移动止盈触发分段：默认部分卖出，避免卖飞
        action = 'SELL'
        sell_ratio = 0.30  # 第一段默认卖出30%

        # 回撤更大或盈利更高时，提高卖出比例
        severe_drawdown = drawdown_from_high >= (eff_trailing_threshold + 0.02)
        high_profit = profit_loss_ratio >= (protection_threshold + 0.05)
        if severe_drawdown or high_profit:
            sell_ratio = 0.60  # 第二段卖出60%

        # 强趋势/临近涨停保护逻辑
        base_trailing_threshold = trailing_threshold
        base_protection_threshold = protection_threshold
        strong_trend_near_limit = False
        try:
            _ctx = globals().get('ContextInfo') or globals().get('context')
            limit_up_price = get_limit_up_price_safe(_ctx, stock_code) or (buy_price * 1.1)
            distance_to_limit = (limit_up_price - current_price) / max(current_price, 1e-9)
            if profit_loss_ratio >= 0.12 and 0.0 <= distance_to_limit <= 0.02:
                strong_trend_near_limit = True
                trailing_threshold = max(trailing_threshold, 0.08)
                protection_threshold = max(protection_threshold, 0.12)
        except Exception:
            strong_trend_near_limit = False

        # 结构破位：跌破MA10或N日低点
        # 主升段（markup/accumulation）避免“一破就全清”导致卖飞：先减仓，连续确认后才允许全清
        # 主升段用“有效结构”判定，其余阶段沿用原先的盘中结构判断
        if phase in ('markup', 'accumulation'):
            structure_break = bool(structure_filters_enabled and (not eff_above_ma10 or not eff_above_n_day_low))
        else:
            structure_break = bool(structure_filters_enabled and (not above_ma10 or not above_n_day_low))
        if structure_break:
            if strong_trend_near_limit:
                sell_ratio = max(sell_ratio, 0.50)
            else:
                if phase in ('markup', 'accumulation') and env_l not in ('bear', 'down', 'weak_bear', 'extreme_bear'):
                    state_key = f"{stock_code}__structure_break_state"
                    st2 = PER_STOCK_SHAPE_STATE['sell_hints'].get(state_key, {}) if isinstance(PER_STOCK_SHAPE_STATE.get('sell_hints'), dict) else {}
                    prev_cnt = int(st2.get('count', 0) or 0)
                    last_day = str(st2.get('last_day', '') or '')
                    try:
                        today_day = datetime.now().strftime('%Y%m%d')
                    except Exception:
                        today_day = ''
                    # 仅在接近收盘窗口才累加“确认次数”，更贴近日线收盘确认（避免盘中误判当日收盘）
                    in_confirm_window = False
                    try:
                        _ct = datetime.now().time()
                        if not confirm_window_enabled:
                            in_confirm_window = True
                        else:
                            in_confirm_window = _ct >= confirm_window_start
                        if require_daily_bar_today and (not daily_bar_is_today):
                            in_confirm_window = False
                    except Exception:
                        in_confirm_window = False

                    # 同一交易日内不重复累加确认次数；非收盘窗口不新增确认次数
                    if (not in_confirm_window) or (today_day and last_day == today_day):
                        cnt = prev_cnt
                        try:
                            PER_STOCK_SHAPE_STATE['sell_hints'][state_key] = {'count': cnt, 'last_day': last_day, 'ts': _now_ts()}
                        except Exception:
                            pass
                    else:
                        cnt = prev_cnt + 1
                        PER_STOCK_SHAPE_STATE['sell_hints'][state_key] = {'count': cnt, 'last_day': today_day, 'ts': _now_ts()}
                    # 第一次破位：仅部分减仓；连续确认达到阈值：才允许全清
                    if cnt >= structure_break_confirm_times:
                        sell_ratio = 1.0
                    else:
                        sell_ratio = max(sell_ratio, structure_break_partial_ratio)
                else:
                    sell_ratio = 1.0
        else:
            # 结构恢复时清零计数，避免误触发“连续确认”
            try:
                state_key = f"{stock_code}__structure_break_state"
                if isinstance(PER_STOCK_SHAPE_STATE.get('sell_hints'), dict) and state_key in PER_STOCK_SHAPE_STATE['sell_hints']:
                    PER_STOCK_SHAPE_STATE['sell_hints'].pop(state_key, None)
            except Exception:
                pass

        if not structure_break and (not bool(trailing_params.get('skip_near_limitup_freeze', False))):
            try:
                nf_cfg = (STRATEGY_ENHANCEMENT_CONFIG.get('near_limitup_freeze', {}) or {}) if isinstance(STRATEGY_ENHANCEMENT_CONFIG, dict) else {}
            except Exception:
                nf_cfg = {}
            try:
                if bool(nf_cfg.get('enabled', True)):
                    _ctx = globals().get('ContextInfo') or globals().get('context')
                    limit_up_price = get_limit_up_price_safe(_ctx, stock_code) or (buy_price * 1.1)
                    distance_to_limit = (limit_up_price - current_price) / max(current_price, 1e-9)
                    freeze_dist = float(nf_cfg.get('distance_to_limit', 0.015))
                    touch_eps = float(nf_cfg.get('touch_limit_eps', 0.003))
                    unfreeze_dd = float(nf_cfg.get('unfreeze_drawdown', 0.05))
                    min_pf = float(nf_cfg.get('min_profit', 0.04))
                    override_dd = float(nf_cfg.get('override_drawdown', 0.12))

                    near_limit_unfreeze_triggered = False
                    touched_today = False
                    try:
                        today_day = datetime.now().strftime('%Y%m%d')
                        touch_key = f"{stock_code}__limit_touch"
                        old = PER_STOCK_SHAPE_STATE['sell_hints'].get(touch_key, {}) if isinstance(PER_STOCK_SHAPE_STATE.get('sell_hints'), dict) else {}
                        last_day = str(old.get('last_day', '') or '')
                        min_d = float(old.get('min_distance', 9.0) or 9.0) if last_day == today_day else 9.0
                        if 0.0 <= distance_to_limit <= touch_eps:
                            min_d = min(min_d, float(distance_to_limit))
                            PER_STOCK_SHAPE_STATE['sell_hints'][touch_key] = {
                                'last_day': today_day,
                                'min_distance': float(min_d),
                                'ts': _now_ts(),
                            }
                            touched_today = True
                        else:
                            if last_day == today_day and (old is not None):
                                touched_today = True
                    except Exception:
                        touched_today = False

                    try:
                        if touched_today and drawdown_from_high >= unfreeze_dd:
                            near_limit_unfreeze_triggered = True
                    except Exception:
                        near_limit_unfreeze_triggered = False

                    if (not near_limit_unfreeze_triggered) and profit_loss_ratio >= min_pf and 0.0 <= distance_to_limit <= freeze_dist and drawdown_from_high < override_dd:
                        return 'HOLD', 0.0, {
                            'reason': f'临近涨停(距涨停{distance_to_limit:.2%})冻结盈利卖出',
                            'profit_ratio': profit_loss_ratio,
                            'drawdown': drawdown_from_high,
                            'distance_to_limit': distance_to_limit,
                            'touched_limit_today': touched_today,
                            'category': 'near_limitup_freeze'
                        }

                    try:
                        if near_limit_unfreeze_triggered:
                            trailing_params['__near_limitup_unfreeze'] = True
                            trailing_params['__near_limitup_distance'] = float(distance_to_limit)
                    except Exception:
                        pass
            except Exception:
                pass

        if not structure_break and (not bool(trailing_params.get('skip_trailing_confirm', False))):
            try:
                tc_cfg = (STRATEGY_ENHANCEMENT_CONFIG.get('trailing_confirm', {}) or {}) if isinstance(STRATEGY_ENHANCEMENT_CONFIG, dict) else {}
            except Exception:
                tc_cfg = {}
            try:
                if bool(tc_cfg.get('enabled', True)):
                    mode = str(tc_cfg.get('mode', 'hybrid') or 'hybrid').lower()
                    if mode in ('hybrid', 'close_only'):
                        _hm = tc_cfg.get('confirm_window_start', [14, 50])
                        _cws = confirm_window_start
                        if isinstance(_hm, (list, tuple)) and len(_hm) >= 2:
                            _cws = time(int(_hm[0]), int(_hm[1]))
                        in_confirm_window = False
                        try:
                            _ct = datetime.now().time()
                            in_confirm_window = _ct >= _cws
                            if bool(tc_cfg.get('require_daily_bar_today', True)) and (not daily_bar_is_today):
                                in_confirm_window = False
                        except Exception:
                            in_confirm_window = False

                        if not in_confirm_window:
                            try:
                                armed_key = f"{stock_code}__trailing_armed"
                                today_day = datetime.now().strftime('%Y%m%d')
                                old = PER_STOCK_SHAPE_STATE['sell_hints'].get(armed_key, {}) if isinstance(PER_STOCK_SHAPE_STATE.get('sell_hints'), dict) else {}
                                last_day = str(old.get('last_day', '') or '')
                                if last_day != today_day:
                                    PER_STOCK_SHAPE_STATE['sell_hints'][armed_key] = {
                                        'armed_ts': _now_ts(),
                                        'last_day': today_day,
                                        'profit_ratio': profit_loss_ratio,
                                        'drawdown': drawdown_from_high,
                                        'threshold': float(trailing_threshold),
                                    }
                            except Exception:
                                pass
                            return 'HOLD', 0.0, {
                                'reason': '盈利移动止盈已触发预警，等待尾盘确认',
                                'profit_ratio': profit_loss_ratio,
                                'drawdown': drawdown_from_high,
                                'category': 'trailing_confirm_wait'
                            }

                        if mode == 'close_only':
                            try:
                                armed_key = f"{stock_code}__trailing_armed"
                                old = PER_STOCK_SHAPE_STATE['sell_hints'].get(armed_key, {}) if isinstance(PER_STOCK_SHAPE_STATE.get('sell_hints'), dict) else {}
                                if not old:
                                    return 'HOLD', 0.0, {
                                        'reason': '尾盘确认模式：未出现盘中预警，不执行盈利移动止盈',
                                        'profit_ratio': profit_loss_ratio,
                                        'drawdown': drawdown_from_high,
                                        'category': 'trailing_confirm_no_armed'
                                    }
                            except Exception:
                                return 'HOLD', 0.0, {
                                    'reason': '尾盘确认模式：预警状态读取失败，保守不卖',
                                    'profit_ratio': profit_loss_ratio,
                                    'drawdown': drawdown_from_high,
                                    'category': 'trailing_confirm_read_fail'
                                }
            except Exception:
                pass

        # 分时确认机制：若未结构破位且非极端情况，要求分时确认以避免卖飞
        intraday_down = False
        vol_spike = False
        intraday_checked = False
        try:
            if sell_ratio < 1.0 and intraday_confirm:
                md5 = get_market_data_ex([stock_code], ['close', 'volume'], '5m', 20)  # pyright: ignore[reportUndefinedVariable]
                if isinstance(md5, dict) and stock_code in md5 and not md5[stock_code].empty:
                    df5 = md5[stock_code]
                    closes5 = df5['close'].dropna().tolist() if 'close' in df5 else []
                    vols5 = df5['volume'].dropna().tolist() if 'volume' in df5 else []
                    if len(closes5) >= 10:
                        m5 = sum(closes5[-5:]) / 5.0
                        m10 = sum(closes5[-10:]) / 10.0
                        intraday_down = (current_price < m5) and (m5 <= m10)
                    if len(vols5) >= 11 and vols5[-1] is not None:
                        base_avg = sum([v for v in vols5[-11:-1] if v is not None]) / 10.0
                        if base_avg > 0:
                            vol_spike = float(vols5[-1]) >= 1.2 * base_avg
                    intraday_checked = True
        except Exception as _ie:
            logger.debug(f"分时确认获取失败: {_ie}")

        # 若分时确认不足，则保守下调卖出比例（除非结构已破位）
        if sell_ratio < 1.0 and structure_filters_enabled and (above_ma10 and above_n_day_low):
            confirms = 0
            if intraday_down:
                confirms += 1
            if vol_spike:
                confirms += 1
            if confirms == 0 and intraday_checked:
                # 无确认，先小幅减仓以避免卖飞
                sell_ratio = min(sell_ratio, 0.10)

        # 时间窗口保护：在午后前段流动性偏弱时更保守（13:00-13:20）
        try:
            if afternoon_caution:
                now = datetime.now()
                if now.hour == 13 and now.minute < 20 and sell_ratio < 1.0 and (above_ma10 and above_n_day_low):
                    sell_ratio = min(sell_ratio, 0.20)
        except Exception:
            pass

        # —— 触发前的综合抑制规则（结构破位除外）——
        if sell_ratio < 1.0 and (above_ma10 and above_n_day_low):
            # 未达到滞回阈值则不触发
            if drawdown_from_high < eff_trailing_threshold:
                return 'HOLD', 0.0, {
                    'reason': f'滞回保护：未达到有效阈值({eff_trailing_threshold:.2%})',
                    'profit_ratio': profit_loss_ratio,
                    'drawdown': drawdown_from_high,
                    'effective_trailing_threshold': eff_trailing_threshold,
                }
            # 最小持有期与冷却期控制
            if not min_hold_ok:
                return 'HOLD', 0.0, {'reason': '最小持有期未到，抑制移动止盈'}
            if in_cooldown:
                return 'HOLD', 0.0, {'reason': '冷却期内，抑制移动止盈'}
            # 每小时触发次数限制
            if triggers_in_window >= max_triggers_per_hour:
                return 'HOLD', 0.0, {'reason': '达到小时触发上限，抑制移动止盈'}
            # 冲击闸门：分时量能异常或已处于闸门期则抑制
            if (vol_spike and sell_ratio < 1.0) or in_shock_gate:
                # 若首次检测到量能异常，开启闸门
                if vol_spike and not in_shock_gate:
                    shock_gate_until = now_ts + shock_gate_minutes * 60
                PER_STOCK_SHAPE_STATE['sell_hints'][state_key] = {
                    'last_trail_ts': last_trail_ts,
                    'window_start': window_start,
                    'triggers_in_window': triggers_in_window,
                    'shock_gate_until': shock_gate_until,
                    'last_effective_threshold': eff_trailing_threshold,
                }
                return 'HOLD', 0.0, {'reason': '冲击闸门/分时量能异常，暂缓移动止盈'}

        detail_info = {
            'reason': f"移动止盈触发: 收益{profit_loss_ratio:.1%}, 回撤{drawdown_from_high:.1%}, 比例{sell_ratio:.0%}",
            'profit_ratio': profit_loss_ratio,
            'drawdown': drawdown_from_high,
            'trailing_threshold': trailing_threshold,
            'effective_trailing_threshold': eff_trailing_threshold,
            'protection_threshold': protection_threshold,
            'base_trailing_threshold': base_trailing_threshold,
            'base_protection_threshold': base_protection_threshold,
            'strong_trend_near_limit': strong_trend_near_limit,
            'above_ma10': above_ma10,
            'above_n_day_low': above_n_day_low,
            'intraday_down': intraday_down,
            'vol_spike': vol_spike,
            'intraday_checked': intraday_checked,
            'profit_amount': (current_price - buy_price) * volume
        }

        try:
            if bool(trailing_params.get('__near_limitup_unfreeze', False)):
                detail_info['category'] = 'near_limitup_unfreeze'
                detail_info['distance_to_limit'] = float(trailing_params.get('__near_limitup_distance', 0.0) or 0.0)
                detail_info['reason'] = f"临近涨停解冻放行后触发卖出: " + str(detail_info.get('reason', ''))
        except Exception:
            pass

        logger.info(f"?? {stock_code} {detail_info['reason']}")
        # 更新状态：记录触发
        triggers_in_window += 1
        PER_STOCK_SHAPE_STATE['sell_hints'][state_key] = {
            'last_trail_ts': now_ts,
            'window_start': window_start,
            'triggers_in_window': triggers_in_window,
            'shock_gate_until': shock_gate_until,
            'last_effective_threshold': eff_trailing_threshold,
        }
        return action, sell_ratio, detail_info

    except Exception as e:
        logger.error(f"移动止盈检查失败: {e}")
        # 返回保守的持有决策
        error_detail = {
            'reason': f"移动止盈检查异常: {e}",
            'error': str(e)
        }
        return 'HOLD', 0.0, error_detail

def _log_account_overview(context):
    """
    打印账户资金快照，便于诊断（总资产/可用/持仓市值/冻结）。
    """
    try:
        data = get_trade_detail_data(context.accID, context.accIDType, 'ACCOUNT')
        if not data:
            logger.warning("?? 无法获取账户信息(ACCOUNT)")
            return
        ai0 = data[0]
        total_asset = getattr(ai0, 'm_dTotalAsset', None)
        available = getattr(ai0, 'm_dAvailable', None)
        market_value = getattr(ai0, 'm_dMarketValue', None)
        frozen = getattr(ai0, 'm_dFrozen', None)
        fields = {
            '总资产': total_asset,
            '可用资金': available,
            '持仓市值': market_value,
            '冻结资金': frozen,
        }
        parts = []
        for k, v in fields.items():
            if v is None:
                parts.append(f"{k}: <无该字段>")
            else:
                try:
                    parts.append(f"{k}: {float(v):,.2f}元")
                except Exception:
                    parts.append(f"{k}: {v}")
        logger.info("?? 账户资金快照: " + ", ".join(parts))
    except Exception as e:
        logger.warning(f"?? 获取账户资金快照失败: {e}")


def _basic_precheck_buy(stock_code, price, volume):
    """
    轻量级买入侧参数前置检查：代码后缀/价格/数量合规性。
    返回 (ok: bool, msg: str)
    """
    try:
        if not stock_code or len(stock_code) < 6:
            return False, "股票代码无效"
        if not (stock_code.endswith('.SH') or stock_code.endswith('.SZ')):
            return False, "股票代码缺少交易所后缀(.SH/.SZ)"
        if price is None or price <= 0:
            return False, "价格必须大于0"
        if volume is None or volume <= 0:
            return False, "数量必须大于0"
        if volume % 100 != 0:
            return False, "数量必须是100的整数倍"
        return True, "OK"
    except Exception as e:
        return False, f"前置检查异常: {e}"

def extract_price_data(data, field='close'):
    """
    通用数据提取函数，支持多种数据格式
    
    参数:
    data: 历史数据（DataFrame或对象列表）
    field: 要提取的字段名（'close', 'high', 'low', 'volume'等）
    
    返回:
    list: 价格数据列表
    """
    try:
        # 处理None或空数据
        if data is None:
            return []
        
        # 处理基本数据类型
        if isinstance(data, (int, float)):
            logger.warning(f"[extract_price_data] - 输入为单个数值: {data}")
            return [float(data)]
        
        if isinstance(data, str):
            logger.warning(f"[extract_price_data] - 输入为字符串: {data}")
            try:
                return [float(data)]
            except ValueError:
                return []
        
        if isinstance(data, dict):
            logger.warning(f"[extract_price_data] - 输入为字典格式")
            # 尝试多种字典结构
            if field in data:
                value = data[field]
                if isinstance(value, (list, tuple)):
                    return [float(x) for x in value if x is not None]
                else:
                    return [float(value)] if value is not None else []
            
            # 尝试嵌套字典结构 {stock_code: {field: values}}
            for key, nested_data in data.items():
                if isinstance(nested_data, dict) and field in nested_data:
                    value = nested_data[field]
                    if isinstance(value, (list, tuple)):
                        return [float(x) for x in value if x is not None]
                    else:
                        return [float(value)] if value is not None else []
            
            # 尝试直接从字典值中提取数据
            for key, value in data.items():
                if isinstance(value, (list, tuple)) and len(value) > 0:
                    # 假设这是价格数据列表
                    try:
                        return [float(x) for x in value if x is not None]
                    except (ValueError, TypeError):
                        continue
            
            logger.warning(f"[extract_price_data] - 字典中未找到有效的{field}数据")
            return []
        
        # 检查是否有长度属性
        try:
            data_len = len(data)
            if data_len == 0:
                return []
        except TypeError:
            logger.warning(f"[extract_price_data] - 数据类型无法获取长度: {type(data)}")
            return []
        
        # DataFrame格式处理
        if hasattr(data, 'columns'):
            if field in data.columns:
                return data[field].tolist()
            else:
                logger.warning(f"[extract_price_data] - DataFrame中缺少字段: {field}")
                return []
        
        # 对象列表格式处理
        elif isinstance(data, (list, tuple)) and len(data) > 0:
            if hasattr(data[0], field):
                return [getattr(bar, field) for bar in data if hasattr(bar, field)]
            else:
                logger.warning(f"[extract_price_data] - 数据对象缺少{field}属性")
                return []
        
        # 其他格式
        else:
            logger.warning(f"[extract_price_data] - 不支持的数据格式: {type(data)}")
            return []
            
    except Exception as e:
        logger.error(f"[extract_price_data] - 提取{field}数据失败: {e}")
        return []

def auto_tune_priority_trade(context=None) -> bool:
    """
    根据市场环境和指数当日强弱，自动调参 `STRATEGY_ENHANCEMENT_CONFIG['priority_trade']`
    以及 `strong_signal_rise_cap`。

    策略：
    - 牛市：更激进，提高首批试探比例与贴近涨停阈值
    - 震荡：使用默认
    - 熊市：更保守，降低首批试探比例与贴近涨停阈值
    - 同时参考沪深300当日涨跌幅进行微调
    """
    try:
        env = 'sideways'
        try:
            env = detect_market_environment(context)
        except Exception:
            env = 'sideways'

        # 基础模板
        presets = {
            'bull': {
                'probe_ratio': {'low': 0.07, 'medium': 0.10, 'high': 0.12},
                'up_limit_proximity': 0.005,
                'near_limit_cap_multiplier': 1.010,
                'plus_adj_priority': 0.013,
                'plus_adj_non_priority': 0.010,
                'strong_signal_rise_cap': 0.115,
            },
            'sideways': {
                'probe_ratio': {'low': 0.05, 'medium': 0.08, 'high': 0.10},
                'up_limit_proximity': 0.003,
                'near_limit_cap_multiplier': 1.008,
                'plus_adj_priority': 0.012,
                'plus_adj_non_priority': 0.010,
                'strong_signal_rise_cap': 0.11,
            },
            'bear': {
                'probe_ratio': {'low': 0.04, 'medium': 0.06, 'high': 0.08},
                'up_limit_proximity': 0.002,
                'near_limit_cap_multiplier': 1.006,
                'plus_adj_priority': 0.010,
                'plus_adj_non_priority': 0.009,
                'strong_signal_rise_cap': 0.10,
            }
        }

        base = presets.get(env, presets['sideways']).copy()

        # 指数当日强弱微调（若可获取）
        try:
            idx_hist = get_market_data_ex('SH000300', ['open', 'close'], 'D', 2)
            if idx_hist and len(idx_hist) >= 2:
                # 近两日收盘变化（若交易中则用当日open->close估算）
                today = idx_hist[-1]
                prev = idx_hist[-2]
                oc = (today.get('close') or 0)
                oo = (today.get('open') or 0)
                pc = (prev.get('close') or 0)
                day_chg = 0.0
                if oo and oc:
                    day_chg = (oc / oo - 1.0)
                elif pc and oc:
                    day_chg = (oc / pc - 1.0)
                # > +1% 更激进；< -1% 更保守
                if day_chg >= 0.01:
                    base['probe_ratio'] = {k: min(0.15, v + 0.01) for k, v in base['probe_ratio'].items()}
                    base['up_limit_proximity'] = min(0.006, base['up_limit_proximity'] + 0.001)
                    base['near_limit_cap_multiplier'] = min(1.012, base['near_limit_cap_multiplier'] + 0.002)
                    base['plus_adj_priority'] = min(0.015, base['plus_adj_priority'] + 0.001)
                    base['strong_signal_rise_cap'] = min(0.12, base['strong_signal_rise_cap'] + 0.005)
                elif day_chg <= -0.01:
                    base['probe_ratio'] = {k: max(0.03, v - 0.01) for k, v in base['probe_ratio'].items()}
                    base['up_limit_proximity'] = max(0.001, base['up_limit_proximity'] - 0.001)
                    base['near_limit_cap_multiplier'] = max(1.004, base['near_limit_cap_multiplier'] - 0.002)
                    base['plus_adj_priority'] = max(0.008, base['plus_adj_priority'] - 0.001)
                    base['strong_signal_rise_cap'] = max(0.095, base['strong_signal_rise_cap'] - 0.005)
        except Exception:
            pass

        # 写回配置
        try:
            pt = STRATEGY_ENHANCEMENT_CONFIG.get('priority_trade', {}) or {}
            pt['probe_ratio'] = base['probe_ratio']
            pt['up_limit_proximity'] = base['up_limit_proximity']
            pt['near_limit_cap_multiplier'] = base['near_limit_cap_multiplier']
            pt['plus_adj_priority'] = base['plus_adj_priority']
            pt['plus_adj_non_priority'] = base['plus_adj_non_priority']
            STRATEGY_ENHANCEMENT_CONFIG['priority_trade'] = pt
            STRATEGY_ENHANCEMENT_CONFIG['strong_signal_rise_cap'] = base['strong_signal_rise_cap']
            logger.info(
                f"??? 自动调参[priority_trade]: env={env} probe={pt['probe_ratio']} up_prox={pt['up_limit_proximity']} cap×={pt['near_limit_cap_multiplier']} plus={pt['plus_adj_priority']:.3f} rise_cap={STRATEGY_ENHANCEMENT_CONFIG['strong_signal_rise_cap']:.3f}"
            )
            return True
        except Exception as w_e:
            logger.warning(f"priority_trade 写回失败: {w_e}")
            return False
    except Exception as e:
        logger.warning(f"auto_tune_priority_trade 异常: {e}")
        return False

def safe_get_current_price(context, stock_code):
    """
    安全的当前价格获取函数
    
    参数:
    context: 上下文信息
    stock_code: 股票代码
    
    返回:
    float: 当前价格
    """
    try:
        # 使用get_full_tick获取最新价格
        tick_data = context.get_full_tick([stock_code])
        if tick_data and stock_code in tick_data:
            return float(tick_data[stock_code].get('lastPrice', 0))
        else:
            # 备用方案：使用get_market_data_ex（增强容错）
            try:
                market_data = context.get_market_data_ex(
                    ['close'],
                    [stock_code],
                    count=1,
                    dividend_type='front',
                    fill_data=True
                )
            except Exception:
                market_data = None
            if market_data is not None and stock_code in market_data:
                try:
                    md = market_data[stock_code]
                    # 统一提取close
                    closes = extract_price_data(md, 'close')
                    if closes:
                        return float(closes[-1])
                    # 有些返回直接是数值
                    if isinstance(md, (int, float, str)):
                        return float(md)
                except Exception:
                    pass
            return 0.0
        
    except Exception as e:
        logger.error(f"获取{stock_code}当前价格失败: {e}")
        return 0.0

