# ===== 统一股数计算系统 =====
def calculate_optimal_shares(target_amount, current_price, allow_upward_adjustment=True):
    """
    统一的股数计算函数
    
    参数:
    target_amount: 目标投资金额
    current_price: 当前股价
    allow_upward_adjustment: 是否允许向上调整
    
    返回:
    dict: {'shares': int, 'actual_amount': float, 'deviation': float}
    """
    try:
        # 类型转换和验证 - 修复BUG
        target_amount = float(target_amount) if target_amount is not None else 0
        current_price = float(current_price) if current_price is not None else 0
        
        # 参数验证
        if target_amount <= 0:
            return {'shares': 0, 'actual_amount': 0, 'deviation': 0, 'error': '目标金额无效'}
        
        if current_price <= 0:
            return {'shares': 0, 'actual_amount': 0, 'deviation': 0, 'error': '价格无效'}
        
        min_shares = 100  # A股最小交易单位
        
        # 计算理论股数
        theoretical_shares = target_amount / current_price
    except (TypeError, ValueError, ZeroDivisionError) as e:
        return {'shares': 0, 'actual_amount': 0, 'deviation': 0, 'error': f'计算错误: {e}'}
    
    if theoretical_shares < min_shares:
        # 不足最小交易单位：按测试约定返回0股（不强行提升至100股）
        return {
            'shares': 0,
            'actual_amount': 0.0,
            'deviation': 1.0,
            'warning': '金额不足最小交易单位(100股)'
        }
    
    # 向下取整到100股倍数
    target_shares_down = int(theoretical_shares / min_shares) * min_shares
    actual_amount_down = target_shares_down * current_price
    deviation_down = abs(actual_amount_down - target_amount) / target_amount
    
    if not allow_upward_adjustment:
        return {
            'shares': target_shares_down,
            'actual_amount': actual_amount_down,
            'deviation': deviation_down
        }
    
    # 向上取整到100股倍数
    target_shares_up = target_shares_down + min_shares
    actual_amount_up = target_shares_up * current_price
    deviation_up = abs(actual_amount_up - target_amount) / target_amount
    
    # 选择偏差更小的方案，但上调不能超过10%
    if deviation_up < deviation_down and deviation_up <= 0.10:
        return {
            'shares': target_shares_up,
            'actual_amount': actual_amount_up,
            'deviation': deviation_up,
            'adjustment': 'upward'
        }
    else:
        return {
            'shares': target_shares_down,
            'actual_amount': actual_amount_down,
            'deviation': deviation_down,
            'adjustment': 'downward'
        }

def validate_batch_shares(batch_results, total_target_amount, stock_code: str = None, context=None):
    """
    验证分批执行的总股数和总金额
    
    参数:
    batch_results: 分批执行结果列表
    total_target_amount: 目标总金额
    stock_code: 可选，股票代码（用于动态最小交易单位校验）
    context: 可选，上下文（用于获取交易所信息）
    
    返回:
    dict: 验证结果
    """
    total_shares = 0
    total_amount = 0
    
    for batch in batch_results:
        if batch.get('success', False):
            shares = batch.get('executed_shares', 0)
            price = batch.get('executed_price', 0)
            total_shares += shares
            total_amount += shares * price
    
    # 动态最小交易单位（默认100，BJ市场为1）
    lot = 100
    try:
        if stock_code:
            # 优先使用工具函数（若已定义）
            if 'get_round_lot_size' in globals():
                lot = int(get_round_lot_size(stock_code, context)) or 100
            else:
                code_up = str(stock_code).upper()
                lot = 1 if code_up.endswith('.BJ') else 100
    except Exception:
        lot = 100

    # 校验规则：
    # 1) 总股数为最小交易单位的整数倍
    shares_valid = (total_shares % max(1, lot) == 0) if total_shares > 0 else True
    
    # 2) 金额偏差不超过10%
    deviation = 0
    within_tolerance = True
    try:
        # 计算金额偏差
        amount_deviation = abs(total_amount - total_target_amount) / total_target_amount if total_target_amount > 0 else 0
        
        return {
            'total_shares': total_shares,
            'total_amount': total_amount,
            'target_amount': total_target_amount,
            'shares_valid': shares_valid,
            'shares_remainder': total_shares % max(1, lot),
            'lot_size': lot,
            'amount_deviation': amount_deviation,
            'amount_deviation_pct': amount_deviation * 100,
            'within_tolerance': amount_deviation <= 0.10  # 收紧到10%容差
        }
    except Exception as e:
        logger.error(f"validate_batch_shares: {e}")
        return {
            'total_shares': total_shares,
            'total_amount': total_amount,
            'target_amount': total_target_amount,
            'shares_valid': shares_valid,
            'shares_remainder': total_shares % max(1, lot),
            'lot_size': lot,
            'amount_deviation': 0,
            'amount_deviation_pct': 0,
            'within_tolerance': False
        }


# ===== 数据获取优化系统 =====
class DataCache:
    """智能数据缓存系统，避免重复API调用"""
    
    def __init__(self, tick_cache_duration=5, market_cache_duration=300):
        self.tick_cache = {}  # 实时数据缓存
        self.market_cache = {}  # 历史数据缓存
        self.tick_cache_duration = tick_cache_duration  # 实时数据缓存5秒（优化）
        self.market_cache_duration = market_cache_duration  # 历史数据缓存5分钟
        self.last_cleanup = time_module.time()
        
        # 分层缓存策略：不同场景使用不同缓存时长
        self.cache_strategies = {
            'trading': 3,      # 交易执行：3秒缓存
            'analysis': 10,    # 技术分析：10秒缓存
            'monitoring': 30   # 监控报告：30秒缓存
        }
    
    def _cleanup_expired_cache(self):
        """清理过期缓存"""
        current_time = time_module.time()
        if current_time - self.last_cleanup < 60:  # 每分钟清理一次
            return
        
        # 清理过期的实时数据缓存
        expired_keys = []
        for key, (data, timestamp) in self.tick_cache.items():
            if current_time - timestamp > self.tick_cache_duration:
                expired_keys.append(key)
        for key in expired_keys:
            del self.tick_cache[key]
        
        # 清理过期的历史数据缓存
        expired_keys = []
        for key, (data, timestamp) in self.market_cache.items():
            if current_time - timestamp > self.market_cache_duration:
                expired_keys.append(key)
        for key in expired_keys:
            del self.market_cache[key]
        
        self.last_cleanup = current_time
    
    def _is_cache_expired(self, timestamp, duration):
        """检查缓存是否过期 - 修复BUG"""
        try:
            current_time = time_module.time()
            
            # 处理不同类型的时间戳 - 修复类型混淆BUG
            if isinstance(timestamp, datetime):
                # 将datetime转换为时间戳
                timestamp = timestamp.timestamp()
            elif not isinstance(timestamp, (int, float)):
                # 无效的时间戳类型，认为已过期
                return True
            
            return (current_time - timestamp) > duration
        except Exception as e:
            # 发生任何错误都认为缓存已过期，保证安全性
            logger.warning(f"缓存过期检查异常: {e}")
            return True
    
    def get_tick_data(self, stock_codes, context, cache_strategy='analysis'):
        """获取实时数据（带智能缓存策略）"""
        self._cleanup_expired_cache()
        
        # 严格验证context参数类型
        if context is None:
            logger.error("get_tick_data: context参数为None")
            return None
        
        if isinstance(context, str):
            logger.error(f"get_tick_data: context参数错误，传入了字符串'{context}'，应该传入ContextInfo对象")
            return None
        
        if not hasattr(context, 'get_full_tick'):
            logger.error(f"get_tick_data: context对象缺少get_full_tick方法，context类型: {type(context)}")
            return None
        
        if not callable(getattr(context, 'get_full_tick')):
            logger.error(f"get_tick_data: context.get_full_tick不是可调用方法")
            return None
        
        # 生成缓存键
        cache_key = f"{','.join(stock_codes)}_{cache_strategy}"
        current_time = time_module.time()
        
        # 检查缓存
        if cache_key in self.tick_cache:
            cached_data, cached_time = self.tick_cache[cache_key]
            cache_age = current_time - cached_time
            
            # 根据策略决定缓存有效期
            if cache_strategy == 'trading':
                max_age = 1  # 交易时1秒缓存
            else:
                max_age = 3  # 分析时3秒缓存
            
            if cache_age < max_age:
                return cached_data
        
        # 获取新数据
        try:
            tick_data = context.get_full_tick(stock_codes)
            if tick_data:
                self.tick_cache[cache_key] = (tick_data, current_time)
                return tick_data
        except Exception as e:
            logger.error(f"获取实时数据失败: {e}")
        
        return None
    
    def get_market_data_ex(self, stock_codes, fields, period='1d', count=20, context=None, dividend_type='front', fill_data=True):
        """获取历史数据（带缓存）- 使用最新的get_market_data_ex API"""
        self._cleanup_expired_cache()
        
        if isinstance(stock_codes, str):
            stock_codes = [stock_codes]
        
        # 生成缓存键
        cache_key = (tuple(sorted(stock_codes)), tuple(fields), period, count, dividend_type, fill_data)
        current_time = time_module.time()
        
        if cache_key in self.market_cache:
            data, timestamp = self.market_cache[cache_key]
            if current_time - timestamp < self.market_cache_duration:
                return data
        
        # 缓存未命中，调用API
        try:
            if context:
                market_data = context.get_market_data_ex(
                    fields,  # fields参数直接传递
                    stock_codes,  # stock_code参数直接传递
                    period=period,
                    count=count,
                    dividend_type=dividend_type,
                    fill_data=fill_data,
                    subscribe=True
                )
                if market_data:
                    self.market_cache[cache_key] = (market_data, current_time)
                    return market_data
        except Exception as e:
            logger.warning(f"获取历史数据失败: {e}")
        
        return None

# 全局数据缓存实例
data_cache = DataCache()

