def is_st_stock(stock_code: str, ContextInfo=None) -> bool:
    """
    判断是否为ST股票
    
    参数:
    stock_code: 股票代码，如 '600000.SH'
    
    返回:
    bool: True表示是ST股票，False表示不是
    """
    try:
        if not stock_code or not isinstance(stock_code, str):
            return False
            
        # 1. 通过股票名称判断（如果可以获取到股票名称）
        try:
            # 尝试通过系统API获取股票名称
            stock_name = get_stock_name(stock_code, ContextInfo)
            if stock_name:
                # 规范化：去空白、全角转半角、统一大写
                name_norm = ''.join(str(stock_name).split()).upper()
                # 常见标识：ST、*ST、S*ST、SST、*SST、PT、退/退市
                indicators = ['ST', '*ST', 'S*ST', 'SST', '*SST', 'PT', '退', '退市']
                for ind in indicators:
                    if ind in name_norm:
                        logger.debug(f"通过名称识别ST股票: {stock_code} ({stock_name})")
                        return True
        except Exception as e:
            logger.debug(f"获取股票名称失败 {stock_code}: {e}")
        
        # 2. 检查特殊代码模式（退市整理板等）
        st_code_patterns = [
            '4000',  # 退市整理板
            '4001',  # 退市整理板
        ]
        
        code_part = stock_code.split('.')[0]
        
        # 检查退市整理板代码模式
        for pattern in st_code_patterns:
            if code_part.startswith(pattern):
                logger.debug(f"通过代码模式识别退市整理板: {stock_code}")
                return True
        
        # 3. 可选：对特定板块代码进行额外过滤（保守起见关闭一刀切）

        return False
        
    except Exception as e:
        logger.debug(f"判断ST股票失败 {stock_code}: {e}")
        return False

def get_stock_name(stock_code: str, ContextInfo=None) -> str:
    """
    获取股票名称
    
    使用ContextInfo.get_instrumentdetail()API获取股票的合约名称
    
    参数:
    stock_code: 股票代码，如 '600000.SH'
    ContextInfo: 策略上下文对象
    
    返回:
    str: 股票名称，如果无法获取则返回空字符串
    """
    try:
        # 使用传入的ContextInfo获取合约详细信息
        if ContextInfo:
            contract_info = get_instrumentdetail(stock_code, ContextInfo) if 'get_instrumentdetail' in dir() else None
            if contract_info and 'InstrumentName' in contract_info:
                stock_name = contract_info['InstrumentName']
                logger.debug(f"获取股票名称成功: {stock_code} -> {stock_name}")
                return stock_name
        
        # 如果无法通过ContextInfo获取，尝试其他方式
        # 这里可以添加其他获取股票名称的方法
        
        return ""
        
    except Exception as e:
        logger.debug(f"获取股票名称失败 {stock_code}: {e}")
        return ""

def filter_risky_stocks(stock_list: List[str], ContextInfo=None) -> List[str]:
    """
    过滤风险股票（ST、*ST、退市等）
    
    参数:
    stock_list: 股票代码列表
    
    返回:
    List[str]: 过滤后的股票列表
    """
    try:
        if not stock_list:
            return []
            
        filtered_stocks = []
        filtered_count = 0
        
        for stock_code in stock_list:
            # 检查是否为ST股票
            if is_st_stock(stock_code, ContextInfo):
                filtered_count += 1
                logger.info(f"过滤ST股票: {stock_code}")
                continue
                
            # 检查是否为停牌股票（如果有相关API）
            if is_suspended_stock(stock_code):
                filtered_count += 1
                logger.info(f"过滤停牌股票: {stock_code}")
                logger.debug(f"过滤停牌股票: {stock_code}")
                continue
                
            filtered_stocks.append(stock_code)
        
        if filtered_count > 0:
            logger.info(f"风险股票过滤: 原始{len(stock_list)}只 → 过滤{filtered_count}只 → 剩余{len(filtered_stocks)}只")
        
        return filtered_stocks
        
    except Exception as e:
        logger.error(f"过滤风险股票失败: {e}")
        return stock_list  # 失败时返回原始列表

