def get_sell_action_cooldowns():
    try:
        return dict(SELL_ACTION_COOLDOWN_CONFIG)
    except Exception:
        return {}

def set_sell_action_cooldowns(new_map):
    """
    运行时更新卖出动作冷却配置。
    仅接受非负整数/浮点（将取整）的秒数；忽略非法键值。
    """
    try:
        if not isinstance(new_map, dict):
            return False
        for k, v in new_map.items():
            try:
                sec = int(max(0, float(v)))
            except Exception:
                continue
            SELL_ACTION_COOLDOWN_CONFIG[k] = sec
        logger.info(f"? 已更新卖出动作冷却配置: {SELL_ACTION_COOLDOWN_CONFIG}")
        return True
    except Exception as e:
        logger.warning(f"更新卖出动作冷却配置失败: {e}")
        return False

