# 统一的可靠成本价获取函数（全局）- 增强T+0处理
def get_reliable_cost_price(context, stock_code: str) -> float:
    """获取可靠的持仓成本价，处理T+0大量卖出导致的负持仓问题。
    优先级：m_dCostPrice > m_dAvgPrice/m_dAveragePrice > 历史买入价推算 > 缓存position_cost_cache。
    增强功能：处理T+0大量卖出导致的负持仓和成本价异常。
    """
    try:
        # 尝试从POSITION列表获取
        positions = get_trade_detail_data(context.accID, context.accIDType, 'POSITION')
        target = None
        if positions:
            for pos in positions:
                code = getattr(pos, 'm_strInstrumentID', None)
                if str(code) == str(stock_code):
                    target = pos
                    break
        
        # 基于对象字段优先级选择，增强T+0异常处理
        def _pos_field_with_t0_fix(name):
            try:
                v = getattr(target, name)
                if v is None:
                    return 0.0
                
                cost_price = float(v)
                
                # 智能成本价异常修正逻辑
                if cost_price < 0:
                    # 不直接取绝对值，而是先判断是否合理
                    abs_price = abs(cost_price)
                    
                    # 获取当前价格作为参考
                    try:
                        current_price = get_stock_current_price(stock_code, context) if 'context' in locals() else None
                        if current_price and current_price > 0:
                            # 如果绝对值距离当前价格太远（超过3倍），则认为数据错误
                            if abs_price > current_price * 3 or abs_price < current_price * 0.3:
                                logger.error(f"? {stock_code} 负数成本价{cost_price:.3f}绝对值{abs_price:.3f}与当前价{current_price:.3f}差距过大，数据错误")
                                return 0.0
                            else:
                                logger.warning(f"?? {stock_code} T+0负数成本价修正: {cost_price:.3f} → {abs_price:.3f}元 (字段: {name})")
                                return abs_price
                        else:
                            # 无法获取当前价格，使用保守策略
                            if 0.01 <= abs_price <= 1000:  # 更严格的范围
                                logger.warning(f"?? {stock_code} T+0负数成本价修正(无参考价): {cost_price:.3f} → {abs_price:.3f}元")
                                return abs_price
                            else:
                                logger.error(f"? {stock_code} 负数成本价绝对值超出合理范围: {abs_price:.3f}元")
                                return 0.0
                    except Exception as e:
                        logger.error(f"获取当前价格失败: {e}")
                        return 0.0
                
                # 正常价格范围检查
                if 0.01 <= cost_price <= 10000:
                    return cost_price
                else:
                    logger.warning(f"?? {stock_code} 成本价超出合理范围: {cost_price:.3f}元 (字段: {name})")
                    return 0.0
                    
            except Exception as e:
                logger.debug(f"获取成本价字段{name}失败: {e}")
                return 0.0
        
        if target is not None:
            # 按优先级尝试获取成本价，包含T+0修正
            for fld in ('m_dCostPrice', 'm_dAvgPrice', 'm_dAveragePrice'):
                v = _pos_field_with_t0_fix(fld)
                if v > 0:
                    logger.info(f"? {stock_code} 获取可靠成本价: {v:.3f}元 (字段: {fld})")
                    return v
        
        # 缓存回退
        try:
            cache = position_cost_cache.get(stock_code)
            if cache and (datetime.now() - cache['update_time']).seconds < 3600:
                v = float(cache.get('cost_price') or 0)
                if v > 0:
                    logger.info(f"? {stock_code} 使用缓存成本价: {v:.3f}元")
                    return v
        except Exception:
            pass
        
        # 最后回退到开仓价（含T+0修正）
        if target is not None:
            return _pos_field_with_t0_fix('m_dOpenPrice')
        
        # T+0大量卖出情况：尝试从历史交易记录推算成本价
        try:
            historical_cost = estimate_cost_from_trading_history(context, stock_code)
            if historical_cost and historical_cost > 0:
                logger.info(f"?? {stock_code} 从历史交易推算成本价: {historical_cost:.3f}元")
                # 更新缓存
                position_cost_cache[stock_code] = {
                    'cost_price': historical_cost,
                    'update_time': datetime.now(),
                    'source': 'historical_estimate'
                }
                return historical_cost
        except Exception as e:
            logger.debug(f"历史交易成本价推算失败: {e}")
        
        # 尝试增强版成本价获取（最后的备用方案）
        try:
            enhanced_price = get_enhanced_position_cost_price(target, stock_code)
            if enhanced_price and enhanced_price > 0:
                logger.info(f"?? {stock_code} 使用增强版成本价: {enhanced_price:.3f}元")
                return enhanced_price
        except Exception as e:
            logger.debug(f"增强版成本价获取失败: {e}")
        
        logger.error(f"? {stock_code} 无法获取有效成本价，所有方法均失败")
        return 0.0
        
    except Exception as e:
        logger.error(f"获取可靠成本价异常 {stock_code}: {e}")
        return 0.0

def update_cost_price_cache(stock_code: str, cost_price: float, source: str = 'manual'):
    """更新成本价缓存
    
    参数:
    stock_code: 股票代码
    cost_price: 成本价
    source: 数据来源
    """
    global position_cost_cache
    try:
        if cost_price > 0:
            position_cost_cache[stock_code] = {
                'cost_price': float(cost_price),
                'update_time': datetime.now(),
                'source': source
            }
            logger.info(f"? {stock_code} 成本价缓存已更新: {cost_price:.3f}元 (来源: {source})")
    except Exception as e:
        logger.error(f"更新成本价缓存失败 {stock_code}: {e}")

def estimate_cost_from_trading_history(context, stock_code: str) -> float:
    """从历史交易记录推算合理的成本价
    
    用于处理T+0大量卖出导致负持仓的情况
    通过分析最近的买入记录来推算当前持仓的合理成本价
    """
    try:
        # 获取交易明细数据
        trades = get_trade_detail_data(context.accID, context.accIDType, 'DEAL')
        if not trades:
            return 0.0
        
        # 筛选该股票的买入交易记录（最近30天）
        recent_buys = []
        cutoff_date = datetime.now() - timedelta(days=30)
        
        for trade in trades:
            if (hasattr(trade, 'm_strInstrumentID') and 
                str(trade.m_strInstrumentID) == stock_code and
                hasattr(trade, 'm_nDirection') and 
                trade.m_nDirection == 48):  # 48表示买入
                
                # 获取交易价格和数量
                trade_price = getattr(trade, 'm_dPrice', 0)
                trade_volume = getattr(trade, 'm_nVolume', 0)
                
                if trade_price > 0 and trade_volume > 0:
                    recent_buys.append({
                        'price': float(trade_price),
                        'volume': int(trade_volume),
                        'amount': float(trade_price) * int(trade_volume)
                    })
        
        if not recent_buys:
            return 0.0
        
        # 计算加权平均成本价
        total_amount = sum(buy['amount'] for buy in recent_buys)
        total_volume = sum(buy['volume'] for buy in recent_buys)
        
        if total_volume > 0:
            weighted_avg_cost = total_amount / total_volume
            logger.info(f"?? {stock_code} 历史交易推算成本价: {weighted_avg_cost:.3f}元 (基于{len(recent_buys)}笔买入)")
            return weighted_avg_cost
        
        return 0.0
        
    except Exception as e:
        logger.error(f"历史交易成本价推算异常 {stock_code}: {e}")
        return 0.0

def get_t0_cost_fix_report() -> str:
    """获取T+0成本价修复报告"""
    global t0_cost_fix_stats
    try:
        total = t0_cost_fix_stats['total_fixes']
        success = t0_cost_fix_stats['successful_fixes']
        failed = t0_cost_fix_stats['failed_fixes']
        last_fix = t0_cost_fix_stats['last_fix_time']
        
        if total == 0:
            return "?? T+0成本价修复统计: 无修复记录"
        
        success_rate = (success / total * 100) if total > 0 else 0
        last_fix_str = last_fix.strftime('%Y-%m-%d %H:%M:%S') if last_fix else '无'
        
        return (f"?? T+0成本价修复统计: "
                f"总计{total}次, 成功{success}次, 失败{failed}次, "
                f"成功率{success_rate:.1f}%, 最后修复: {last_fix_str}")
    except Exception as e:
        return f"?? T+0修复统计获取失败: {e}"

