# 统一信号级别常量定义
SIGNAL_THRESHOLDS = {
    'perfect': 5.0,     # 完美信号：突破强度≥5.0%
    'excellent': 3.5,   # 优秀信号：突破强度≥3.5%
    'premium': 2.5,     # 顶级信号：突破强度≥2.5%
    'confirmed': 1.5,   # 标准信号：突破强度≥1.5%
    'detected': 0.8,    # 探测信号：突破强度≥0.8%
    'pullback': 0       # 回调信号：突破强度<0.8%
}

# ===== 6级信号分类系统 =====
# 已完全升级为6级信号分类，移除旧的3级兼容性映射
# 信号等级：perfect > excellent > premium > confirmed > detected > pullback

def generate_smart_strategy_from_signal(stock_code, signal_strength):
    """
    根据信号强度智能生成买入策略配置
    
    参数:
    stock_code: 股票代码
    signal_strength: 信号强度 (0-6)
    
    返回:
    dict: 包含策略配置的字典
    """
    try:
        # 根据信号强度映射策略配置
        if signal_strength >= 6:
            # 完美信号 - 激进策略
            return {
                'position_ratio': 0.8,
                'strategy': 'aggressive',
                'timing': 'immediate'
            }
        elif signal_strength >= 5:
            # 优秀信号 - 积极策略
            return {
                'position_ratio': 0.6,
                'strategy': 'active',
                'timing': 'immediate'
            }
        elif signal_strength >= 4:
            # 标准信号 - 平衡策略
            return {
                'position_ratio': 0.5,
                'strategy': 'balanced',
                'timing': 'pullback_support'
            }
        else:
            # 弱信号 - 谨慎策略
            return {
                'position_ratio': 0.3,
                'strategy': 'cautious',
                'timing': 'deep_pullback'
            }
    except Exception as e:
        logger.warning(f"生成{stock_code}智能策略失败: {e}")
        # 返回默认保守策略
        return {
            'position_ratio': 0.3,
            'strategy': 'conservative',
            'timing': 'pullback_support'
        }

def get_signal_strength_level(ma_deviation):
    """
    根据均线偏离度判断信号强度等级 - 统一版本
    
    参数:
    ma_deviation: 均线偏离度（百分比，如3.5表示3.5%）或突破强度
    
    返回:
    信号强度等级: 'perfect', 'excellent', 'premium', 'confirmed', 'detected', 'pullback'
    """
    try:
        # 修复None值处理BUG
        if ma_deviation is None:
            logger.warning("均线偏离度为None，返回弱信号")
            return 'pullback'
        
        deviation = abs(float(ma_deviation))
        
        # 添加调试日志
        logger.debug(f"?? 信号强度分析: {deviation}%")
        
        # 使用统一的6级分类系统
        if deviation >= SIGNAL_THRESHOLDS['perfect']:
            logger.debug(f"? 完美信号: {deviation}% >= {SIGNAL_THRESHOLDS['perfect']}%")
            return 'perfect'
        elif deviation >= SIGNAL_THRESHOLDS['excellent']:
            logger.debug(f"?? 优秀信号: {deviation}% >= {SIGNAL_THRESHOLDS['excellent']}%")
            return 'excellent'
        elif deviation >= SIGNAL_THRESHOLDS['premium']:
            logger.debug(f"?? 顶级信号: {deviation}% >= {SIGNAL_THRESHOLDS['premium']}%")
            return 'premium'
        elif deviation >= SIGNAL_THRESHOLDS['confirmed']:
            logger.debug(f"?? 标准信号: {deviation}% >= {SIGNAL_THRESHOLDS['confirmed']}%")
            return 'confirmed'
        elif deviation >= SIGNAL_THRESHOLDS['detected']:
            logger.debug(f"?? 探测信号: {deviation}% >= {SIGNAL_THRESHOLDS['detected']}%")
            return 'detected'
        else:
            logger.debug(f"?? 回调信号: {deviation}% < {SIGNAL_THRESHOLDS['detected']}%")
            return 'pullback'
    except Exception as e:
        logger.error(f"? 信号强度判断异常: {e}, 输入值: {ma_deviation}")
        return 'pullback'  # 默认返回最弱信号

