def get_adaptive_signal_weight(signal_level, market_env='sideways'):
    """
    根据信号强度和市场环境返回自适应资金权重倍数 - 升级版6级信号支持
    
    参数:
        signal_level: 信号强度等级 ('perfect', 'excellent', 'premium', 'confirmed', 'detected', 'pullback')
        market_env: 市场环境 ('bull', 'bear', 'sideways')
    
    返回:
        权重倍数: 根据市场环境调整的权重
    """
    # 市场环境自适应权重配置
    adaptive_weights = {
        'bull': {      # 牛市：高质量信号可靠性高，提升权重
            'perfect': 2.2,     # 完美信号2.2倍权重
            'excellent': 1.8,   # 优秀信号1.8倍权重
            'premium': 1.4,     # 顶级信号1.4倍权重
            'confirmed': 1.0,   # 标准信号标准权重
            'detected': 0.7,    # 探测信号0.7倍权重
            'pullback': 0.4     # 回调信号0.4倍权重
        },
        'bear': {      # 熊市：整体可靠性下降，保守配置
            'perfect': 1.6,     # 完美信号1.6倍权重
            'excellent': 1.3,   # 优秀信号1.3倍权重
            'premium': 1.1,     # 顶级信号1.1倍权重
            'confirmed': 1.0,   # 标准信号标准权重
            'detected': 0.8,    # 探测信号0.8倍权重
            'pullback': 0.6     # 回调信号0.6倍权重
        },
        'sideways': {  # 震荡市：平衡配置
            'perfect': 2.0,     # 完美信号2.0倍权重
            'excellent': 1.6,   # 优秀信号1.6倍权重
            'premium': 1.3,     # 顶级信号1.3倍权重
            'confirmed': 1.0,   # 标准信号标准权重
            'detected': 0.7,    # 探测信号0.7倍权重
            'pullback': 0.5     # 回调信号0.5倍权重
        }
    }
    
    # 安全获取市场环境权重配置
    market_weights = adaptive_weights.get(market_env)
    if market_weights is None or not isinstance(market_weights, dict):
        market_weights = adaptive_weights['sideways']
    
    return market_weights.get(signal_level, 1.0)

def get_signal_weight_multiplier(signal_level, context=None, use_adaptive=True):
    """
    根据信号强度返回资金权重倍数（支持市场环境自适应）- 升级版6级信号支持
    
    参数:
        signal_level: 信号强度等级 ('perfect', 'excellent', 'premium', 'confirmed', 'detected', 'pullback')
        context: 交易上下文（用于获取市场环境）
        use_adaptive: 是否使用自适应权重
    
    返回:
        权重倍数: 浮点数
    """
    global current_market_environment
    
    if use_adaptive:
        # 使用系统现有的市场环境检测结果
        if context is not None:
            # 如果有上下文，使用实时检测
            market_env = detect_market_environment(context)
        else:
            # 否则使用全局变量中的市场环境
            market_env = current_market_environment
            
        weight = get_adaptive_signal_weight(signal_level, market_env)
        
        # 记录市场环境和权重调整
        env_names = {'bull': '牛市', 'bear': '熊市', 'extreme_bear': '极端熊市', 'sideways': '震荡市'}
        logger.info(f"市场环境: {env_names.get(market_env, '未知')} | 信号权重: {signal_level}={weight:.1f}x")
        
        return weight
    else:
        # 使用固定权重配置（震荡市配置）
        weight_map = {
            'strong': 1.3,   # 强信号1.3倍权重
            'medium': 1.0,   # 中等信号标准权重
            'weak': 0.6      # 弱信号0.6倍权重
        }
        return weight_map.get(signal_level, 1.0)

def get_signal_weight(x, context=None, use_adaptive=True):
    """
    统一的信号权重入口（兼容数值或等级字符串）
    
    参数:
    - x: 可为数值型(均线偏离度/突破强度，单位%)或字符串信号等级
          数值示例: 3.5 → 表示3.5%
          字符串示例: 'premium'/'confirmed' 等
    - context: 上下文（用于市场环境自适应）
    - use_adaptive: 是否启用市场环境自适应权重
    
    返回:
    - float: 权重倍数
    """
    try:
        # 字符串等级，直接取权重
        if isinstance(x, str):
            level = x.strip().lower()
            return get_signal_weight_multiplier(level, context, use_adaptive)
        
        # 数值 → 转等级后取权重
        val = float(x)
        level = get_signal_strength_level(val)
        return get_signal_weight_multiplier(level, context, use_adaptive)
    except Exception as e:
        logger.warning(f"get_signal_weight 计算失败({x}): {e}，返回默认1.0")
        return 1.0

def calculate_weighted_position_amounts(selected_stocks, total_investment, signal_strengths, context_info=None):
    """
    统一的加权资金分配函数 - 解决建仓规划与买入执行不一致问题
    
    参数:
    selected_stocks: 选中的股票列表
    total_investment: 总投资金额
    signal_strengths: 股票信号强度字典 {股票代码: 信号等级}
    context_info: 上下文信息（用于获取均线偏离度）
    
    返回:
    dict: {股票代码: 分配金额}
    """
    if not selected_stocks:
        return {}
    
    try:
        # 计算每只股票的权重
        stock_weights = {}
        total_weight = 0
        
        for stock in selected_stocks:
            # 获取信号强度等级
            signal_level = signal_strengths.get(stock, 'medium')
            
            # 如果没有预设信号强度，尝试实时计算
            if signal_level == 'medium' and context_info:
                try:
                    # 获取股票的均线偏离度
                    stock_data = context_info.get_market_data_ex(['close'], [stock], period='1d', count=20)
                    if stock_data and stock in stock_data:
                        stock_price_data = stock_data[stock]
                        close_prices = extract_price_data(stock_price_data, 'close')
                        if len(close_prices) >= 5:
                            recent_prices = close_prices[-5:]
                            ma5 = sum(recent_prices) / len(recent_prices)
                            current_price = recent_prices[-1]
                            ma_deviation = ((current_price - ma5) / ma5) * 100
                            signal_level = get_signal_strength_level(ma_deviation)
                        else:
                            logger.warning(f"{stock} 数据不足5条，使用默认中等信号")
                            signal_level = 'medium'
                    else:
                        logger.warning(f"{stock} 无法获取数据，使用默认中等信号")
                        signal_level = 'medium'
                except Exception as e:
                    logger.warning(f"获取{stock}信号强度失败: {e}，使用默认中等信号")
                    signal_level = 'medium'
            
            # 获取权重（支持市场环境自适应）
            weight = get_signal_weight_multiplier(signal_level, context_info)
            stock_weights[stock] = weight
            total_weight += weight
            
            logger.debug(f"{stock}: 信号等级={signal_level}, 权重={weight}")
        
        # 处理权重为0的情况：平均分配
        if total_weight <= 0:
            equal = total_investment / len(selected_stocks)
            logger.warning("?? 信号权重总和为0，使用平均分配")
            return {s: equal for s in selected_stocks}

        # 按权重分配资金
        position_amounts = {}
        allocated_total = 0
        
        for stock in selected_stocks:
            weight = stock_weights[stock]
            amount = (weight / total_weight) * total_investment
            position_amounts[stock] = amount
            allocated_total += amount
            
            signal_level = signal_strengths.get(stock, 'medium')
            logger.info(f"?? {stock} 加权资金分配: {signal_level.upper()}信号 → 权重{weight:.1f}x → 分配{amount:.0f}元")
        
        logger.info(f"?? 加权资金分配完成: 总投资{total_investment:.0f}元, 实际分配{allocated_total:.0f}元")
        
        return position_amounts
        
    except Exception as e:
        logger.error(f"加权资金分配失败: {e}")
        # 失败时使用平均分配
        avg_amount = total_investment / len(selected_stocks)
        return {stock: avg_amount for stock in selected_stocks}

def is_in_trading_window(current_time, signal_level):
    """
    检查当前时间是否在指定信号等级的交易窗口内 - 升级版6级信号支持
    
    参数:
    current_time: 当前时间字符串，格式如 '14:20:53' 或 datetime对象
    signal_level: 信号等级 'perfect', 'excellent', 'premium', 'confirmed', 'detected', 'pullback'
    
    返回:
    (bool, str): (是否在窗口内, 描述信息)
    """
    try:
        # 获取当前时间（分钟数）
        if isinstance(current_time, str):
            if len(current_time) > 8:
                time_str = current_time.split('.')[0]
            else:
                time_str = current_time
            time_parts = time_str.split(':')
            current_hour = int(time_parts[0])
            current_minute = int(time_parts[1])
            current_time_minutes = current_hour * 60 + current_minute
        else:
            current_time_minutes = current_time.hour * 60 + current_time.minute
        
        # 基础交易时间检查（所有信号都需要在交易时间内）
        morning_start = 9 * 60 + 30  # 09:30
        morning_end = 11 * 60 + 30   # 11:30
        afternoon_start = 13 * 60    # 13:00
        afternoon_end = 15 * 60      # 15:00
        
        is_trading_time = (morning_start <= current_time_minutes <= morning_end) or \
                         (afternoon_start <= current_time_minutes <= afternoon_end)
        
        # 如果不在交易时间内，直接返回
        if not is_trading_time:
            return False, "? 当前不在交易时间内（09:30-11:30, 13:00-15:00）"
        
        # ?? 完美和优秀信号全天候执行，不受时间窗口限制
        if signal_level in ['perfect', 'excellent']:
            signal_desc = "完美" if signal_level == 'perfect' else "优秀"
            return True, f"?? {signal_desc}信号全天候执行，当前在交易时间内"
        
        # 处理时间格式（其他信号等级）
        if isinstance(current_time, str):
            if len(current_time) > 8:  # 包含毫秒的情况
                time_str = current_time.split('.')[0]
            else:
                time_str = current_time
            
            # 提取时分
            time_parts = time_str.split(':')
            current_hour = int(time_parts[0])
            current_minute = int(time_parts[1])
            current_time_minutes = current_hour * 60 + current_minute
        else:
            # datetime对象
            current_time_minutes = current_time.hour * 60 + current_time.minute
        
        # 获取对应信号等级的时间窗口
        if signal_level not in TRADING_TIME_WINDOWS:
            signal_level = 'pullback'  # 默认使用最严格的窗口
            logger.warning(f"未知信号等级，使用默认回调信号窗口: {signal_level}")
        
        windows = TRADING_TIME_WINDOWS[signal_level]
        
        # 检查上午窗口
        morning_start = windows['morning'][0]
        morning_end = windows['morning'][1]
        morning_start_minutes = int(morning_start.split(':')[0]) * 60 + int(morning_start.split(':')[1])
        morning_end_minutes = int(morning_end.split(':')[0]) * 60 + int(morning_end.split(':')[1])
        
        # 检查下午窗口
        afternoon_start = windows['afternoon'][0]
        afternoon_end = windows['afternoon'][1]
        afternoon_start_minutes = int(afternoon_start.split(':')[0]) * 60 + int(afternoon_start.split(':')[1])
        afternoon_end_minutes = int(afternoon_end.split(':')[0]) * 60 + int(afternoon_end.split(':')[1])
        
        # 判断是否在窗口内
        in_morning_window = morning_start_minutes <= current_time_minutes <= morning_end_minutes
        in_afternoon_window = afternoon_start_minutes <= current_time_minutes <= afternoon_end_minutes
        
        is_in_window = in_morning_window or in_afternoon_window
        
        # 信号等级中文描述映射
        signal_desc_map = {
            'premium': '顶级',
            'confirmed': '标准', 
            'detected': '探测',
            'pullback': '回调'
        }
        signal_desc = signal_desc_map.get(signal_level, signal_level.upper())
        
        if is_in_window:
            window_type = "上午窗口" if in_morning_window else "下午窗口"
            description = f"? {signal_desc}信号在{window_type}内，允许买入"
        else:
            description = f"? {signal_desc}信号不在买入窗口内 (窗口: {windows['morning'][0]}-{windows['morning'][1]}, {windows['afternoon'][0]}-{windows['afternoon'][1]})"
        
        return is_in_window, description
        
    except Exception as e:
        logger.error(f"时间窗口检查失败: {e}")
        return False, f"时间窗口检查失败: {e}"

def is_market_open(current_time=None):
    """
    检查市场是否开放交易
    
    参数:
    current_time: 当前时间，可以是datetime对象或时间字符串，默认使用当前时间
    
    返回:
    (bool, str, dict): (是否开市, 描述信息, 详细信息)
    """
    try:
        # 获取当前时间
        if current_time is None:
            now = datetime.now()
        elif isinstance(current_time, str):
            # 解析时间字符串
            if len(current_time) > 8:
                time_str = current_time.split('.')[0]
            else:
                time_str = current_time
            time_parts = time_str.split(':')
            now = datetime.now().replace(
                hour=int(time_parts[0]), 
                minute=int(time_parts[1]), 
                second=int(time_parts[2]) if len(time_parts) > 2 else 0,
                microsecond=0
            )
        else:
            now = current_time
        
        # 检查是否是工作日（周一到周五）
        weekday = now.weekday()  # 0=Monday, 6=Sunday
        if weekday >= 5:  # 周六或周日
            # 仅当配置启用周末禁跑时，才在此直接返回
            if MARKET_CALENDAR.get('disable_weekend_run', True):
                return False, f"? 周末不开市 (周{'六' if weekday == 5 else '日'})", {
                    'is_weekend': True,
                    'weekday': weekday,
                    'current_time': now.strftime('%H:%M:%S')
                }
        
        # 获取当前时间（分钟数）
        current_minutes = now.hour * 60 + now.minute
        
        # 交易时间段
        morning_start = 9 * 60 + 30   # 09:30
        morning_end = 11 * 60 + 30    # 11:30
        afternoon_start = 13 * 60     # 13:00
        afternoon_end = 15 * 60       # 15:00
        
        # 检查是否在交易时间内
        in_morning = morning_start <= current_minutes <= morning_end
        in_afternoon = afternoon_start <= current_minutes <= afternoon_end
        is_trading = in_morning or in_afternoon
        
        # 计算距离下一个交易时段的时间
        next_session_info = ""
        if current_minutes < morning_start:
            # 开市前
            minutes_to_open = morning_start - current_minutes
            next_session_info = f"距离开市还有{minutes_to_open}分钟"
        elif morning_end < current_minutes < afternoon_start:
            # 午休时间
            minutes_to_open = afternoon_start - current_minutes
            next_session_info = f"午休中，距离下午开市还有{minutes_to_open}分钟"
        elif current_minutes > afternoon_end:
            # 收市后
            next_session_info = "今日交易已结束"
        
        if is_trading:
            session = "上午" if in_morning else "下午"
            return True, f"? 市场开放中 ({session}交易时段)", {
                'is_trading': True,
                'session': session,
                'current_time': now.strftime('%H:%M:%S'),
                'weekday': weekday
            }
        else:
            return False, f"? 市场未开放 - {next_session_info}", {
                'is_trading': False,
                'current_time': now.strftime('%H:%M:%S'),
                'next_session_info': next_session_info,
                'weekday': weekday
            }
            
    except Exception as e:
        logger.error(f"市场开放检查失败: {e}")
        return False, f"? 市场状态检查异常: {e}", {'error': str(e)}

def smart_trading_time_control(signal_level, current_time=None, strict_mode=False):
    """
    智能交易时间控制 - 综合考虑市场开放状态和信号等级
    
    参数:
    signal_level: 信号等级
    current_time: 当前时间
    strict_mode: 是否启用严格模式（严格模式下所有信号都受时间窗口限制）
    
    返回:
    (bool, str, dict): (是否允许交易, 原因描述, 详细信息)
    """
    try:
        # 首先检查市场是否开放
        market_open, market_msg, market_info = is_market_open(current_time)
        if not market_open:
            return False, market_msg, {
                'market_open': False,
                'market_info': market_info,
                'signal_level': signal_level
            }
        
        # 市场开放，检查信号等级的时间窗口
        if not strict_mode:
            # 非严格模式：完美和优秀信号全天候执行
            if signal_level in ['perfect', 'excellent']:
                return True, f"?? {signal_level.upper()}信号全天候执行", {
                    'market_open': True,
                    'signal_level': signal_level,
                    'full_day_trading': True,
                    'market_info': market_info
                }
        
        # 检查具体的时间窗口
        in_window, window_msg = is_in_trading_window(current_time, signal_level)
        
        return in_window, window_msg, {
            'market_open': True,
            'in_trading_window': in_window,
            'signal_level': signal_level,
            'market_info': market_info,
            'strict_mode': strict_mode
        }
        
    except Exception as e:
        logger.error(f"智能交易时间控制失败: {e}")
        return False, f"? 交易时间控制异常: {e}", {'error': str(e)}

def can_retry_after_failure(last_attempt_time, current_time, retry_interval_minutes=3):
    """
    检查买入失败后是否可以重试
    
    参数:
    last_attempt_time: 上次尝试时间 (格式: "HH:MM")
    current_time: 当前时间 (格式: "HH:MM")
    retry_interval_minutes: 重试间隔分钟数，默认3分钟
    
    返回:
    bool: True表示可以重试，False表示需要继续等待
    """
    try:
        if not last_attempt_time or not current_time:
            return True  # 如果时间信息不完整，允许重试

        # 归一化到 datetime 对象（仅日期无关，使用今天日期）
        def to_dt_hm(t):
            if isinstance(t, datetime):
                return t
            if isinstance(t, dt_time):
                return datetime.now().replace(hour=t.hour, minute=t.minute, second=0, microsecond=0)
            if isinstance(t, str):
                # 接受 "HH:MM" 或 "HH:MM:SS" 格式
                parts = t.split(":")
                hh = int(parts[0])
                mm = int(parts[1]) if len(parts) > 1 else 0
                ss = int(parts[2]) if len(parts) > 2 else 0
                return datetime.now().replace(hour=hh, minute=mm, second=ss, microsecond=0)
            # 其他类型，直接允许重试
            return datetime.now()

        last_time = to_dt_hm(last_attempt_time)
        curr_time = to_dt_hm(current_time)

        # 计算时间差
        time_diff = curr_time - last_time
        
        # 处理跨日情况（如果当前时间小于上次时间，说明跨日了）
        if time_diff.total_seconds() < 0:
            time_diff += timedelta(days=1)
        
        # 检查是否超过重试间隔
        return time_diff.total_seconds() >= retry_interval_minutes * 60
        
    except Exception as e:
        logger.warning(f"重试时间检查失败: {e}，默认允许重试")
        return True  # 出错时默认允许重试

