DETECTED_SIGNAL_THRESHOLD = 0.8    # 探测信号：均线偏离0.8%-1.5%
PULLBACK_SIGNAL_THRESHOLD = 0.0      # 回调信号：均线偏离<0.8%

# 分级时间窗口配置
