_next_day_sell_lock = threading.RLock()

def enqueue_next_day_sell(context, stock_code: str, intended_volume: int, reason: str = 'T+1不可卖'):
    try:
        code = format_stock_code(stock_code)
        tomorrow = (datetime.now() + timedelta(days=1)).strftime('%Y%m%d')
        with _next_day_sell_lock:
            next_day_sell_queue[code] = {
                'date': tomorrow,
                'reason': reason,
                'intended_volume': int(max(0, int(intended_volume) if intended_volume else 0)),
                'enqueue_time': time_module.time()
            }
        logger.info(f"? {code} 已加入次日待卖队列: date={tomorrow}, intended_volume={intended_volume}, reason={reason}")
    except Exception as e:
        logger.warning(f"enqueue_next_day_sell 失败: {stock_code} - {e}")

def process_next_day_sell_queue(context):
    """扫描并报告次日待卖队列的可执行项（仅日志与返回，不自动下单）。
    返回: list[dict] 可执行候选，元素包含 code, sellable, intended_volume, reason
    """
    candidates = []
    try:
        today = datetime.now().strftime('%Y%m%d')
        positions = None
        try:
            if 'get_trade_detail_data' in globals():
                positions = get_trade_detail_data(context.accID, context.accIDType, 'POSITION')
        except Exception:
            positions = None
        pos_map = {}
        if isinstance(positions, (list, tuple)):
            for p in positions:
                try:
                    pc = p.get('m_strInstrumentID') or p.get('InstrumentID') or p.get('stock_code') or p.get('code') or ''
                    if pc:
                        pos_map[str(pc).upper()] = {
                            'sellable': int(p.get('m_nEnableAmount') or p.get('m_nSellable') or p.get('enableAmount') or p.get('sellable') or p.get('available_amount') or 0),
                            'total': int(p.get('m_nAmount') or p.get('m_nVolume') or p.get('volume') or p.get('position') or 0)
                        }
                except Exception:
                    continue
        with _next_day_sell_lock:
            for code, info in list(next_day_sell_queue.items()):
                if info.get('date') and info['date'] <= today:
                    s = pos_map.get(str(code).upper(), {})
                    sellable = int(s.get('sellable') or 0)
                    if sellable > 0:
                        logger.info(f"? 次日待卖检查: {code} sellable={sellable} → 可执行")
                        candidates.append({
                            'code': code,
                            'sellable': sellable,
                            'total': int(s.get('total') or 0),
                            'intended_volume': info.get('intended_volume', 0),
                            'reason': info.get('reason', '')
                        })
                    else:
                        logger.info(f"? 次日待卖检查: {code} 仍不可卖(sellable=0)，保留队列")
    except Exception as e:
        logger.warning(f"process_next_day_sell_queue 异常: {e}")
    return candidates

def _get_latest_price_safe(context, stock_code: str) -> float:
    try:
        code = format_stock_code(stock_code)
        if 'get_full_tick' in globals():
            tk = get_full_tick(code)
            if isinstance(tk, dict):
                for k in ('last', 'LastPrice', 'm_dLastPrice', 'price', 'new'):  # 兼容多字段
                    v = tk.get(k)
                    if v is not None:
                        return float(v)
        return 0.0
    except Exception:
        return 0.0

def auto_exec_next_day_sell(context):
    try:
        if not AUTO_EXEC_NEXTDAY_SELL:
            return 0
        cands = process_next_day_sell_queue(context)
        executed = 0
        for it in cands:
            code = it.get('code')
            sellable = int(it.get('sellable') or 0)
            total = int(it.get('total') or 0)
            intended = int(it.get('intended_volume') or 0)
            reason = str(it.get('reason') or '')
            if sellable <= 0:
                continue
            price_cur = _get_latest_price_safe(context, code)
            cost = get_reliable_cost_price(context, code)
            if price_cur <= 0 or cost <= 0:
                continue
            pl = (price_cur - cost) / cost
            action = 'HOLD'
            sell_ratio = 0.0
            # 该队列目前仅用于“T+1导致的止损未能当日执行”。为避免次日无论盈亏都卖，
            # 若价格已恢复到止损阈值之上，则取消队列，交由正常止损/止盈逻辑管理。
            if ('止损触发' in reason) or ('STOP' in reason.upper()):
                if pl <= float(NEXTDAY_STOP_LOSS_THRESHOLD):
                    action = 'SELL'
                    sell_ratio = 1.0
                else:
                    logger.info(f"? 次日待卖: {code} 已恢复(PL={pl:.2%})，取消队列，不执行卖出")
                    try:
                        with _next_day_sell_lock:
                            if code in next_day_sell_queue:
                                del next_day_sell_queue[code]
                    except Exception:
                        pass
                    continue
            else:
                # 兜底：非止损原因的队列（未来可能扩展）。保持原逻辑：止盈(移动止盈)或止损。
                try:
                    cfg = get_dynamic_enhancement_config(context)
                    cfg = compute_effective_sell_params(context, code, cfg)
                    PER_STOCK_SHAPE_STATE['sell_hints'][f"{code}__last_eff_cfg"] = {'ts': _now_ts()}
                except Exception:
                    pass
                opened_ts = 0
                try:
                    opened_ts = int(stock_positions_info.get(code, {}).get('opened_at_ts', 0) or 0)
                except Exception:
                    opened_ts = 0
                trailing_params = {
                    'trailing_percent': 0.06,
                    'min_profit': 0.08,
                    'opened_at_ts': opened_ts,
                    'min_holding_days': 0,
                    'skip_trailing_confirm': True,
                    'skip_near_limitup_freeze': True,
                    'skip_markup_trailing': True,
                }
                act, ratio, _detail = trailing_profit_check(code, pl, cost, price_cur, max(total, sellable), trailing_params, price_cur)
                if act == 'SELL' and ratio > 0:
                    action = 'SELL'
                    sell_ratio = max(0.0, min(1.0, float(ratio)))
                if action == 'HOLD' and pl <= float(NEXTDAY_STOP_LOSS_THRESHOLD):
                    action = 'SELL'
                    sell_ratio = 1.0
            if action != 'SELL' or sell_ratio <= 0:
                logger.info(f"? 次日待卖: {code} 未达止盈/止损条件，暂缓 (PL={pl:.2%})")
                continue
            lot = get_round_lot_size(code, context)
            vol_by_ratio = int((total if total > 0 else sellable) * sell_ratio)
            vol0 = max(intended, vol_by_ratio)
            vol = max(lot, (vol0 // lot) * lot)
            vol = min(vol, sellable)
            if vol <= 0:
                logger.info(f"? 次日待卖: {code} 计算可卖量为0，跳过")
                continue
            logger.info(f"? 次日待卖自动执行: {code} vol={vol}, sellable={sellable}, total={total}, ratio={sell_ratio:.0%}, PL={pl:.2%}")
            try:
                # 修复参数顺序：按照 real_trade_order(context, stock_code, price, volume, remark, action=...) 正确传参
                # 使用安全封装，避免异常影响生命周期
                ret = safe_real_trade_order(
                    context,
                    code,
                    price_cur,
                    vol,
                    'NEXTDAY-QUEUE',
                    action='sell'
                )
                if isinstance(ret, dict) and ret.get('success'):
                    executed += 1
                    with _next_day_sell_lock:
                        if code in next_day_sell_queue:
                            del next_day_sell_queue[code]
                else:
                    logger.warning(f"?? 次日待卖自动执行失败: {code} - {ret}")
            except Exception as e:
                logger.warning(f"?? 次日待卖自动执行异常: {code} - {e}")
        return executed
    except Exception as e:
        logger.warning(f"auto_exec_next_day_sell 异常: {e}")
        return 0

def check_order_deduplication(stock_code, order_type, lock_duration=None):
    """
    检查订单去重锁定，防止短时间内重复下单
    
    参数:
    stock_code: 股票代码
    order_type: 订单类型 ('买入' 或 '卖出')
    lock_duration: 锁定时长（秒），默认按方向选择（买入10s / 卖出12s）
    
    返回:
    bool: True=可以下单, False=被锁定不能下单
    """
    global order_deduplication_locks
    
    try:
        current_time = time_module.time()
        # 按方向选择默认冷却时长
        try:
            side = str(order_type)
        except Exception:
            side = ''
        if lock_duration is None:
            if '买' in side:
                lock_duration = 10
            elif '卖' in side:
                lock_duration = 12
            else:
                lock_duration = 12
        
        # 检查是否存在锁定记录
        if stock_code in order_deduplication_locks:
            lock_info = order_deduplication_locks[stock_code]
            last_order_time = lock_info.get('last_order_time', 0)
            last_order_type = lock_info.get('order_type', '')
            
            # 计算时间差
            time_diff = current_time - last_order_time
            
            # 如果是相同类型的订单且在锁定时间内，拒绝下单
            if last_order_type == order_type and time_diff < lock_duration:
                remaining_time = lock_duration - time_diff
                logger.warning(f"?? {stock_code} 订单去重保护: {order_type}订单被锁定，剩余{remaining_time:.1f}秒")
                logger.warning(f"   上次{order_type}时间: {time_module.strftime('%H:%M:%S', time_module.localtime(last_order_time))}")
                return False
        
        # 更新锁定记录
        order_deduplication_locks[stock_code] = {
            'last_order_time': current_time,
            'order_type': order_type,
            'lock_duration': lock_duration
        }
        
        logger.info(f"?? {stock_code} 订单去重检查通过，允许{order_type}（冷却{int(lock_duration)}s）")
        return True
        
    except Exception as e:
        logger.error(f"订单去重检查失败: {e}")
        # 出错时允许下单，避免影响正常交易
        return True

def check_global_sell_control(stock_code, reason):
    """
    全局卖出控制检查 - 防止同一调仓周期内重复卖出
    
    参数:
    stock_code: 股票代码
    reason: 卖出原因
    
    返回:
    dict: {'allowed': bool, 'reason': str, 'existing_order': dict}
    """
    global daily_sell_order_status
    
    try:
        current_time = time_module.time()
        today_str = datetime.now().strftime("%Y-%m-%d")
        existing_status = ''
        existing_reason = ''
        submit_time = 0
        
        # 检查是否已有当日卖出订单
        if stock_code in daily_sell_order_status:
            existing_order = daily_sell_order_status[stock_code]
            existing_status = existing_order.get('status', '')
            existing_reason = existing_order.get('reason', '')
            submit_time = existing_order.get('submit_time', 0)
            # 若存在无委托号的pending/submitted且超时，进行自愈清理，避免长时间误锁
            try:
                _oid = existing_order.get('order_id')
                _no_oid = (_oid is None) or (str(_oid).strip() == '') or (str(_oid).strip().lower() == 'none')
            except Exception:
                _no_oid = True
            try:
                _elapsed = (current_time - float(submit_time or 0))
            except Exception:
                _elapsed = 0
            if existing_status in ['pending', 'submitted'] and _no_oid and _elapsed > 120:
                try:
                    daily_sell_order_status[stock_code]['status'] = 'failed'
                    logger.warning(f"?? {stock_code} 全局卖出控制: 发现无委托号的pending/submitted已超时({_elapsed:.0f}s)，自动降级为failed并解除抑制")
                except Exception:
                    pass
            
            # 如果已提交且未完成，拒绝重复提交
            if existing_status in ['pending', 'submitted']:
                time_diff = current_time - submit_time
                logger.warning(f"?? {stock_code} 全局卖出控制: 已有{existing_status}状态的卖出订单")
                logger.warning(f"   现有订单原因: {existing_reason}")
                logger.warning(f"   现有订单提交时间: {time_module.strftime('%H:%M:%S', time_module.localtime(submit_time))}")
                logger.warning(f"   当前尝试原因: {reason}")
                logger.warning(f"   时间间隔: {time_diff:.1f}秒")
                
                return {
                    'allowed': False,
                    'reason': f'已有{existing_status}状态订单: {existing_reason}',
                    'existing_order': existing_order
                }

        # 按动作(reason)维度的冷却抑制（读取可配置映射）
        ACTION_COOLDOWN_MAP = get_sell_action_cooldowns()
        # 规范化动作键
        def _normalize_reason(s):
            try:
                s = str(s) if s is not None else ''
            except Exception:
                s = ''
            s_low = s.lower()
            if 'l1' in s_low:
                return 'take_profit_L1'
            if 'l2' in s_low:
                return 'take_profit_L2'
            if 'l3' in s_low:
                return 'take_profit_L3'
            if 'trail' in s_low or '移动' in s:
                return 'trailing'
            if '损' in s or 'stop_loss' in s_low:
                return 'stop_loss'
            # 默认不抑制
            return s

        norm_reason = _normalize_reason(reason)
        cooldown_seconds = ACTION_COOLDOWN_MAP.get(norm_reason)
        if cooldown_seconds:
            # 全局注册表：按(股票, 动作)记录最近一次允许尝试时间
            global sell_action_cooldowns
            if 'sell_action_cooldowns' not in globals():
                sell_action_cooldowns = {}
            key = (stock_code, norm_reason)
            last_ts = sell_action_cooldowns.get(key, 0)
            if last_ts and (current_time - last_ts) < cooldown_seconds:
                remaining = cooldown_seconds - (current_time - last_ts)
                logger.debug(f"? 动作冷却抑制: {stock_code} {norm_reason} 距上次{current_time-last_ts:.0f}s/<={cooldown_seconds}s，剩余{remaining:.0f}s")
                return {
                    'allowed': False,
                    'reason': f'动作冷却期内({norm_reason}) 剩余{remaining:.0f}s',
                    'existing_order': None
                }
            # 通过检查则更新动作时间戳
            sell_action_cooldowns[key] = current_time

        # 同一调仓周期内(5分钟)不允许重复卖出
        if existing_status == 'completed':
            td = (current_time - submit_time) if submit_time else 999999
            if td < 300:  # 5分钟 = 300秒
                logger.warning(f"?? {stock_code} 全局卖出控制: 同一调仓周期内已完成卖出")
                logger.warning(f"   已完成订单原因: {existing_reason}")
                logger.warning(f"   完成时间: {time_module.strftime('%H:%M:%S', time_module.localtime(submit_time))}")
                logger.warning(f"   当前尝试原因: {reason}")
                
                return {
                    'allowed': False,
                    'reason': f'同一调仓周期内已完成卖出({existing_reason})',
                    'existing_order': existing_order
                }
        
        # 记录新的卖出订单状态
        daily_sell_order_status[stock_code] = {
            'status': 'pending',
            'submit_time': current_time,
            'reason': reason,
            'order_id': None,
            'date': today_str
        }
        
        logger.info(f"? {stock_code} 全局卖出控制检查通过，允许卖出({reason})")
        return {
            'allowed': True,
            'reason': '检查通过',
            'existing_order': None
        }
        
    except Exception as e:
        logger.error(f"全局卖出控制检查失败: {e}")
        # 出错时允许卖出，避免影响正常交易
        return {
            'allowed': True,
            'reason': '检查异常，允许执行',
            'existing_order': None
        }

def update_sell_order_status(stock_code, status, order_id=None):
    """
    更新卖出订单状态
    
    参数:
    stock_code: 股票代码
    status: 订单状态 ('submitted', 'completed', 'failed')
    order_id: 委托号(可选)
    """
    global daily_sell_order_status
    
    try:
        if stock_code in daily_sell_order_status:
            daily_sell_order_status[stock_code]['status'] = status
            if order_id:
                daily_sell_order_status[stock_code]['order_id'] = order_id
            
            logger.info(f"?? {stock_code} 卖出订单状态更新: {status}")
            if order_id:
                logger.info(f"   委托号: {order_id}")
        
    except Exception as e:
        logger.error(f"更新卖出订单状态失败: {e}")

def clear_daily_sell_status():
    """
    清理过期的当日卖出状态记录
    """
    global daily_sell_order_status
    
    try:
        current_time = time_module.time()
        today_str = datetime.now().strftime("%Y-%m-%d")
        
        # 清理非当日的记录
        expired_stocks = []
        for stock_code, order_info in daily_sell_order_status.items():
            order_date = order_info.get('date', '')
            if order_date != today_str:
                expired_stocks.append(stock_code)
        
        for stock_code in expired_stocks:
            del daily_sell_order_status[stock_code]
        
        if expired_stocks:
            logger.info(f"?? 清理过期卖出状态记录: {len(expired_stocks)}条")
        
    except Exception as e:
        logger.error(f"清理当日卖出状态失败: {e}")

