class DynamicProfitCalculator:
    """
    动态止盈参数计算器
    根据股票特征和市场环境动态计算个性化止盈参数
    """
    
    def __init__(self):
        self.stock_categories = {
            'large_cap': {'min_market_cap': 500, 'volatility_range': (0.15, 0.25)},
            'mid_cap': {'min_market_cap': 100, 'volatility_range': (0.20, 0.35)},
            'small_cap': {'min_market_cap': 0, 'volatility_range': (0.25, 0.50)}
        }
        
        # 基础参数配置
        self.base_params = {
            'bull': {'level1': 0.06, 'level2': 0.10, 'level3': 0.18},
            'bear': {'level1': 0.03, 'level2': 0.05, 'level3': 0.08},
            'sideways': {'level1': 0.05, 'level2': 0.08, 'level3': 0.15}
        }
        
        logger.info("? 动态止盈计算器已初始化")
    
    def categorize_stock(self, stock_code: str) -> str:
        """根据股票代码简单分类"""
        try:
            if stock_code.startswith(('000', '002', '300')):
                return 'small_cap'  # 深市中小板、创业板
            elif stock_code.startswith('600'):
                return 'large_cap'  # 沪市主板大盘股
            else:
                return 'mid_cap'    # 其他
        except Exception:
            return 'mid_cap'
    
    def calculate_risk_score(self, stock_code: str, market_env: str = 'sideways') -> float:
        """计算股票风险评分"""
        try:
            category = self.categorize_stock(stock_code)
            
            # 基础风险评分
            base_risk = {
                'large_cap': 0.3,
                'mid_cap': 0.5,
                'small_cap': 0.7
            }.get(category, 0.5)
            
            # 市场环境调整
            market_adjustment = {
                'bull': -0.1,    # 牛市降低风险
                'bear': 0.2,     # 熊市增加风险
                'sideways': 0.0  # 震荡市不调整
            }.get(market_env, 0.0)
            
            risk_score = max(0.1, min(0.9, base_risk + market_adjustment))
            return risk_score
            
        except Exception as e:
            logger.warning(f"?? {stock_code} 风险评分计算失败: {e}")
            return 0.5
    
    def calculate_dynamic_params(self, stock_code: str, market_env: str = 'sideways') -> Dict:
        """计算动态止盈参数"""
        try:
            # 获取基础参数
            base = self.base_params.get(market_env, self.base_params['sideways'])
            
            # 计算风险调整
            risk_score = self.calculate_risk_score(stock_code, market_env)
            category = self.categorize_stock(stock_code)
            
            # 风险调整系数
            risk_multiplier = 1.0 + (risk_score - 0.5) * 0.4
            
            # 股票类型调整
            category_multiplier = {
                'large_cap': 0.9,   # 大盘股相对保守
                'mid_cap': 1.0,     # 中盘股标准
                'small_cap': 1.2    # 小盘股相对激进
            }.get(category, 1.0)
            
            # 计算最终参数
            level1 = base['level1'] * risk_multiplier * category_multiplier
            level2 = base['level2'] * risk_multiplier * category_multiplier
            level3 = base['level3'] * risk_multiplier * category_multiplier
            
            # 参数边界控制
            level1 = max(0.02, min(0.10, level1))
            level2 = max(0.04, min(0.15, level2))
            level3 = max(0.08, min(0.25, level3))
            
            return {
                'level1': level1,
                'level2': level2,
                'level3': level3,
                'risk_score': risk_score,
                'category': category,
                'market_env': market_env,
                'confidence': 0.8,
                'algorithm': 'dynamic_calculator',
                'last_update': datetime.now().strftime('%Y%m%d %H:%M:%S')
            }
            
        except Exception as e:
            logger.error(f"? {stock_code} 动态参数计算失败: {e}")
            return self._get_fallback_params(market_env)
    
    def batch_calculate_params(self, stock_codes: List[str], market_env: str = 'sideways') -> Dict:
        """批量计算多只股票的参数"""
        results = {}
        for stock_code in stock_codes:
            results[stock_code] = self.calculate_dynamic_params(stock_code, market_env)
        return results
    
    def _get_fallback_params(self, market_env: str = 'sideways') -> Dict:
        """获取兜底参数"""
        base = self.base_params.get(market_env, self.base_params['sideways'])
        return {
            'level1': base['level1'],
            'level2': base['level2'],
            'level3': base['level3'],
            'risk_score': 0.5,
            'category': 'unknown',
            'market_env': market_env,
            'confidence': 0.3,
            'algorithm': 'fallback',
            'last_update': datetime.now().strftime('%Y%m%d %H:%M:%S')
        }

