# ===== 全内存个人化档案存储（轻量封装） =====
class InMemoryPerStockProfileStore:
    """
    会话内的个股档案存储（不落盘）。
    用于存放每只股票的个性化参数与状态（便于后续统一管理）。
    注意：当前实现以现有的 stock_positions_info 为主数据源，
    该 Store 仅作为后续扩展的轻量封装，不改变现有读写路径。
    """
    def __init__(self):
        self._data = {}

    def get(self, stock_code: str) -> dict:
        return self._data.get(stock_code, {})

    def set(self, stock_code: str, profile: dict) -> None:
        if isinstance(profile, dict):
            self._data[stock_code] = profile

    def ensure(self, stock_code: str, defaults: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        if stock_code not in self._data:
            self._data[stock_code] = dict(defaults or {})
        return self._data[stock_code]

    def update_fields(self, stock_code: str, **kwargs) -> None:
        p = self._data.setdefault(stock_code, {})
        p.update({k: v for k, v in kwargs.items()})


# 全局实例（完全内存，不与磁盘交互）
PER_STOCK_STORE = InMemoryPerStockProfileStore()


# ===== 混合止盈状态机（先分级→再移动） - 轻量脚手架 =====
class HybridTakeProfitStateMachine:
    """
    轻量状态机脚手架：不改变现有止盈/止损路径，只提供统一的辅助方法。
    后续可逐步将分级推进与移动止盈激活逻辑迁移到此类中。
    """
    TP_NONE = 0
    TP_1 = 1
    TP_2 = 2
    TP_3 = 3

    @staticmethod
    def ensure_init(stock_code: str, current_price: float, volume: int) -> None:
        try:
            # 与 stock_positions_info 对齐的默认字段
            defaults = {
                'tp_stage': 0,
                'activated_trailing': False,
                'highest_price': float(current_price) if current_price else 0.0,
                'volume': int(volume) if volume else 0,
            }
            PER_STOCK_STORE.ensure(stock_code, defaults)
        except Exception:
            # 保守忽略，避免影响主流程
            pass

    @staticmethod
    def update_highest(stock_code: str, price: float) -> None:
        try:
            p = PER_STOCK_STORE.get(stock_code)
            hp = float(p.get('highest_price', 0.0))
            if price and price > hp:
                PER_STOCK_STORE.update_fields(stock_code, highest_price=float(price))
        except Exception:
            pass

    @staticmethod
    def maybe_activate_trailing(stock_code: str, profit_ratio: float, current_price: float, X: float, Y: float) -> bool:
        """若未激活且满足收益≥X与从最高价回撤≥Y，则标记为已激活。"""
        try:
            p = PER_STOCK_STORE.get(stock_code)
            if not p or p.get('activated_trailing', False):
                return bool(p.get('activated_trailing', False))

            hp = float(p.get('highest_price', current_price or 0.0))
            pullback = (hp - current_price) / hp if hp > 0 else 0.0
            if profit_ratio is not None and profit_ratio >= X and pullback >= Y:
                PER_STOCK_STORE.update_fields(stock_code, activated_trailing=True)
                logger.info(f"?? {stock_code} [StateMachine] 激活移动止盈: X={X:.1%}, Y={Y:.1%}, hp={hp:.2f}, cur={current_price:.2f}, 回撤={pullback:.2%}")
                return True
            return False
        except Exception:
            return False


def compute_adaptive_trailing_thresholds(stock_code: str, market_env: str) -> Tuple[float, float]:
    """
    计算方案2所需的自适应阈值 (X=激活最小收益, Y=新高后回撤阈值)。
    与移动止盈构造逻辑保持一致，供日志汇总和策略选择共用。
    """
    try:
        try:
            category = dynamic_profit_calculator.categorize_stock(stock_code)
        except Exception:
            category = 'mid_cap'

        if category == 'large_cap':
            X, Y = 0.11, 0.03
        elif category == 'small_cap':
            X, Y = 0.14, 0.045
        else:
            X, Y = 0.12, 0.035

        if market_env == 'bull':
            X = max(0.06, X - 0.01)
            Y = min(0.08, Y + 0.005)
        elif market_env == 'sideways':
            # 震荡市：更偏向“早保护、紧回撤”，用于稳健落袋
            try:
                if category == 'large_cap':
                    X = max(0.05, X - 0.02)
                    Y = max(0.02, Y - 0.005)
                elif category == 'small_cap':
                    X = max(0.08, X - 0.01)
                    Y = max(0.025, Y - 0.005)
                else:
                    X = max(0.06, X - 0.02)
                    Y = max(0.02, Y - 0.005)
            except Exception:
                X = max(0.06, X - 0.02)
                Y = max(0.02, Y - 0.005)
        elif _is_bearish(market_env):
            X = min(0.20, X + 0.01)
            Y = max(0.02, Y - 0.005)
        # 按生命周期阶段做小幅偏置
        try:
            st = stock_positions_info.get(stock_code, {})
            phase = st.get('lifecycle_phase', 'unknown')
            # 拉升/吸筹：进入保护更晚(X↑)，但容忍更大回撤(Y↑)
            if phase in ('markup', 'accumulation'):
                X = min(0.25, X + 0.01)
                Y = min(0.10, Y + 0.005)
            # 洗盘：更早进入保护(X↓)，且容忍更大回撤(Y↑)
            elif phase == 'shakeout':
                X = max(0.05, X - 0.01)
                Y = min(0.10, Y + 0.005)
            # 出货：更早进入保护(X↓)，收紧回撤(Y↓)
            elif phase == 'distribution':
                X = max(0.05, X - 0.02)
                Y = max(0.02, Y - 0.005)
        except Exception:
            pass
        return float(X), float(Y)
    except Exception:
        return 0.12, 0.035


def is_distribution_peak(ContextInfo,
                         stock_code: str,
                         current_price: float,
                         buy_price: float,
                         trade_date: str,
                         config: Optional[Dict] = None) -> Dict[str, Any]:
    """
    轻量级“出货峰”检测：顶部套牢盘≈两倍顶部获利盘。
    估算方法：
    - 取近window_days日的最高价max_high，定义顶部带[top_band*max_high, max_high]
    - 在最近N日(日线)中，收盘价位于顶部带的交易日：
        close>=buy_price 视为TopProfit(顶部浮盈)，close<buy_price视为TopOverhang(顶部套牢)
      使用当日成交量作为权重估计强度
    - ratio = TopOverhang / max(TopProfit, eps)
    - 结合当日位置与量能做弱化确认
    返回: {'flag': bool, 'ratio': float, 'reason': str, 'intensity': 'weak'|'medium'|'strong'}
    """
    try:
        cfg = config or {}
        window_days = int(cfg.get('window_days', 5) or 5)
        top_band = float(cfg.get('top_band', 0.95) or 0.95)
        ratio_primary = float(cfg.get('ratio_primary', 2.0) or 2.0)
        ratio_strong = float(cfg.get('ratio_strong', 3.0) or 3.0)
        pos_cut = float(cfg.get('pos_cut', 0.6) or 0.6)
        vol_spike = float(cfg.get('vol_spike', 2.0) or 2.0)

        code = format_stock_code(stock_code)
        # 获取近20日日线数据
        md = get_market_data_ex([code], period='1d', count=20, fields=['high', 'low', 'close', 'volume'])  # pyright: ignore[reportUndefinedVariable]
        if not isinstance(md, dict) or code not in md or md[code].empty:
            return {'flag': False, 'ratio': 0.0, 'reason': 'no_daily_data', 'intensity': 'weak'}

        df = md[code]
        try:
            # 近window_days日的最高价
            recent = df.tail(max(1, window_days))
            max_high = float(recent['high'].max()) if 'high' in recent else None
        except Exception:
            max_high = None
        if not max_high or max_high <= 0:
            return {'flag': False, 'ratio': 0.0, 'reason': 'invalid_max_high', 'intensity': 'weak'}
        band_low = float(max_high) * float(top_band)

        # 顶部带内的TopOverhang/TopProfit估算（按成交量加权）
        top_profit = 0.0
        top_overhang = 0.0
        try:
            sub = df[df['high'] >= band_low]
            for _, row in sub.iterrows():
                c = float(row.get('close', 0) or 0)
                v = float(row.get('volume', 0) or 0)
                if c >= band_low:
                    if buy_price and buy_price > 0 and c >= float(buy_price):
                        top_profit += v
                    else:
                        top_overhang += v
        except Exception:
            pass
        eps = 1e-6
        ratio = float(top_overhang) / float(max(top_profit, eps)) if (top_profit or top_overhang) else 0.0

        # 当日分时位置与量能
        price_pos_ok = False
        vol_spike_ok = False
        try:
            tick = ContextInfo.get_full_tick([code])
            if isinstance(tick, dict) and code in tick:
                t = tick[code]
                day_high = float(t.get('high', 0) or 0)
                day_low = float(t.get('low', 0) or 0)
                if day_high > day_low and current_price and current_price > 0:
                    price_pos = (current_price - day_low) / (day_high - day_low)
                    price_pos_ok = (price_pos <= pos_cut)
        except Exception:
            price_pos_ok = False
        try:
            # 今日量与近20日均量对比
            if not df.empty and 'volume' in df:
                today_vol = float(df['volume'].iloc[-1])
                mean_vol = float(df['volume'].iloc[:-1].mean()) if len(df) > 1 else 0.0
                if mean_vol > 0:
                    vol_ratio = today_vol / mean_vol
                    vol_spike_ok = (vol_ratio >= vol_spike)
        except Exception:
            vol_spike_ok = False

        intensity = 'weak'
        if ratio >= ratio_strong:
            intensity = 'strong'
        elif ratio >= ratio_primary:
            intensity = 'medium'

        # 触发条件：ratio达标 且（分时位置回落 或 量能尖峰）
        cond = (ratio >= ratio_primary) and (price_pos_ok or vol_spike_ok)
        reason = f"ratio={ratio:.2f} (overhang/profit), price_pos_ok={price_pos_ok}, vol_spike_ok={vol_spike_ok}, band_low={band_low:.2f}, max_high={max_high:.2f}"
        return {'flag': bool(cond), 'ratio': float(ratio), 'reason': reason, 'intensity': intensity}
    except Exception as e:
        logger.debug(f"distribution_peak_check异常 {stock_code}: {e}")
        return {'flag': False, 'ratio': 0.0, 'reason': f'exception: {e}', 'intensity': 'weak'}


def _get_close_series(ContextInfo, stock_code: str, count: int = 60) -> List[float]:
    try:
        code = format_stock_code(stock_code)
        md = get_market_data_ex([code], period='1d', count=count, fields=['close'])  # pyright: ignore[reportUndefinedVariable]
        if isinstance(md, dict) and code in md and (not md[code].empty):
            df = md[code]
            if 'close' in df:
                return [float(x) for x in list(df['close'].values)]
    except Exception:
        pass
    return []

