# ===== 个性化参数引擎（轻量版：仅日志展示，不改变交易决策） =====
def extract_stock_features(stock_code: str,
                           ContextInfo,
                           buy_price: float,
                           current_price: float,
                           volume: int,
                           profit_loss_ratio: float,
                           market_env: str) -> dict:
    """
    轻量特征提取器：全内存、尽量使用已有API，失败即回退。
    返回用于个性化计算的最小必要特征集。
    """
    features = {
        'category': None,
        'atr_pct': None,
        'avg_turnover': None,
        'pl_ratio': profit_loss_ratio,
        'volume': volume,
        'market_env': market_env,
    }
    try:
        features['category'] = dynamic_profit_calculator.categorize_stock(stock_code)
    except Exception:
        features['category'] = 'mid_cap'

    # 尝试提取近20日的收盘/成交量，用于估算波动（ATR近似）与流动性
    try:
        df = get_market_data_ex([stock_code], ['close', 'volume'], '1d', 20)  # pyright: ignore[reportUndefinedVariable]
        if isinstance(df, dict) and stock_code in df and not df[stock_code].empty:
            hist = df[stock_code]
            closes = hist['close'].dropna().values.tolist() if 'close' in hist else []
            vols = hist['volume'].dropna().values.tolist() if 'volume' in hist else []
            if closes and len(closes) >= 2:
                diffs = [abs(closes[i] - closes[i-1]) for i in range(1, len(closes))]
                avg_diff = sum(diffs) / max(1, len(diffs))
                base = closes[-2] if closes[-2] else (buy_price or current_price)
                if base > 0:
                    features['atr_pct'] = min(0.15, max(0.002, avg_diff / base))
            if vols:
                features['avg_turnover'] = float(sum(vols)) / max(1, len(vols))
    except Exception:
        # 回退：使用当下价格粗略估计波动
        if buy_price and current_price and buy_price > 0:
            est = abs(current_price - buy_price) / buy_price
            features['atr_pct'] = min(0.10, max(0.002, est))
        else:
            features['atr_pct'] = 0.02
        features['avg_turnover'] = None

    return features


class PersonalizedProfitParamsCalculator:
    """
    轻量个性化计算器：根据特征和市况，输出推荐的止盈/止损参数（仅日志展示）。
    不改变现有实盘执行的阈值与行为。
    """
    @staticmethod
    def calculate(features: dict, market_env: str) -> dict:
        try:
            category = (features.get('category') or 'mid_cap')
            atr = features.get('atr_pct') or 0.02
            pl = features.get('pl_ratio') or 0.0

            # 分级止盈建议（基于ATR与品种）
            if category == 'large_cap':
                tp_levels = [max(0.06, 3*atr), max(0.10, 5*atr), max(0.18, 8*atr)]
                tp_portions = [0.5, 0.5, 1.0]
                trailing_distance = min(0.05, max(0.025, 2.0*atr))
            elif category == 'small_cap':
                tp_levels = [max(0.08, 3.5*atr), max(0.14, 6*atr), max(0.22, 9*atr)]
                tp_portions = [0.4, 0.6, 1.0]
                trailing_distance = min(0.07, max(0.035, 2.5*atr))
            else:
                tp_levels = [max(0.07, 3*atr), max(0.12, 5.5*atr), max(0.20, 8.5*atr)]
                tp_portions = [0.5, 0.5, 1.0]
                trailing_distance = min(0.06, max(0.03, 2.2*atr))

            # === 主升浪风格微调：在主升阶段适度抬高L1/L2阈值，避免过早分级止盈卖飞 ===
            try:
                phase = None
                # 从全局持仓镜像中读取生命周期阶段（若有）
                # 仅在明确定义为主升阶段时才放宽止盈目标
                for _code, st in (stock_positions_info or {}).items():
                    # features层面无法直接区分票，这里仅在存在生命周期信息时使用其统计特征
                    if isinstance(st, dict) and 'lifecycle_phase' in st:
                        phase = st.get('lifecycle_phase')
                        break
                is_main_rise_phase = phase in ('pre_markup', 'markup')
                if is_main_rise_phase and market_env in ('bull', 'sideways'):
                    l1, l2, l3 = tp_levels
                    # L1/L2 适度抬高 2/4 个点，但不超过30%
                    l1 = min(0.30, l1 + 0.02)
                    l2 = min(0.35, l2 + 0.04)
                    tp_levels = [l1, l2, l3]
            except Exception:
                pass

            # 市场环境对止损的影响（仅建议）
            base_stop_loss = 0.05
            time_stop_days = 5
            vol_stop_mult = 1.5
            drawdown_stop = 0.06
            if market_env == 'bull':
                base_stop_loss = 0.045
                trailing_distance = min(0.08, trailing_distance + 0.005)
            elif _is_bearish(market_env):
                base_stop_loss = 0.035
                trailing_distance = max(0.02, trailing_distance - 0.005)

            notes = f"cat={category}, atr={atr:.3f}, pl={pl:.2%}, env={market_env}"
            return {
                'tp_levels': tp_levels,
                'tp_portions': tp_portions,
                'trailing_distance': trailing_distance,
                'base_stop_loss': base_stop_loss,
                'time_stop_days': time_stop_days,
                'vol_stop_mult': vol_stop_mult,
                'drawdown_stop': drawdown_stop,
                'notes': notes,
            }
        except Exception as e:
            logger.warning(f"个性化参数计算失败(轻量): {e}")
            return {
                'tp_levels': [0.08, 0.12, 0.20],
                'tp_portions': [0.5, 0.5, 1.0],
                'trailing_distance': 0.035,
                'base_stop_loss': 0.05,
                'time_stop_days': 5,
                'vol_stop_mult': 1.5,
                'drawdown_stop': 0.06,
                'notes': 'fallback',
            }


