# 全局开关（如外部未定义则设置默认）
if 'PERSONALIZED_REPORTING_ENABLED' not in globals():
    PERSONALIZED_REPORTING_ENABLED = True
if 'PERSONALIZED_ENGINE_ENABLED' not in globals():
    PERSONALIZED_ENGINE_ENABLED = True
if 'PERSONALIZED_APPLY_ENABLED' not in globals():
    # 开启后，个性化建议将参与执行参数（分级止盈与移动止盈保护距离）
    PERSONALIZED_APPLY_ENABLED = True

# 0.0~1.0：个性化建议的应用权重；1.0=完全采用建议，0.0=忽略建议
if 'PERSONALIZED_APPLY_WEIGHT' not in globals():
    PERSONALIZED_APPLY_WEIGHT = 1.0

def set_runtime_personalization_config(overrides: Optional[Dict[str, Any]] = None, ContextInfo=None):
    """运行时配置接口：支持热更新个性化相关的开关与权重。
    优先级：overrides > ContextInfo.personalization_config > 保持现状。
    支持的键：
      - PERSONALIZED_REPORTING_ENABLED: bool
      - PERSONALIZED_ENGINE_ENABLED: bool
      - PERSONALIZED_APPLY_ENABLED: bool
      - PERSONALIZED_APPLY_WEIGHT: float (0.0~1.0)
    """
    try:
        cfg = None
        if overrides and isinstance(overrides, dict):
            cfg = overrides
        elif ContextInfo is not None:
            cfg = getattr(ContextInfo, 'personalization_config', None)
        if not cfg:
            return

        def _coerce_bool(v, default):
            if isinstance(v, bool):
                return v
            if isinstance(v, str):
                lv = v.strip().lower()
                if lv in ('1','true','yes','on'): return True
                if lv in ('0','false','no','off'): return False
            return default

        def _coerce_weight(v, default):
            try:
                w = float(v)
                if 0.0 <= w <= 1.0:
                    return w
                return default
            except Exception:
                return default

        globals()['PERSONALIZED_REPORTING_ENABLED'] = _coerce_bool(
            cfg.get('PERSONALIZED_REPORTING_ENABLED', PERSONALIZED_REPORTING_ENABLED), PERSONALIZED_REPORTING_ENABLED)
        globals()['PERSONALIZED_ENGINE_ENABLED'] = _coerce_bool(
            cfg.get('PERSONALIZED_ENGINE_ENABLED', PERSONALIZED_ENGINE_ENABLED), PERSONALIZED_ENGINE_ENABLED)
        globals()['PERSONALIZED_APPLY_ENABLED'] = _coerce_bool(
            cfg.get('PERSONALIZED_APPLY_ENABLED', PERSONALIZED_APPLY_ENABLED), PERSONALIZED_APPLY_ENABLED)
        globals()['PERSONALIZED_APPLY_WEIGHT'] = _coerce_weight(
            cfg.get('PERSONALIZED_APPLY_WEIGHT', PERSONALIZED_APPLY_WEIGHT), PERSONALIZED_APPLY_WEIGHT)

        logger.info(
            f"?? 个性化运行时配置: REPORT={PERSONALIZED_REPORTING_ENABLED}, ENGINE={PERSONALIZED_ENGINE_ENABLED}, "
            f"APPLY={PERSONALIZED_APPLY_ENABLED}, WEIGHT={PERSONALIZED_APPLY_WEIGHT:.2f}"
        )
    except Exception as e:
        logger.debug(f"运行时个性化配置更新失败: {e}")

def _get_env_personalization_defaults(env: str) -> dict:
    """根据市场环境返回推荐的个性化配置默认值。"""
    env = (env or 'sideways').lower()
    base = {
        'PERSONALIZED_REPORTING_ENABLED': True,
        'PERSONALIZED_ENGINE_ENABLED': True,
        'PERSONALIZED_APPLY_ENABLED': True,
        'PERSONALIZED_APPLY_WEIGHT': 0.5,  # 震荡市基线
    }
    if env == 'bull':
        base['PERSONALIZED_APPLY_WEIGHT'] = 0.7
    elif _is_bearish(env):
        base['PERSONALIZED_APPLY_WEIGHT'] = 0.3
    else:
        base['PERSONALIZED_APPLY_WEIGHT'] = 0.5
    return base

def get_default_profit_params(market_env='sideways'):
    """
    获取默认止盈参数
    
    参数:
    market_env: 市场环境 ('bull', 'bear', 'sideways')
    
    返回:
    Dict: 包含level1, level2, level3等参数的字典
    """
    # 基础默认参数
    base_params = {
        'level1': 0.08,  # 8%
        'level2': 0.12,  # 12%
        'level3': 0.20,  # 20%
        'potential_score': 0.5,
        'last_update': datetime.now().strftime('%Y%m%d'),
        'data_quality': 'default',
        'market_env': market_env,
        'algorithm': 'default_baseline'
    }
    
    # 根据市场环境调整参数
    if market_env == 'bull':
        # 牛市：提高止盈线，享受更多收益
        base_params['level1'] = base_params['level1'] * 1.2  # 6%
        base_params['level2'] = base_params['level2'] * 1.2  # 9.6%
        base_params['level3'] = base_params['level3'] * 1.2  # 18%
        base_params['potential_score'] = 0.7
        
    elif _is_bearish(market_env):
        # 熊市：降低止盈线，快速获利了结
        base_params['level1'] = base_params['level1'] * 0.8  # 4%
        base_params['level2'] = base_params['level2'] * 0.8  # 6.4%
        base_params['level3'] = base_params['level3'] * 0.8  # 12%
        base_params['potential_score'] = 0.3
        
    # sideways 保持默认值
    
    # 添加止损和止盈参数
    base_params['stop_loss'] = -5.0  # -5% 止损线
    base_params['take_profit'] = base_params['level1'] * 100  # 使用level1作为默认止盈线，转换为百分比
    
    logger.info(f"?? 获取默认止盈参数: L1={base_params['level1']:.1%}, L2={base_params['level2']:.1%}, L3={base_params['level3']:.1%} (市场环境:{market_env})")
    
    return base_params

def get_enhanced_profit_params(stock_code, market_env='sideways', use_default=False, ContextInfo=None, current_price=None, buy_price=None, current_return=0.0):
    """
    获取个性化止盈参数 - 简化版
    
    参数:
    stock_code: 股票代码
    market_env: 市场环境 ('bull', 'bear', 'sideways')
    use_default: 是否强制使用默认参数
    
    返回:
    Dict: 包含level1, level2, level3等参数的字典
    """
    global stock_personalized_profit_params
    
    try:
        # 1. 强制使用默认参数
        if use_default:
            return get_default_profit_params(market_env)
        
        # 2. 检查是否已有个性化参数且未过期
        if stock_code in stock_personalized_profit_params:
            cached_params = stock_personalized_profit_params[stock_code]
            last_update = cached_params.get('last_update', '')
            
            if last_update:
                try:
                    update_date = datetime.strptime(last_update.split()[0], '%Y%m%d')
                    days_old = (datetime.now() - update_date).days
                    if days_old <= 7:  # 参数仍然有效
                        return cached_params
                except Exception:
                    pass
        
        # 3. 动态计算新参数
        dynamic_params = dynamic_profit_calculator.calculate_dynamic_params(stock_code, market_env)
        
        if dynamic_params:
            # 缓存计算结果
            stock_personalized_profit_params[stock_code] = dynamic_params
            return dynamic_params
        
        # 4. 兜底使用默认参数
        return get_default_profit_params(market_env)
        
    except Exception as e:
        logger.error(f"? 获取个性化止盈参数失败: {e}")
        return get_default_profit_params(market_env)

# ===== 增强版容错机制函数 - 价格精度统一 =====

def align_price_to_tick(price: float, tick: float = 0.01) -> float:
    """
    将价格对齐到指定tick精度，默认0.01（两位小数）。
    """
    try:
        p = float(price)
        if tick <= 0:
            return round(p, 2)
        # 使用四舍五入到最接近的tick
        aligned = round(p / tick) * tick
        # 最终保留两位小数显示
        return round(aligned, 2)
    except Exception:
        # 回退为两位小数
        try:
            return round(float(price), 2)
        except Exception:
            return 0.00
            
def enhanced_price_validation(price, stock_code="", context_price=None):
    if not ENHANCED_PRICE_VALIDATION:
        return align_price_to_tick(price)
    
    original_price = price
    fixed = False
    
    try:
        # 检查NaN值
        if pd.isna(price):
            if context_price and not pd.isna(context_price):
                price = float(context_price)
            else:
                # 实盘安全处理：无法修复则拒绝订单
                logger.error(f"价格NaN且无参考价格，拒绝订单: {stock_code} {original_price}")
                return None  # 返回None表示价格无法修复，应拒绝订单
            fixed = True
            logger.warning(f"价格NaN修复: {stock_code} {original_price} → {price:.2f}")
        
        # 检查无穷值
        elif np.isinf(price):
            if context_price and not np.isinf(context_price):
                price = float(context_price)
            else:
                # 实盘安全处理：无法修复则拒绝订单
                logger.error(f"价格无穷值且无参考价格，拒绝订单: {stock_code} {original_price}")
                return None  # 返回None表示价格无法修复，应拒绝订单
            fixed = True
            logger.warning(f"价格无穷值修复: {stock_code} {original_price} → {price:.2f}")
        
        # 检查负值或零值
        elif price <= 0:
            if context_price and context_price > 0:
                price = float(context_price)
            else:
                # 实盘安全处理：无法修复则拒绝订单
                logger.error(f"价格非正值且无参考价格，拒绝订单: {stock_code} {original_price}")
                return None  # 返回None表示价格无法修复，应拒绝订单
            fixed = True
            logger.warning(f"价格非正值修复: {stock_code} {original_price} → {price:.2f}")
        
        # 检查价格范围
        elif price < PRICE_VALIDATION_MIN or price > PRICE_VALIDATION_MAX:
            # 限制在合理范围内
            price = max(PRICE_VALIDATION_MIN, min(PRICE_VALIDATION_MAX, price))
            fixed = True
            logger.warning(f"价格范围修复: {stock_code} {original_price} → {price:.2f}")
        
        # 检查价格异常波动
        elif context_price and abs(price - context_price) / context_price > PRICE_ANOMALY_THRESHOLD:
            # 异常波动超过30%，调整到合理范围
            if price > context_price:
                price = context_price * (1 + PRICE_ANOMALY_THRESHOLD)
            else:
                price = context_price * (1 - PRICE_ANOMALY_THRESHOLD)
            fixed = True
            logger.warning(f"价格异常波动修复: {stock_code} {original_price} → {price:.2f}")
        
        if fixed:
            global_optimization_stats['price_fixes'] += 1
        
        # 最终返回两位小数的对齐价格
        return align_price_to_tick(price)
        
    except Exception as e:
        logger.error(f"价格验证异常: {e}，拒绝订单以确保实盘安全")
        global_optimization_stats['price_fixes'] += 1
        return None  # 异常情况下拒绝订单，不使用默认价格

def enhanced_data_cleaning(data, field_name="", stock_code=""):
    """
    增强版数据清洗 - 优化3核心技术
    自动清洗NaN、无穷值、负值等异常数据
    """
    global global_optimization_stats
    
    if not DATA_CLEANING_ENABLED:
        return data
    
    try:
        if isinstance(data, (list, np.ndarray)):
            cleaned_data = []
            for i, value in enumerate(data):
                cleaned_value = value
                
                # 修复NaN值
                if AUTO_FIX_NAN_VALUES and pd.isna(value):
                    if i > 0 and len(cleaned_data) > 0:
                        cleaned_value = cleaned_data[-1]  # 使用前一个有效值
                    else:
                        # 实盘安全：无法修复则跳过或返回原数据
                        logger.warning(f"警告 数据NaN无法修复，保持原值: {field_name}[{i}] = {value}")
                        cleaned_value = value  # 保持原值，由上层函数判断如何处理
                    global_optimization_stats['data_cleanups'] += 1
                
                # 修复无穷值
                elif AUTO_FIX_INF_VALUES and np.isinf(value):
                    if i > 0 and len(cleaned_data) > 0:
                        cleaned_value = cleaned_data[-1]  # 使用前一个有效值
                    else:
                        # 实盘安全：无法修复则跳过或返回原数据
                        logger.warning(f"警告 数据无穷值无法修复，保持原值: {field_name}[{i}] = {value}")
                        cleaned_value = value  # 保持原值，由上层函数判断如何处理
                    global_optimization_stats['data_cleanups'] += 1
                
                # 修复负值（仅针对价格和成交量）
                elif AUTO_FIX_NEG_VALUES and value < 0 and field_name in ['close', 'open', 'high', 'low', 'volume']:
                    cleaned_value = abs(value) if value != 0 else (10.0 if field_name != 'volume' else 1000000)
                    global_optimization_stats['data_cleanups'] += 1
                
                cleaned_data.append(cleaned_value)
            
            return cleaned_data
        
        else:
            # 单个数值处理
            if AUTO_FIX_NAN_VALUES and pd.isna(data):
                global_optimization_stats['data_cleanups'] += 1
                return 10.0 if field_name == 'close' else 1000000
            elif AUTO_FIX_INF_VALUES and np.isinf(data):
                global_optimization_stats['data_cleanups'] += 1
                return 10.0 if field_name == 'close' else 1000000
            elif AUTO_FIX_NEG_VALUES and data < 0 and field_name in ['close', 'open', 'high', 'low', 'volume']:
                global_optimization_stats['data_cleanups'] += 1
                return abs(data) if data != 0 else (10.0 if field_name != 'volume' else 1000000)
            
            return data
    
    except Exception as e:
        logger.error(f"数据清洗异常: {e}")
        # 返回原数据，确保程序继续运行
        return data

def enhanced_memory_optimization():
    """
    增强版内存优化 - 优化2核心技术
    定期执行垃圾回收，优化内存使用
    """
    global global_optimization_stats
    
    if not MEMORY_OPTIMIZATION:
        return
    
    try:
        gc.collect()
        global_optimization_stats['memory_cleanups'] += 1
        
        # 每10次清理输出一次日志
        if global_optimization_stats['memory_cleanups'] % GC_FREQUENCY == 0:
            logger.info(f"内存优化: 已执行{global_optimization_stats['memory_cleanups']}次垃圾回收")
    
    except Exception as e:
        logger.error(f"内存优化异常: {e}")

def enhanced_api_retry(api_func, *args, max_retries=None, **kwargs):
    """
    增强版API重试机制 - 优化4核心技术
    智能重试与指数退避，确保API调用成功率
    """
    global global_optimization_stats
    
    if not ADVANCED_RETRY_MECHANISM:
        return api_func(*args, **kwargs)
    
    max_retries = max_retries or API_RETRY_MAX_ATTEMPTS
    
    for attempt in range(max_retries):
        try:
            result = api_func(*args, **kwargs)
            if attempt > 0:
                logger.info(f"API重试成功: 第{attempt + 1}次尝试")
            return result
        
        except Exception as e:
            global_optimization_stats['api_retries'] += 1
            
            if attempt < max_retries - 1:
                # 计算延迟时间
                if API_EXPONENTIAL_BACKOFF:
                    delay = API_RETRY_BASE_DELAY * (2 ** attempt)
                else:
                    delay = API_RETRY_BASE_DELAY
                
                logger.warning(f"API调用失败，第{attempt + 1}次重试，延迟{delay:.2f}秒: {e}")
                time_module.sleep(delay)
            else:
                logger.error(f"API重试失败，已达最大重试次数{max_retries}: {e}")
                raise e

def log_optimization_stats():
    """
    记录优化统计信息
    """
    stats = global_optimization_stats
    if any(stats.values()):
        logger.info(f"?? 增强版优化统计: 价格修复{stats['price_fixes']}次, "
                   f"内存清理{stats['memory_cleanups']}次, 数据清洗{stats['data_cleanups']}次, "
                   f"API重试{stats['api_retries']}次")

# ===== 资金和持仓安全检查函数 =====

def check_available_funds(context, required_amount: float) -> Dict:
    """
    检查可用资金是否足够 - 增强版本，包含多重资金获取方案
    
    参数:
    context: 策略上下文
    required_amount: 需要的资金金额
    
    返回:
    Dict: 资金检查结果
    """
    try:
        # 增强的资金获取机制 - 多重方案
        account_info = None
        fund_source = "unknown"
        
        # 方案1: 标准API调用
        try:
            account_info = get_trade_detail_data(context.accID, context.accIDType, 'ACCOUNT')  # pyright: ignore[reportUndefinedVariable]
            if account_info and len(account_info) > 0:
                fund_source = "标准API"
                logger.info(f"? 资金获取成功 - {fund_source}")
            else:
                logger.warning(f"?? 标准API返回空数据: {type(account_info)}, 长度: {len(account_info) if account_info else 0}")
        except Exception as e:
            logger.warning(f"?? 标准API调用失败: {e}")
        
        # 方案2: 重试机制 - 如果第一次失败
        if not account_info or len(account_info) == 0:
            try:
                logger.info(f"?? 启动资金获取重试机制...")
                time_module.sleep(0.5)  # 短暂等待
                account_info = get_trade_detail_data(context.accID, context.accIDType, 'ACCOUNT')  # pyright: ignore[reportUndefinedVariable]
                if account_info and len(account_info) > 0:
                    fund_source = "重试API"
                    logger.info(f"? 资金获取重试成功 - {fund_source}")
                else:
                    logger.warning(f"?? 重试API仍返回空数据")
            except Exception as e:
                logger.warning(f"?? 重试API调用失败: {e}")
        
        # 方案3: 账户状态诊断 - 如果仍然失败
        if not account_info or len(account_info) == 0:
            try:
                logger.info(f"?? 启动账户状态诊断...")
                
                # 检查账户配置
                if not hasattr(context, 'accID') or not context.accID:
                    logger.error(f"? 账户ID未配置: {getattr(context, 'accID', 'None')}")
                    return {
                        'sufficient': False,
                        'reason': '账户ID未配置或为空'
                    }
                
                if not hasattr(context, 'accIDType') or not context.accIDType:
                    logger.error(f"? 账户类型未配置: {getattr(context, 'accIDType', 'None')}")
                    return {
                        'sufficient': False,
                        'reason': '账户类型未配置或为空'
                    }
                
                logger.info(f"?? 账户配置检查:")
                logger.info(f"   账户ID: {context.accID}")
                logger.info(f"   账户类型: {context.accIDType}")
                
                # 尝试其他数据类型验证账户连接
                try:
                    test_positions = get_trade_detail_data(context.accID, context.accIDType, 'POSITION')  # pyright: ignore[reportUndefinedVariable]
                    if test_positions is not None:
                        logger.info(f"? 账户连接正常 - 持仓数据可获取")
                        fund_source = "账户连接正常但资金数据异常"
                    else:
                        logger.error(f"? 账户连接异常 - 持仓数据也无法获取")
                        return {
                            'sufficient': False,
                            'reason': '账户连接异常，无法获取任何交易数据'
                        }
                except Exception as e:
                    logger.error(f"? 账户连接测试失败: {e}")
                    return {
                        'sufficient': False,
                        'reason': f'账户连接测试失败: {e}'
                    }
                
            except Exception as e:
                logger.error(f"? 账户状态诊断失败: {e}")
        
        if account_info and len(account_info) > 0:
            # 根据API文档，使用C++对象的m_开头属性名
            account_obj = account_info[0]
            
            # 详细记录账户对象信息用于诊断
            logger.info(f"?? 账户对象类型: {type(account_obj)}")
            logger.info(f"?? 账户对象属性: {[attr for attr in dir(account_obj) if not attr.startswith('_')]}")
            
            # 获取可用资金（优化异常处理）
            available_cash = 0.0
            if hasattr(account_obj, 'm_dAvailable') and account_obj.m_dAvailable is not None:
                try:
                    available_cash = float(account_obj.m_dAvailable)
                    if available_cash > 0:
                        logger.info(f"? 从m_dAvailable获取可用资金: {available_cash}")
                    else:
                        logger.warning(f"? m_dAvailable返回异常值: {available_cash}")
                except (ValueError, TypeError):
                    logger.warning("? m_dAvailable转换失败")
            
            # 如果m_dAvailable无效，尝试m_dBalance
            if available_cash <= 0:
                if hasattr(account_obj, 'm_dBalance') and account_obj.m_dBalance is not None:
                    try:
                        balance = float(account_obj.m_dBalance)
                        if balance > 0:
                            available_cash = balance * 0.9  # 保守估计90%可用
                            logger.info(f"? 从m_dBalance估算可用资金: {available_cash} (总资产{balance}的90%)")
                        else:
                            logger.warning(f"? m_dBalance返回异常值: {balance}")
                    except (ValueError, TypeError):
                        logger.warning("? m_dBalance转换失败")
            
            # 最后的兜底处理
            if available_cash <= 0:
                logger.error("?? 无法获取有效的可用资金信息 - 所有资金字段均无效或为0")
                return {
                    'sufficient': False,
                    'available': 0.0,
                    'required': required_amount,
                    'shortage': required_amount,
                    'message': '无法获取资金信息，暂停交易'
                }
            
            # 获取总资产
            if hasattr(account_obj, 'm_dTotalAssets') and account_obj.m_dTotalAssets is not None:
                total_asset = float(account_obj.m_dTotalAssets)
                logger.info(f"? 从m_dTotalAssets获取总资产: {total_asset}")
            elif hasattr(account_obj, 'm_dBalance') and account_obj.m_dBalance is not None:
                total_asset = float(account_obj.m_dBalance)
                logger.info(f"? 从m_dBalance获取总资产: {total_asset}")
            else:
                total_asset = available_cash
                logger.warning(f"?? 使用可用资金作为总资产: {total_asset}")
            
            # 保留5%的安全资金缓冲
            safe_available = available_cash * 0.95
            
            logger.info(f"?? 资金检查({fund_source}): 可用资金{available_cash:.0f}元, 需要{required_amount:.0f}元, 安全可用{safe_available:.0f}元")
            
            if required_amount <= safe_available:
                return {
                    'sufficient': True,
                    'available_cash': available_cash,
                    'total_asset': total_asset,
                    'required_amount': required_amount,
                    'remaining_after_trade': safe_available - required_amount,
                    'fund_source': fund_source
                }
            else:
                return {
                    'sufficient': False,
                    'available_cash': available_cash,
                    'total_asset': total_asset,
                    'required_amount': required_amount,
                    'shortage': required_amount - safe_available,
                    'reason': f'资金不足，缺少{required_amount - safe_available:.0f}元',
                    'fund_source': fund_source
                }
        else:
            logger.error("? 所有资金获取方案均失败")
            return {
                'sufficient': False,
                'reason': '所有资金获取方案均失败，可能的原因：账户权限不足、券商系统异常、网络连接问题'
            }
            
    except Exception as e:
        logger.error(f"? 资金检查异常: {e}")
        return {
            'sufficient': False,
            'reason': f'资金检查异常: {e}'
        }

