                    # 统计日志 - 按6级信号分类统计
                    signal_6_count = sum(1 for s in selected_stocks if buy.get(s, 0) >= 6)
                    signal_5_count = sum(1 for s in selected_stocks if buy.get(s, 0) == 5)
                    signal_4_count = sum(1 for s in selected_stocks if buy.get(s, 0) == 4)
                    signal_3_count = sum(1 for s in selected_stocks if buy.get(s, 0) == 3)
