            fb_trial_ratio_runtime = float((fb_entry_profile or {}).get('trial_ratio', FIRST_BOARD_OPEN_TRIAL_RATIO) or FIRST_BOARD_OPEN_TRIAL_RATIO)
            fb_confirm_ratio_runtime = float((fb_entry_profile or {}).get('confirm_ratio', FIRST_BOARD_CONFIRM_POSITION_RATIO if 'FIRST_BOARD_CONFIRM_POSITION_RATIO' in globals() else FIRST_BOARD_POSITION_RATIO) or (FIRST_BOARD_CONFIRM_POSITION_RATIO if 'FIRST_BOARD_CONFIRM_POSITION_RATIO' in globals() else FIRST_BOARD_POSITION_RATIO))
            fb_env_runtime = str((fb_entry_profile or {}).get('env', 'sideways') or 'sideways')
            logger.info(f"?? 首板二段式仓位画像: env={fb_env_runtime} trial={fb_trial_ratio_runtime:.0%} confirm={fb_confirm_ratio_runtime:.0%}")
            for k in selected_stocks:
                logger.info(f"\n--- 处理股票 {k} ---")
                logger.info(f"买入信号: {buy.get(k, 0)}, 因子评分: {factor_scores.get(k, {}).get('composite_score', 'N/A'):.1f}")
                
                # 读取计划预算（若已在候选池阶段生成）
