def _get_rise_prob_cache(context) -> dict:
    """在上下文中获取/初始化上涨概率缓存。结构：{ code: { 'data': {...}, 'ts': timestamp } }"""
    try:
        cache = getattr(context, '_rise_prob_cache', None)
        if not isinstance(cache, dict):
            cache = {}
            setattr(context, '_rise_prob_cache', cache)
        return cache
    except Exception:
        # 兜底：使用模块级别临时缓存
        if not hasattr(globals(), '_GLOBAL_RISE_PROB_CACHE'):
            globals()['_GLOBAL_RISE_PROB_CACHE'] = {}
        return globals()['_GLOBAL_RISE_PROB_CACHE']

def _is_cache_valid(entry: dict, ttl_minutes: int) -> bool:
    try:
        if not entry or 'ts' not in entry:
            return False
        ts = entry['ts']
        # 使用datetime.now()，避免引入timedelta位置错误；项目已全局import
        expires = ts + timedelta(minutes=ttl_minutes)
        return datetime.now() <= expires
    except Exception:
        return False

def get_cached_rise_prob(context, stock: str, ttl_minutes: int) -> Optional[dict]:
    cache = _get_rise_prob_cache(context)
    entry = cache.get(stock)
    if entry and _is_cache_valid(entry, ttl_minutes):
        return entry.get('data')
    return None

def cache_rise_prob(context, stock: str, data: dict):
    cache = _get_rise_prob_cache(context)
    try:
        cache[stock] = {'data': data, 'ts': datetime.now()}
    except Exception:
        pass

def compute_or_get_cached_rise_prob(context, stock: str, cfg: dict) -> dict:
    ttl = int(cfg.get('ttl_minutes', 30))
    cached = get_cached_rise_prob(context, stock, ttl)
    if cached is not None:
        return cached
    data = compute_t0_t1_rise_probabilities(
        context,
        stock,
        lookback=int(cfg.get('lookback', 180)),
        min_samples=int(cfg.get('min_samples', 15)),
    )
    cache_rise_prob(context, stock, data)
    return data

