def compute_intraday_t0_momentum(context, stock: str, period: str = '5m', bars: int = 24) -> dict:
    """基于分时数据估算当日T+0动量，返回 {score:[0,1], ret:浮动, v_accel:量能加速}。
    依赖：get_market_data_ex(context, [codes], ['close','volume'], period, count)
    """
    try:
        data = get_market_data_ex(context, [stock], ['close', 'volume'], period=period, count=bars)
        # 支持两种返回：dict->DataFrame 或 简单list[dict]
        closes = []
        vols = []
        if isinstance(data, dict) and stock in data and hasattr(data[stock], 'empty') and not data[stock].empty:
            df = data[stock]
            closes = df['close'].dropna().tolist() if 'close' in df else []
            vols = df['volume'].dropna().tolist() if 'volume' in df else []
        elif isinstance(data, list):
            closes = [row.get('close') for row in data if row.get('close') is not None]
            vols = [row.get('volume') for row in data if row.get('volume') is not None]
        if len(closes) < 3:
            return {'score': 0.5, 'ret': 0.0, 'v_accel': 0.0, 'ok': False}
        # 计算分时收益与量能加速
        ret = (closes[-1] / closes[0] - 1.0) if closes[0] else 0.0
        mid = len(vols) // 2
        if mid > 0 and len(vols) > mid:
            v1 = sum(vols[:mid]) / mid if sum(vols[:mid]) else 0.0
            v2 = sum(vols[mid:]) / (len(vols) - mid) if sum(vols[mid:]) else 0.0
            v_accel = _safe_div(v2, v1, 0.0) - 1.0 if v1 > 0 else 0.0
        else:
            v_accel = 0.0
        # 评分：ret权重0.7，v_accel权重0.3，映射到[0,1]
        ret_score = max(0.0, min(1.0, 0.5 + ret * 10))  # +1%≈+0.1分
        va_score = max(0.0, min(1.0, 0.5 + v_accel * 1.0))
        score = max(0.0, min(1.0, ret_score * 0.7 + va_score * 0.3))
        return {'score': score, 'ret': ret, 'v_accel': v_accel, 'ok': True}
    except Exception as e:
        logger.debug(f"分时T0动量计算失败 {stock}: {e}")
        return {'score': 0.5, 'ret': 0.0, 'v_accel': 0.0, 'ok': False}

