def compute_gap_continuation_stats(context, stock: str, lookback: int = 180, min_samples: int = 8) -> dict:
    """统计向上跳空后次日上涨的延续概率。返回 {gap_up:bool, cont_prob:float, samples:int}。
    gap_up 定义：today.open > yesterday.high。
    """
    try:
        hist = get_market_data_ex(context, [stock], ['open', 'close', 'high', 'low'], period='1d', count=lookback + 2)
        rows = []
        if isinstance(hist, dict) and stock in hist and hasattr(hist[stock], 'empty') and not hist[stock].empty:
            df = hist[stock]
            for _, r in df.iterrows():
                rows.append({'open': r.get('open'), 'close': r.get('close'), 'high': r.get('high'), 'low': r.get('low')})
        elif isinstance(hist, list):
            rows = hist
        if len(rows) < 3:
            return {'gap_up': False, 'cont_prob': 0.5, 'samples': 0}
        # 当前是否跳空
        y, t = rows[-2], rows[-1]
        if any(v is None for v in [y.get('high'), t.get('open')]):
            gap_now = False
        else:
            gap_now = t['open'] > y['high']
        # 历史跳空延续统计
        cont_up, cnt = 0, 0
        for i in range(len(rows) - 2):
            d0, d1 = rows[i], rows[i + 1]
            if d0.get('high') is None or d1.get('open') is None:
                continue
            if d1['open'] > d0['high']:
                # 次日是否延续（d2相对d1）
                if i + 2 < len(rows):
                    d2 = rows[i + 2]
                    if d2.get('close') is not None and d1.get('close') is not None:
                        cont_up += 1 if d2['close'] > d1['close'] else 0
                        cnt += 1
        prob = (cont_up / cnt) if cnt > 0 else 0.5
        return {'gap_up': bool(gap_now), 'cont_prob': prob, 'samples': cnt}
    except Exception as e:
        logger.debug(f"跳空延续统计失败 {stock}: {e}")
        return {'gap_up': False, 'cont_prob': 0.5, 'samples': 0}

