def evaluate_loss_making_stock(stock_code, context):
    """
    评估亏损股票的投资价值
    
    参数:
    stock_code: 股票代码
    context: 策略上下文
    
    返回:
    Dict: 评估结果
    """
    try:
        evaluation = {
            'is_loss_making': False,
            'investment_value': 'unknown',
            'risk_level': 'medium',
            'recommendation': 'neutral',
            'reasons': [],
            'score': 0.5
        }
        
        # 获取合约详细信息
        try:
            # 使用正确的API调用方式获取合约信息
            instrument_detail = get_instrumentdetail(stock_code, context) if 'get_instrumentdetail' in globals() else None
            
            # 获取涨停价、跌停价等信息用于后续分析
            up_stop_price = instrument_detail.get('UpStopPrice', 0) if instrument_detail else 0
            down_stop_price = instrument_detail.get('DownStopPrice', 0) if instrument_detail else 0
            pre_close = instrument_detail.get('PreClose', 0) if instrument_detail else 0
            
            # 基于股票代码和行业进行初步判断
            stock_prefix = stock_code[:3]
            
            # 成长型亏损股票识别
            growth_sectors = ['300', '688']  # 创业板、科创板
            ai_keywords = ['人工智能', '芯片', '半导体', '新能源', '生物医药', '云计算']
            
            if stock_prefix in growth_sectors:
                evaluation['investment_value'] = 'potential_growth'
                evaluation['recommendation'] = 'consider'
                evaluation['reasons'].append('成长板块股票，可能处于投入期')
                evaluation['score'] += 0.2
            
            # 传统行业亏损股票
            traditional_sectors = ['000', '001', '002', '600', '601', '603']
            if stock_prefix in traditional_sectors:
                evaluation['investment_value'] = 'value_or_cyclical'
                evaluation['recommendation'] = 'cautious'
                evaluation['reasons'].append('传统行业股票，需关注周期性因素')
                evaluation['score'] += 0.1
            
            # 获取技术面强度作为补充
            try:
                hist_data = context.get_market_data_ex(fields=['close'], stock_code=[stock_code], period='1d', count=20, dividend_type='none', fill_data=True)
                if hist_data and stock_code in hist_data and len(hist_data[stock_code]) >= 10:
                    recent_data = hist_data[stock_code][-10:]
                    price_trend = (recent_data[-1].close - recent_data[0].close) / recent_data[0].close
                    
                    if price_trend > 0.15:  # 近期涨幅>15%
                        evaluation['recommendation'] = 'positive'
                        evaluation['reasons'].append(f'近期强势上涨{price_trend:.1%}，技术面良好')
                        evaluation['score'] += 0.3
                    elif price_trend < -0.20:  # 近期跌幅>20%
                        evaluation['risk_level'] = 'high'
                        evaluation['reasons'].append(f'近期大幅下跌{price_trend:.1%}，技术面较弱')
                        evaluation['score'] -= 0.2
            except:
                pass
            
        except Exception as e:
            logger.debug(f"获取{stock_code}财务数据失败: {e}")
            evaluation['reasons'].append('无法获取详细财务数据，基于技术面分析')
        
        # 综合评分
        if evaluation['score'] >= 0.7:
            evaluation['recommendation'] = 'buy'
        elif evaluation['score'] >= 0.5:
            evaluation['recommendation'] = 'consider'
        elif evaluation['score'] >= 0.3:
            evaluation['recommendation'] = 'cautious'
        else:
            evaluation['recommendation'] = 'avoid'
        
        return evaluation
        
    except Exception as e:
        logger.error(f"评估{stock_code}亏损股票价值失败: {e}")
        return {
            'is_loss_making': False,
            'investment_value': 'unknown',
            'risk_level': 'high',
            'recommendation': 'avoid',
            'reasons': ['评估失败'],
            'score': 0.0
        }

def test_price_type_support(context, stock_code, test_amount=100):
    """
    测试不同价格类型的支持情况
    用于在策略初始化时检测券商柜台支持的价格类型
    
    参数:
    context: 策略上下文
    stock_code: 股票代码
    test_amount: 测试数量（股）
    
    返回:
    dict: 支持的价格类型列表和详细信息
    """
    logger.info(f"?? 开始测试 {stock_code} 价格类型支持情况...")
    
    # 测试的价格类型（按优先级排序，优先测试卖一价）
    test_types = [
        {'pr_type': 4, 'name': '卖1价', 'priority': 1},  # 优先测试卖一价，提高成交率
        {'pr_type': 6, 'name': '买1价', 'priority': 2},
        {'pr_type': 11, 'name': '指定价', 'priority': 3},
        {'pr_type': 5, 'name': '最新价', 'priority': 4},
        {'pr_type': 12, 'name': '涨跌停价', 'priority': 5}
    ]
    
    supported_types = []
    failed_types = []
    
    try:
        # 获取账户信息
        account_id = context.accID
        order_type = 1101  # 普通下单
        
        # 获取当前价格作为参考
        try:
            tick_data = context.get_full_tick([stock_code])
            if tick_data and stock_code in tick_data:
                current_price = float(tick_data[stock_code]['lastPrice'])
                test_price = max(current_price, 0.01)
            else:
                test_price = 10.0  # 默认测试价格
        except:
            test_price = 10.0
        
        logger.info(f"?? 测试价格: {test_price}元, 测试数量: {test_amount}股")
        
        for test_info in test_types:
            pr_type = test_info['pr_type']
            name = test_info['name']
            priority = test_info['priority']
            
            try:
                logger.info(f"?? 测试 {name}(prType={pr_type})...")
                
                # 根据价格类型设置价格（修复API调用）
                if pr_type == 11:  # 指定价
                    order_price = test_price
                elif pr_type == 5:  # 最新价
                    order_price = 0  # 柜台通常要求占位传0
                elif pr_type in [4, 6]:  # 卖1价、买1价
                    order_price = 0  # 盘口价格占位使用0
                else:
                    order_price = 0  # 其他无需固定价的类型占位使用0
                
                # 执行测试下单（小额测试）
                result = passorder(
                    23,                    # 参数1: 操作类型 (买入)
                    order_type,            # 参数2: 下单方式
                    account_id,            # 参数3: 资金账号
                    stock_code,            # 参数4: 股票代码
                    pr_type,               # 参数5: 价格类型
                    order_price,           # 参数6: 下单价格
                    test_amount,           # 参数7: 下单数量
                    "stock_strategy",      # 参数8: 策略名称(可选)
                    0,                     # 参数9: 不立即下单(可选)
                    "价格类型测试",        # 参数10: 用户委托ID(可选)
                    context                # 参数11: ContextInfo(必须最后)
                )
                
                # 成功判定：部分柜台返回正整数委托号，也有柜台返回0表示成功
                if (isinstance(result, int) and (result > 0 or result == 0)):
                    supported_types.append({
                        'pr_type': pr_type,
                        'name': name,
                        'priority': priority,
                        'status': 'supported'
                    })
                    logger.info(f"? {name}(prType={pr_type}) 支持")
                else:
                    failed_types.append({
                        'pr_type': pr_type,
                        'name': name,
                        'priority': priority,
                        'status': 'failed',
                        'error_code': result
                    })
                    logger.warning(f"? {name}(prType={pr_type}) 不支持，错误码: {result}")
                    
            except Exception as e:
                failed_types.append({
                    'pr_type': pr_type,
                    'name': name,
                    'priority': priority,
                    'status': 'error',
                    'error': str(e)
                })
                logger.error(f"?? {name}(prType={pr_type}) 测试异常: {e}")
        
        # 生成测试报告
        logger.info(f"?? {stock_code} 价格类型支持测试完成")
        logger.info(f"? 支持的类型: {len(supported_types)}个")
        logger.info(f"? 不支持的类型: {len(failed_types)}个")
        
        # 按优先级排序支持的类型
        supported_types.sort(key=lambda x: x['priority'])
        
        if supported_types:
            logger.info("?? 推荐使用的价格类型顺序:")
            for i, supported in enumerate(supported_types, 1):
                logger.info(f"   {i}. {supported['name']}(prType={supported['pr_type']})")
        
        return {
            'stock_code': stock_code,
            'supported_types': supported_types,
            'failed_types': failed_types,
            'test_price': test_price,
            'test_amount': test_amount,
            'recommended_sequence': [t['pr_type'] for t in supported_types]
        }
        
    except Exception as e:
        logger.error(f"?? 价格类型支持测试失败: {e}")
        return {
            'stock_code': stock_code,
            'supported_types': [],
            'failed_types': [],
            'error': str(e)
        }

def validate_price_type_before_order(context, stock_code, pr_type, price, action="buy"):
    """
    下单前验证价格类型是否可用
    
    参数:
    context: 策略上下文
    stock_code: 股票代码
    pr_type: 价格类型
    price: 价格
    action: 交易方向
    
    返回:
    dict: 验证结果
    """
    try:
        # 获取实时行情
        tick_data = context.get_full_tick([stock_code])
        if not tick_data or stock_code not in tick_data:
            return {
                'valid': False,
                'reason': '无法获取实时行情',
                'suggestion': '使用买1价(prType=6)'
            }
        
        current_price = float(tick_data[stock_code]['lastPrice'])
        bid_price = float(tick_data[stock_code].get('bidPrice1', current_price))
        ask_price = float(tick_data[stock_code].get('askPrice1', current_price))
        
        # 验证价格类型
        if pr_type == 6:  # 买1价
            if bid_price <= 0:
                return {
                    'valid': False,
                    'reason': '买1价无效',
                    'suggestion': '使用指定价(prType=11)'
                }
        elif pr_type == 5:  # 最新价
            if current_price <= 0:
                return {
                    'valid': False,
                    'reason': '最新价无效',
                    'suggestion': '使用买1价(prType=6)'
                }
        elif pr_type == 11:  # 指定价
            if price <= 0:
                return {
                    'valid': False,
                    'reason': '指定价无效',
                    'suggestion': '使用买1价(prType=6)'
                }
        
        return {
            'valid': True,
            'current_price': current_price,
            'bid_price': bid_price,
            'ask_price': ask_price
        }
        
    except Exception as e:
        return {
            'valid': False,
            'reason': f'验证异常: {e}',
            'suggestion': '使用买1价(prType=6)'
        }

